const authored:DocEntry[]=[
 {id:"icon-button",name:"IconButton",group:"Actions",summary:"The lamp. The housing takes the depth ladder; the icon carries the state — unlit at rest, lit on hover, brighter on press — and the label, when there is one, never rides that ramp. Round and 42px when icon-only; a labelled one is a CTA, so it is a pill at the large control height with a glyph scaled to match the label.",code:`import { IconButton } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* Icon-only needs a name — there is no text node to read. */}\n<IconButton icon={<PlayIcon />} aria-label="Play" />\n\n{/* Labelled: the icon glows, the label holds its ink. */}\n<IconButton icon={<WhatsAppIcon />} label="Message us" tone="whatsapp-quiet" />\n\n{/* Social links render as anchors. */}\n<IconButton icon={<LinkedInIcon />} href="/linkedin" aria-label="LinkedIn" tone="linkedin" />`,options:[["tone",`"neutral" | "papaya" | "azure" | "invert"`,<>The surface and filled housings. <code>neutral</code> is the surface button and its lamp lights green; the other three are filled housings, where the lamp lights white because papaya on papaya is invisible.</>],["tone",`"whatsapp" | "facebook" | "instagram" | "x" | "linkedin" | "youtube"`,<>The filled channel tones — each carries its platform's own colour as the housing's fill. Reach for one when the button <em>is</em> the call to action.</>],["tone",`"whatsapp-quiet" | "facebook-quiet" | "instagram-quiet" | "x-quiet" | "linkedin-quiet" | "youtube-quiet"`,<>The quiet form of each channel: a carved surface housing whose lamp lights that platform's colour. This is the one for a <strong>row</strong> of channels — a footer's social links, a contact strip — because six filled discs is a wall of fills, while six quiet ones read as one material with six different lights in it.</>],["label",`ReactNode`,<>Absent leaves it round and 42px. Present turns it into a pill at the large control height with the glyph scaled to the label — a labelled icon button is a CTA, not an affordance.</>],["href",`string`,<>Renders an anchor instead of a button. Anchor attributes such as <code>target</code> and <code>rel</code> pass through with it.</>],["renderLink",`(props: { className, href, style, children }) => ReactNode`,<>Hand your router the anchor. Only <code>className</code>, <code>href</code>, <code>style</code> and <code>children</code> reach it — the same four <a href="#button">Button</a> and <a href="#social-button">SocialButton</a> pass. <code>style</code> carries the <code>glow</code> colour, so spread it or the lamp lights the tone&rsquo;s colour instead of yours. Ignored without <code>href</code>.</>],["glow",`string`,<>Any CSS colour, overriding the tone's lamp. It is mixed at the <code>--td-glow-*</code> strengths, so a custom colour still rides the same rest / hover / press ladder.</>],],notes:[<><strong>An internal link goes through <code>renderLink</code>.</strong> <code>href</code> alone is a plain <code>&lt;a&gt;</code>, which is right for a social link out to somebody else&rsquo;s platform and wrong for a route inside your own app. The four things it receives are the four the whole library passes; put <code>target</code>, <code>rel</code> and your <code>aria-*</code> on your own element.</>,<><strong>An icon-only button needs a name.</strong> With no <code>label</code>, pass <code>aria-label</code> or <code>aria-labelledby</code> — there is no text node for a screen reader to read. The component logs a warning when neither is there.</>,<><strong>The icon has to be filled.</strong> Pass a library glyph at <code>LAMP_WEIGHT</code>. A glow traces the alpha edge of what it lights, so an outline mark glows as a hollow outline and reads as a smudge.</>,<><strong>Only the icon moves.</strong> The housing takes the depth ladder and the label holds its ink in every state. If you find yourself recolouring the label on hover, the component is being used against its grain.</>,<>Everything else is the native element — <code>disabled</code>, <code>onClick</code>, <code>type</code>, <code>title</code> and the rest pass straight through to the button or the anchor.</>,],preview:<div style={{display:"flex",flexDirection:"column",gap:20}}><div className="row" style={{gap:12,flexWrap:"wrap",alignItems:"center"}}><IconButton icon={LAMP_ICON} aria-label="Play"/><IconButton icon={LAMP_ICON} aria-label="Brand action" tone="papaya"/><IconButton icon={LAMP_ICON} aria-label="Accent action" tone="azure"/><IconButton icon={LAMP_ICON} aria-label="Inverted action" tone="invert"/><IconButton icon={LAMP_ICON} aria-label="Disabled" disabled/></div><div className="row" style={{gap:12,flexWrap:"wrap",alignItems:"center"}}><IconButton icon={LAMP_ICON} label="Message us" tone="whatsapp-quiet"/><IconButton icon={LAMP_ICON} label="Book a call" tone="papaya"/><IconButton icon={LAMP_ICON} label="Read the brief"/></div><div className="row" style={{gap:12,flexWrap:"wrap",alignItems:"center"}}><IconButton icon={LAMP_ICON} href="#icon-button" aria-label="WhatsApp" tone="whatsapp"/><IconButton icon={LAMP_ICON} href="#icon-button" aria-label="LinkedIn" tone="linkedin"/><IconButton icon={LAMP_ICON} href="#icon-button" aria-label="Facebook" tone="facebook"/><IconButton icon={LAMP_ICON} href="#icon-button" aria-label="Instagram" tone="instagram"/><IconButton icon={LAMP_ICON} href="#icon-button" aria-label="X" tone="x"/><IconButton icon={LAMP_ICON} href="#icon-button" aria-label="YouTube" tone="youtube"/></div><p className="hint" style={{margin:0}}>Hover and press each one — only the icon's colour and glow move. The label never does.</p></div>},
 {id:"site-navigation",name:"SiteNavigation",group:"Navigation",summary:"The public site header, and the one mith.tech runs in production. Brand, a row of links and mega-menu triggers, and an actions slot. Sticky, retracting on the way down and returning on the way up, flush when stuck. Each panel is one fixed size its content fills rather than a size its content drives.",code:`import { SiteNavigation } from "@mithtech-bengaluru/tonaldepth-react";\n\n<SiteNavigation\n  brand={<a href="/">Mithtech</a>}\n  actions={<Button size="sm">Talk to us</Button>}\n  items={[\n    { kind: "link", label: "Pricing", href: "/pricing" },\n    {\n      kind: "menu",\n      id: "services",\n      label: "Services",\n      title: "What we run",\n      description: "Implementation, integration and managed operations.",\n      content: <ServicesPanel />,\n    },\n  ]}\n/>`,options:[["items[].kind",`"link" | "menu"`,<>A <code>link</code> is a flat anchor in the bar. A <code>menu</code> is a mega-panel trigger and carries <code>id</code>, <code>title</code>, an optional <code>description</code>, <code>cta</code> and <code>footer</code>, and the <code>content</code> that fills the sheet.</>],["retract",`boolean · default true`,<>Retract on the way down, return on the way up. Off pins the bar in place.</>],["revealFloor",`number · default 140`,<>The scroll depth below which the bar is always present, whichever way the page is moving. Keeps the header from flickering at the top of a page.</>],],notes:[<><strong>This is the header the marketing site actually ships.</strong> mith.tech’s <code>Navbar</code> is this component with site copy poured into it — the sticking, the retract, the <code>--nav-offset</code> publishing and the fixed panel size all live here rather than in the site. Panel <em>content</em> stays with the site, because the library has no business holding a list of the industries someone sells into.</>,<><strong>Not <a href="#desktop-navigation">DesktopNavigation</a>.</strong> That one is the bar inside a signed-in product: a flat row of links, no panels, no scroll behaviour, no router seam. This one is for a public page. They look alike at a glance because a header is a header; what separates them is that only this one has panels, sticky retract and <code>renderLink</code>.</>,<><strong>A panel is one fixed size its content fills</strong> — not a size its content drives. Two triggers beside each other must not open two differently shaped sheets, so write the content to the panel rather than sizing the panel to the content.</>,<><strong>Hand your router the anchor.</strong> A <code>link</code> item takes <code>renderLink</code>, which is given the class and the href and returns the element — Next's <code>Link</code>, React Router's <code>Link</code>. Without it every internal link is a document load. The navigation keeps ownership of the class and the aria state.</>,<>A menu's <code>cta</code> takes the element rather than a href for the same reason: you supply the anchor, so the router owns it.</>,<><code>actions</code> is the slot for the theme toggle and the primary call to action. <code>children</code> render between the bar and the panels — that is where a mobile drawer goes.</>,<><code>label</code> names the navigation landmark and <code>closeLabel</code> names each panel's close button. Both are screen-reader text, so translate them with the rest of the page.</>,<><strong>The sheet&rsquo;s scrim is portalled to <code>document.body</code>, and it has to be.</strong> The header carries the retract transform, and a transformed element becomes the containing block for its <code>position: fixed</code> descendants — so rendered in place the scrim&rsquo;s <code>inset: 0</code> resolved against the 86px bar and covered the bar alone, while the new backdrop root left <code>backdrop-filter</code> computing to <code>none</code>. That shipped in <code>0.1.0-alpha.26</code> and read as &ldquo;the mega menu buttons aren&rsquo;t working&rdquo;. <a href="#overlays">Overlays</a> carries the rule; it applies to anything you build that has to cover the page.</>,<>Because the scrim is outside the header, it is outside the header&rsquo;s stacking context too: it sits at <code>z-index: 30</code> against the consumer&rsquo;s own page furniture. Where a page keeps something above that, raise <code>--td-react-sitenav-scrim-z</code> rather than restyling the scrim.</>,],preview:<div style={{position:"relative",minHeight:180}}><SiteNavigation retract={false} brand={<a href="#site-navigation" style={{fontFamily:"var(--td-font-display)",fontSize:22,letterSpacing:"0.02em"}}>MITHTECH</a>} actions={<><ThemeToggle/><Button variant="primary" size="sm">Talk to us</Button></>} items={[{kind:"link",label:"Pricing",href:"#site-navigation"},{kind:"link",label:"Work",href:"#site-navigation",current:true},{kind:"menu",id:"services",label:"Services",title:"What we run",description:"Implementation, integration and managed operations — on open source, with the source in your hands.",cta:<a className="td-mega-cta" href="#site-navigation">All services</a>,footer:<MegaActions><a className="td-cta" href="#site-navigation">Pricing</a><Button variant="primary" size="sm">Talk to us</Button></MegaActions>,content:<MegaGrid><FeatureCard tone="brand" icon={ICON_DEMO} title="ERPNext" href="#site-navigation" points={["Discovery to go-live","Data migration"]}>The full rollout, run by the people who stay.</FeatureCard><FeatureCard tone="accent" icon={ICON_DEMO} title="Medusa" href="#site-navigation" points={["Headless catalogue","Payments and tax"]}>Commerce, front and back.</FeatureCard><FeatureCard tone="green" icon={ICON_DEMO} title="n8n" href="#site-navigation" points={["Event-driven flows"]}>The wiring between the systems.</FeatureCard><FeatureCard tone="brand" icon={ICON_DEMO} title="Plane" href="#site-navigation" points={["GitHub sync"]}>Engineering execution without the SaaS.</FeatureCard><FeatureCard tone="accent" icon={ICON_DEMO} title="Cal.com" href="#site-navigation" points={["Self-hosted booking"]}>Scheduling inside your perimeter.</FeatureCard><FeatureCard tone="green" icon={ICON_DEMO} title="Managed ops" href="#site-navigation" points={["24×7 on-call"]}>After go-live, for as long as you want us.</FeatureCard></MegaGrid>},{kind:"menu",id:"platforms",label:"Platforms",title:"Where it runs",description:"Same stack, three grounds. The choice is compliance and cost, not capability.",footer:<MegaActions><a className="td-cta" href="#site-navigation">Pricing</a><Button variant="primary" size="sm">Talk to us</Button></MegaActions>,content:<MegaGrid><FeatureCard tone="brand" icon={ICON_DEMO} title="Hetzner" href="#site-navigation" points={["Bare metal, EU"]}>Where most of it runs.</FeatureCard><FeatureCard tone="accent" icon={ICON_DEMO} title="AWS" href="#site-navigation" points={["When compliance asks"]}>The same stack, a different bill.</FeatureCard><FeatureCard tone="green" icon={ICON_DEMO} title="On-prem" href="#site-navigation" points={["Your rack, your rules"]}>For data that cannot leave.</FeatureCard></MegaGrid>},{kind:"menu",id:"knowledge",label:"Knowledge",title:"What we have written down",description:"Guides, comparisons and the engagements behind them.",footer:<MegaActions><a className="td-cta" href="#site-navigation">Pricing</a><Button variant="primary" size="sm">Talk to us</Button></MegaActions>,content:<MegaCascade groups={[{id:"guides",label:"Guides",icon:<ICube/>,branches:[{id:"erp",title:"ERP",hint:"Process, hosting, tuning",href:"#site-navigation",items:[{href:"#site-navigation",title:"ERPNext in 90 days"},{href:"#site-navigation",title:"Data migration from Tally"},{href:"#site-navigation",title:"Choosing your modules"}]},{id:"commerce",title:"Commerce",hint:"Storefront and checkout",items:[{href:"#site-navigation",title:"Medusa vs Shopify"},{href:"#site-navigation",title:"Gateways in India"}]}]},{id:"work",label:"Case studies",icon:<IList/>,branches:[{id:"retail",title:"Retail",hint:"What shipped, and what it cost",items:[{href:"#site-navigation",title:"Commercely replatform",detail:"Retail"},{href:"#site-navigation",title:"Rework Industries",detail:"Manufacturing"}]}]}]}/>}]}/></div>},
 {id:"footer",name:"Footer",group:"Navigation",summary:"The site footer, composed rather than configured: a brand band, link columns, a recessed contact well, a social row and a bottom bar. Each part is its own export, so a site takes the pieces it needs.",code:`import { Footer, FooterGrid, FooterBrand, FooterColumn, FooterContact, FooterBottom } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Footer>\n  <FooterGrid>\n    <FooterBrand name="Mithtech" href="/">\n      Open-source implementation for SMEs.\n    </FooterBrand>\n    <FooterColumn title="Services" links={[{ href: "/erpnext", label: "ERPNext" }]} />\n    <FooterColumn title="Company" links={[{ href: "/work", label: "Work" }]} />\n  </FooterGrid>\n\n  {/* The contact well sits BELOW the grid, not inside it — as a column\n      it squeezes an address into ~130px. */}\n  <FooterContact items={[{ key: "Email", value: "hello@mith.tech" }]} />\n\n  <FooterBottom note="© 2026 Mithtech" links={[{ href: "/privacy", label: "Privacy" }]} />\n</Footer>`,notes:[<><strong>Seven exports, taken as needed.</strong> <code>Footer</code> is the landmark; <code>FooterGrid</code> lays out the brand band and the link columns; <code>FooterBrand</code>, <code>FooterColumn</code>, <code>FooterContact</code>, <code>FooterSocial</code> and <code>FooterBottom</code> are the parts.</>,<><strong>FooterBrand</strong> takes <code>name</code>, an optional <code>href</code>, <code>renderLink</code>, and the standing description as children.</>,<><strong>FooterColumn</strong> takes <code>title</code>, <code>links</code> as a list of href and label, and <code>renderLink</code>.</>,<><strong>FooterContact</strong> takes <code>label</code> and <code>items</code>, each a <code>key</code> such as Email or Phone and a <code>value</code>. It goes <em>below</em> the grid, not inside it — as a column it squeezes an address into about 130px.</>,<><strong>FooterBottom</strong> takes the legal <code>note</code>, a <code>social</code> node, <code>links</code> and <code>renderLink</code>.</>,<><strong><code>FooterSocial</code> is the row that goes in that <code>social</code> slot.</strong> It supplies placement and nothing else: pass <a href="#social-button">SocialButton</a>s. Reach for <code>tone="surface"</code> here — the carved housing every other control uses, with the mark in the platform’s colour arriving on hover. A footer row of five or six saturated chips out-shouts the page they close, and the colour stays one glance away rather than gone. The default <code>brand</code> tone belongs where there are two or three and recognition is the point, as on a <a href="#profile-card">ProfileCard</a>. Give the row a <code>label</code>: that becomes its <code>aria-label</code>, which is the only name a screen reader has for a group of icon-only links.</>,<><strong>renderLink is the prop that matters here.</strong> A footer is where the whole link inventory lives, so this is what decides whether sixty internal links route through the framework or fall back to document loads. The footer owns the markup around the anchor; this owns the anchor.</>,<><code>label</code> on <code>Footer</code> names the contentinfo landmark.</>,],preview:<Footer><FooterGrid><FooterBrand name="Mithtech" href="#footer">Open-source implementation for SMEs — Frappe, Medusa and n8n, run by the people who will still be here in year three.</FooterBrand><FooterColumn title="Services" links={[{href:"#footer",label:"ERPNext"},{href:"#footer",label:"Commerce"},{href:"#footer",label:"Automation"}]}/><FooterColumn title="Company" links={[{href:"#footer",label:"Work"},{href:"#footer",label:"Contact"}]}/></FooterGrid><FooterContact items={[{key:"Email",value:"hello@mith.tech"},{key:"Phone",value:"+91 90087 70738"},{key:"Office",value:"Bengaluru"},{key:"Hours",value:"Mon–Fri, 09:30–18:30 IST"}]}/><FooterBottom note="© 2026 Mithtech Innovative Solutions Private Limited" social={<FooterSocial label="Mithtech on social media"><SocialButton network="linkedin" tone="surface" size="sm" href="#footer" label="Mithtech on LinkedIn"/><SocialButton network="instagram" tone="surface" size="sm" href="#footer" label="Mithtech on Instagram"/><SocialButton network="x" tone="surface" size="sm" href="#footer" label="Mithtech on X"/><SocialButton network="youtube" tone="surface" size="sm" href="#footer" label="Mithtech on YouTube"/><SocialButton network="github" tone="surface" size="sm" href="#footer" label="Mithtech on GitHub"/></FooterSocial>} links={[{href:"#footer",label:"Privacy"},{href:"#footer",label:"Terms"}]}/></Footer>},
 {id:"article-card",name:"ArticleCard",group:"Marketing & editorial",summary:"Blog and knowledge cards: an optional cover, a category eyebrow, a title that is the whole-card link, an excerpt, an “In this piece” well holding the tools, files and datasets the piece carries, and a date + read-time meta line.",code:`import { ArticleCard, ArticleCardGrid } from "@mithtech-bengaluru/tonaldepth-react";\n\n// What the piece carries, in the order the reader should meet it. The kind\n// picks the chip's glyph and the category colour it holds; meta is the\n// machine face — a format, a size, a running state — and is set in mono.\n// Leave meta off where there is no machine value to report.\n//\n//   live         a tool that runs in the page          green\n//   download     a file the reader takes away          azure\n//   data         the numbers behind the piece, raw     violet\n//   interactive  something the reader operates         papaya\n\nconst assets = [\n  { kind: "live", label: "Cost calculator", href: "#calculator", meta: "live" },\n  { kind: "download", label: "Line-item sheet", href: "/line-items.xlsx", meta: "xlsx · 84 kb", download: true },\n  { kind: "data", label: "11-engagement dataset", href: "/engagements.csv", meta: "csv", download: true },\n  { kind: "interactive", label: "Scoping checklist", href: "#checklist" },\n];\n\n<ArticleCardGrid>\n  <ArticleCard\n    href="/blog/erpnext-implementation-cost"\n    eyebrow="Cost &amp; hosting"\n    title="What an ERPNext implementation actually costs in India"\n    excerpt="Eleven engagements, the line items that moved."\n    assets={assets}\n    assetsLabel="In this piece"\n    date="14 Jul 2026"\n    readTime="9 min"\n    author={{ name: "Manoj Bhat", initials: "MB" }}\n  />\n</ArticleCardGrid>`,options:[["assets[].kind",`"live" | "download" | "data" | "interactive"`,<>What the reader gets, which picks the chip's glyph and the category colour. <code>live</code> is a tool that runs in the page — green. <code>download</code> is a file taken away — azure. <code>data</code> is the numbers behind the piece, offered raw — violet. <code>interactive</code> is something operated rather than read — papaya.</>],["href",`string`,<>Makes the title the whole-card link and turns on the card's link affordance. Omit it and the card drops the affordance rather than pointing nowhere.</>],["renderLink",`(props: { className, href, children }) => ReactNode`,<>Hand your router the anchor. Given the class and the href, return the element — <em>without it every card is a document load</em>. The card keeps ownership of the class; you own the element. Ignored without <code>href</code>.</>],["assetsLabel",`ReactNode · default "In this piece"`,<>The well's heading. Rename it when the strip holds something the default sentence does not describe.</>],],notes:[<><strong>Hand your router the anchor.</strong> <code>href</code> alone renders a plain <code>&lt;a&gt;</code>, which in a SPA is a full page load out of a grid of cards. <code>renderLink</code> takes the class and the href and returns the element — Next&rsquo;s <code>Link</code>, React Router&rsquo;s <code>Link</code>. Every component in the library that takes an <code>href</code> takes this too; a test holds the pair together, because the three cards shipped without it and nobody noticed until a whole homepage was loading documents. It covers the card&rsquo;s own link and nothing else: an asset chip in the &ldquo;In this piece&rdquo; well stays a plain anchor, because most of them are downloads or someone else&rsquo;s host and the chip&rsquo;s colour rides a <code>data-kind</code> attribute this signature has nowhere to put.</>,<><strong>The assets well only appears when there is something in it.</strong> An empty <code>assets</code> array renders no well, which is why a draft card is a clean card rather than an empty box.</>,<><strong>The well stacks up to three rows that scroll sideways as one.</strong> The assets are split in the order you give them — six become 2+2+2, four become 2+2, two become 1+1 — so keep related items adjacent and they stay on a row together. Rows are real elements rather than a wrapping column, because a wrapping column gives every chip in a column the widest chip's width and short labels then trail a gap.</>,<>An asset's <code>meta</code> is the machine face — <code>xlsx · 84 kb</code>, <code>csv</code>, <code>live</code> — set in mono and upper-cased. Leave it off where there is no machine value to report; it is not a place for a second label.</>,<><code>download: true</code> marks that asset's anchor <code>download</code>, so the file saves instead of navigating. A <code>download</code> kind without it navigates away, which is almost never what was meant.</>,<><code>icon</code> on an asset overrides the kind's glyph, for a file whose own mark says more than its category does.</>,<><code>author</code> takes a <code>name</code> plus either <code>initials</code> for the carved monogram or a full <code>avatar</code> node.</>,<><code>cover</code>, <code>eyebrow</code>, <code>excerpt</code>, <code>date</code> and <code>readTime</code> are each optional and each disappear cleanly. <code>ArticleCardGrid</code> is the responsive grid to put the cards in.</>,],preview:<ArticleCardGrid><ArticleCard href="#article-card" eyebrow="Cost &amp; hosting" title="What an ERPNext implementation actually costs in India" excerpt="Eleven engagements, the line items that moved, and the three that never do." assets={[{kind:"live",label:"Cost calculator",href:"#article-card",meta:"live"},{kind:"live",label:"Hosting benchmarks",href:"#article-card",meta:"live"},{kind:"download",label:"Line-item sheet",href:"#article-card",meta:"xlsx · 84 kb",download:true},{kind:"download",label:"Quote template",href:"#article-card",download:true},{kind:"data",label:"11-engagement dataset",href:"#article-card",meta:"csv",download:true},{kind:"interactive",label:"Scoping checklist",href:"#article-card"}]} date="14 Jul 2026" readTime="9 min" author={{name:"Manoj Bhat",initials:"MB"}}/><ArticleCard href="#article-card" eyebrow="Migration" title="Leaving Shopify without taking the shop down" excerpt="A catalogue cutover that ran in parallel for six weeks, and what it cost to keep both live." assets={[{kind:"interactive",label:"Cutover timeline",href:"#article-card",meta:"interactive"},{kind:"download",label:"Runbook",href:"#article-card",meta:"pdf · 1.2 mb",download:true}]} date="02 Jun 2026" readTime="12 min" author={{name:"S. Rao",initials:"SR"}}/><ArticleCard eyebrow="Draft" title="What an unlisted-share ledger owes its holders" excerpt="No link and nothing to carry — the card drops both the whole-card affordance and the well rather than showing an empty one." date="—" readTime="—"/></ArticleCardGrid>},
 {id:"case-card",name:"CaseCard",group:"Marketing & editorial",summary:"A case study reduced to its outcome — eyebrow, headline, summary, and outcome metrics in the machine face.",code:`import { CaseCard, CaseCardGrid } from "@mithtech-bengaluru/tonaldepth-react";\n\n<CaseCardGrid>\n  <CaseCard\n    href="/case-studies/rework"\n    eyebrow="Manufacturing"\n    title="Order-to-cash cut to four days"\n    summary="Nine plants onto one ERPNext instance."\n    metrics={[{ label: "Order-to-cash", value: "-38%" }]}\n  />\n</CaseCardGrid>`,options:[["href",`string`,<>Makes the title the whole-card link and renders the call to action. Without it the card drops the CTA rather than pointing nowhere.</>],["renderLink",`(props: { className, href, children }) => ReactNode`,<>Hand your router the anchor. Given the class and the href, return the element — <em>without it every card is a document load</em>. The card keeps ownership of the class; you own the element. Ignored without <code>href</code>.</>],["cta",`ReactNode · default "Read the case study"`,<>The words on that link. Only rendered when <code>href</code> is set.</>],],notes:[<><strong>Hand your router the anchor.</strong> <code>href</code> alone renders a plain <code>&lt;a&gt;</code>, which in a SPA is a full page load out of a grid of cards. <code>renderLink</code> takes the class and the href and returns the element — Next&rsquo;s <code>Link</code>, React Router&rsquo;s <code>Link</code>. Every component in the library that takes an <code>href</code> takes this too; a test holds the pair together, because the three cards shipped without it and nobody noticed until a whole homepage was loading documents.</>,<><strong>Metrics are the machine face.</strong> Each is a <code>label</code> and a <code>value</code>, and the value is set in mono because it is a measured number. Two or three is the useful range — a case card is an outcome, not a report.</>,<><code>visual</code> is the slot for a logo or a plate; <code>eyebrow</code> is the sector or the category, and <code>summary</code> is the one paragraph.</>,<><code>CaseCardGrid</code> is the responsive grid. Cards in it stretch to a common height, so keep the summaries within a line of each other.</>,],preview:<CaseCardGrid><CaseCard href="#case-card" eyebrow="Manufacturing" title="Order-to-cash cut to four days" summary="Nine plants moved off spreadsheets and a legacy AX install onto one ERPNext instance." metrics={[{label:"Order-to-cash",value:"-38%"},{label:"Plants live",value:"9"},{label:"Go-live",value:"11 wks"}]}/><CaseCard eyebrow="Logistics" title="Despatch without the phone calls" summary="No link on this one — the card drops its call to action rather than pointing nowhere." metrics={[{label:"Manual touches",value:"-71%"}]}/></CaseCardGrid>},
 {id:"feature-card",name:"FeatureCard",group:"Marketing & editorial",summary:"The reused shape for a capability, a service, or a platform. Tone moves the icon lamp, never a fill.",code:`import { FeatureCard, FeatureGrid } from "@mithtech-bengaluru/tonaldepth-react";\n\n<FeatureGrid columns={3}>\n  <FeatureCard tone="brand" title="ERPNext implementation" points={["Discovery to go-live"]}>\n    Run by the people who will still be here in year three.\n  </FeatureCard>\n</FeatureGrid>`,options:[["tone",`"neutral" | "brand" | "accent" | "green"`,<>Moves the icon lamp and nothing else — never a fill, never a tinted card. Tone is category, so use it to separate kinds of capability, not to rank them.</>],["href",`string`,<>Makes the title the whole-card link.</>],["renderLink",`(props: { className, href, children }) => ReactNode`,<>Hand your router the anchor. Given the class and the href, return the element — <em>without it every card is a document load</em>. The card keeps ownership of the class; you own the element. Ignored without <code>href</code>.</>],["FeatureGrid columns",`2 | 3 | 4`,<>How many the grid aims for at desktop width. It still reflows below that, so this is a ceiling rather than a fixed count.</>],],notes:[<><code>icon</code> takes a filled glyph — it is a lamp, and an outline cannot read as lit.</>,<><strong>Hand your router the anchor.</strong> <code>href</code> alone renders a plain <code>&lt;a&gt;</code>, which in a SPA is a full page load out of a grid of cards. <code>renderLink</code> takes the class and the href and returns the element — Next&rsquo;s <code>Link</code>, React Router&rsquo;s <code>Link</code>. Every component in the library that takes an <code>href</code> takes this too; a test holds the pair together, because the three cards shipped without it and nobody noticed until a whole homepage was loading documents.</>,<><code>points</code> is a list of short capability lines, rendered as the card's own list. <code>children</code> is the body paragraph and <code>footer</code> a standing fact under it — “Included in every retainer”.</>,<><code>eyebrow</code> is the category above the title. It is small caps, so keep it to a word or two.</>,<>The card is the reused shape for a capability, a service or a platform. If it needs a metric it is a <a href="#case-card">CaseCard</a>; if it needs a cover and a date it is an <a href="#article-card">ArticleCard</a>.</>,<><strong>The services grid is this card, and there is deliberately no second card shape for it.</strong> The design system’s <code>10-marketing/services</code> tile is an icon, a title and a line of text in a two-column grid — which is <code>FeatureCard</code> with <code>icon</code>, <code>title</code> and <code>children</code> inside <code>FeatureGrid columns={2}</code>, and nothing else. Building a narrower card for it would have given the library two shapes to keep in step for one job. Its tile also washes the icon in 18% brand; here the tone moves the lamp instead.</>,],preview:<FeatureGrid columns={3}><FeatureCard tone="brand" icon={ICON_DEMO} eyebrow="ERP" title="ERPNext implementation" href="#feature-card" points={["Discovery to go-live","Data migration"]}>The full stack of an ERP rollout.</FeatureCard><FeatureCard tone="accent" icon={ICON_DEMO} eyebrow="Commerce" title="Medusa storefronts" href="#feature-card" points={["Headless catalogue","Payments and tax"]}>One product record, front and back.</FeatureCard><FeatureCard tone="green" icon={ICON_DEMO} eyebrow="Automation" title="n8n workflows" footer="Included in every retainer" points={["Event-driven flows"]}>The wiring between the systems.</FeatureCard></FeatureGrid>},
 {id:"comparison-table",name:"ComparisonTable",group:"Surfaces & data",summary:"Criteria down, options across. The argued-for column takes the ladder's selected step, never a coloured band.",code:`import { ComparisonTable } from "@mithtech-bengaluru/tonaldepth-react";\n\n<ComparisonTable\n  caption="Open source against proprietary SaaS"\n  columns={[{ key: "oss", label: "Open source", highlight: true }, { key: "saas", label: "SaaS" }]}\n  rows={[{ label: "Source access", cells: { oss: true, saas: false } }]}\n/>`,options:[["columns[].highlight",`boolean`,<>Marks the column the page is arguing for. It renders as the selected step of the depth ladder — a pressed well with papaya ink — never a coloured band.</>],["captionHidden",`boolean · default false`,<>Keeps the caption for screen readers but takes it off the page, for a table that already sits under a heading saying the same thing.</>],["criteriaLabel",`ReactNode · default "Criterion"`,<>The header of the first column, the one holding the row labels.</>],["yesLabel / noLabel",`string · default "Yes" / "No"`,<>The accessible text behind the yes and no marks. The marks themselves are drawn, so this is what a screen reader reads.</>],],notes:[<><strong>Cells are keyed by the column's <code>key</code>.</strong> A row's <code>cells</code> is a record, not an array, so the columns can be reordered without touching a single row.</>,<><code>true</code> and <code>false</code> render as the yes and no marks. Any other node renders as itself — a price, a duration, a sentence. A key that is missing or <code>undefined</code> renders an em dash, which is how you say “not applicable” rather than “no”.</>,<>Both a column and a row take an optional <code>note</code>: the small second line under the label, for the qualifier that would otherwise bloat the cell.</>,<><code>caption</code> is required. A comparison with no stated question is an argument the reader has to reconstruct.</>,],preview:<ComparisonTable caption="Open source implementation against proprietary SaaS" criteriaLabel="What you are buying" columns={[{key:"oss",label:"Open source",note:"Mithtech",highlight:true},{key:"saas",label:"Proprietary SaaS"},{key:"custom",label:"Bespoke build"}]} rows={[{label:"Source access",cells:{oss:true,saas:false,custom:true}},{label:"Per-seat licence",note:"Charged annually, per named user",cells:{oss:"None",saas:"₹2,400",custom:"None"}},{label:"Time to first go-live",cells:{oss:"8-14 weeks",saas:"2-6 weeks",custom:"6-18 months"}},{label:"Exit path",cells:{oss:"Your database, your schema",saas:false,custom:undefined}}]}/>},
 {id:"social-button",name:"SocialButton",group:"Actions",summary:"A social link as its own logo — an icon-only control whose housing carries the platform’s colour. Eighteen marks are built in, taken from Simple Icons so they are the owners’ current ones rather than a set that drifted.",code:`import { SocialButton } from "@mithtech-bengaluru/tonaldepth-react";\n\n<SocialButton network="linkedin" href="https://linkedin.com/in/…" label="Manoj on LinkedIn" />\n\n{/* A footer row, quiet until it is pointed at */}\n<SocialButton network="x" tone="surface" href="…" />\n\n{/* No href makes it a button */}\n<SocialButton network="whatsapp" onClick={openChat} />`,options:[["network",`"x" | "linkedin" | "github" | …`,<>One of eighteen: X, LinkedIn, GitHub, GitLab, YouTube, Instagram, Facebook, Threads, WhatsApp, Telegram, Discord, Slack, Mastodon, Bluesky, Medium, Dribbble, Behance, Reddit. The mark and the colour both come with it.</>],["href",`string`,<>Renders an <code>a</code>. Without it the control is a <code>button</code>, for a share action or a chat that opens in place.</>],["tone",`"brand" | "surface" · default "brand"`,<><code>brand</code> puts the platform’s colour on the housing, so the button reads as the logo. <code>surface</code> is the carved neutral housing with the mark in the platform’s colour, arriving fully on hover.</>],["size",`"sm" | "md" | "lg" · default "md"`,<>34, 42 and 50px square — the exact heights <a href="#button"><code>Button</code></a> uses, so a row of these lines up with an email button rather than missing the baseline by two pixels.</>],["label",`string`,<>The accessible name, defaulting to the platform’s. <strong>Name the person</strong> when a page carries several rows — “LinkedIn” read four times says nothing about whose.</>],["renderLink",`(props) => ReactNode`,<>Hands the anchor to a router, the same seam <a href="#site-navigation">SiteNavigation</a> and <a href="#profile-card">ProfileCard</a> offer.</>],],notes:[<><strong>This is the one place a saturated fill is right</strong>, and it is worth saying why. The system otherwise forbids filling a control with a brand colour — but that rule protects <em>our</em> papaya, because a page that fills with it can no longer say anything with it. These fills are not ours. A reader finds LinkedIn by its blue before they have read a word, and a row of neutral chips makes them read six labels to do what colour did at a glance. Here the colour <em>is</em> the content rather than emphasis laid over it.</>,<><strong>The depth does not change.</strong> Same carve, same ladder, same 1px the label of a filled button travels on press. That is what keeps a row of these sitting <em>in</em> the page rather than pasted on top of it, which is the difference between this and a strip of downloaded logos.</>,<><strong>The four black marks invert in dark mode.</strong> X, Threads, Medium and GitHub are pure or near black, and a black chip on a dark page is a hole. Each swaps to the white housing with a black mark that its owner publishes — the sanctioned inversion, not a filter applied to a trademark.</>,<>The marks are <a href="https://simpleicons.org" target="_blank" rel="noreferrer">Simple Icons</a>’, which is the published source and tracks what the owners currently use. The set in <code>components/packages/core</code> predates it and had drifted — Facebook on the 2019 blue, Instagram on the pre-2022 pink. The icons are CC0; <strong>the marks stay their owners’ trademarks</strong>, so do not restyle one past the inversions its owner publishes.</>,<><strong>Not an <a href="#icon-button">IconButton</a>.</strong> That is the neutral lamp housing for <em>your</em> actions — copy, share, download — and its glyph rides a state ladder. This is a link out to somebody else’s platform, and the mark is a trademark rather than a lamp, so it never glows.</>,],preview:<div style={{display:"grid",gap:28}}><div><p className="sub" style={{margin:"0 0 10px",fontFamily:"var(--td-font-mono)",fontSize:"0.62rem",letterSpacing:"0.14em",textTransform:"uppercase"}}>Brand — the default</p><div className="row" style={{gap:10,flexWrap:"wrap"}}>{SOCIAL_NETWORKS.map(n=><SocialButton key={n} network={n} href="#social-button"/>)}</div></div><div><p className="sub" style={{margin:"0 0 10px",fontFamily:"var(--td-font-mono)",fontSize:"0.62rem",letterSpacing:"0.14em",textTransform:"uppercase"}}>Surface — the colour arrives on hover</p><div className="row" style={{gap:10,flexWrap:"wrap"}}>{SOCIAL_NETWORKS.map(n=><SocialButton key={n} network={n} tone="surface" href="#social-button"/>)}</div></div><div><p className="sub" style={{margin:"0 0 10px",fontFamily:"var(--td-font-mono)",fontSize:"0.62rem",letterSpacing:"0.14em",textTransform:"uppercase"}}>Sizes — 34 / 42 / 50, matching Button</p><div className="row" style={{gap:12,alignItems:"center"}}><Button size="sm" variant="email">Email</Button><SocialButton size="sm" network="linkedin" href="#social-button"/><SocialButton size="sm" network="github" href="#social-button"/><span style={{width:16}}/><Button size="md" variant="email">Email</Button><SocialButton size="md" network="linkedin" href="#social-button"/><span style={{width:16}}/><Button size="lg" variant="email">Email</Button><SocialButton size="lg" network="linkedin" href="#social-button"/></div></div></div>},
 {id:"whatsapp-form",name:"WhatsAppForm",group:"Forms",summary:"The WhatsApp enquiry: a button that opens a short form and hands the finished message to WhatsApp, addressed to one number. Nothing is submitted anywhere — the reader sends it from their own account, and the page they were reading rides along.",code:`import { WhatsAppForm } from "@mithtech-bengaluru/tonaldepth-react";\n\n<WhatsAppForm\n  phone="+91 98765 43210"\n  services={["ERPNext implementation", "Medusa storefront", "n8n automation"]}\n  industries={["Manufacturing", "Retail", "Logistics", "Services"]}\n/>`,options:[["phone",`string`,<><strong>Required.</strong> The number the message goes to, in international format. Punctuation is stripped, so <code>+91 98765 43210</code> and <code>919876543210</code> are the same number — but the country code is not optional: <code>wa.me</code> has no idea where a bare local number lives.</>],["label / title / description / submitLabel",`ReactNode`,<>The trigger’s text, the panel’s heading and line, and the button that hands off. The defaults say what the thing does rather than what it is.</>],["services / industries",`string[]`,<>Supplied, the field becomes a list instead of a free-text box. Worth it for the answers you will act on — routing an enquiry by service only works if the answers are the ones your routing knows. Left out, both are ordinary text fields.</>],["page / includePage",`string · boolean`,<>The line naming where the enquiry came from. It defaults to the page’s own URL, read when the form is sent. <code>includePage={false}</code> drops it.</>],["open / defaultOpen / onOpenChange",`boolean`,<>Control the panel, or let it hold its own state — so a pricing page can open it from its own call to action.</>],["onSend",`(message, values) => boolean | void`,<>Runs after validation with the composed message and the fields behind it. Return <code>false</code> to stop the hand-off — for a consent gate, say. Use it for analytics; it is the only place the data is yours.</>],],notes:[<><strong>Nothing is submitted anywhere.</strong> The form composes a message and opens <code>wa.me</code> with it — the reader sends it themselves, from their own account, and no field ever reaches a server of yours. That is the whole reason to prefer this over a contact form on a channel people already trust: there is no inbox to wonder about, and the reader keeps a copy of what they sent in a thread they can come back to.</>,<><strong>Which also means it is not a substitute for a form that has to be received.</strong> If the enquiry must land in a CRM whether or not the reader completes the hand-off, post it to your own endpoint and use this <em>beside</em> that rather than instead of it. The reader can always close WhatsApp without pressing send.</>,<><strong>The page is captured, never asked for.</strong> Nobody types their way to a useful answer, and it is the single field that most changes how an enquiry should be answered — a sales team reading “the pricing page” replies differently from one reading “the careers page”. It is read at send time rather than when the panel opens, so it is right even in a single-page app where the reader navigated with the form already mounted.</>,<><strong>Four fields are required and the rest are not</strong>, and the form says which is which with a carved seam rather than by making you hunt for asterisks. Name, email, phone and subject; company, industry, service and a free note below the line. Email and phone are checked loosely on purpose — a stricter pattern rejects real addresses, and the only thing that ever proves an address is sending to it.</>,<>The submit button sits in the dialog’s footer, which is a sibling of the form rather than inside it. <code>form=</code> is what ties the two together — no ref between them, and no footer nested in a form.</>,<>Closing it empties it. A form the reader abandoned should not be waiting for them half-filled the next time they open it.</>,<>Everything inside is the library’s own: <a href="#dialog">Dialog</a>, <a href="#form-field">FormField</a>, <a href="#input">Input</a> and <a href="#button">Button</a> at <code>variant="whatsapp"</code>, which brings its own mark. Nothing is drawn here that already exists.</>,],preview:<div style={{display:"grid",gap:20}}><div className="row" style={{gap:16,flexWrap:"wrap"}}><WhatsAppForm phone="+91 98765 43210" services={["ERPNext implementation","Medusa storefront","n8n automation","Support retainer"]} industries={["Manufacturing","Retail","Logistics","Healthcare","Services"]}/><WhatsAppForm phone="+91 98765 43210" label="Talk to sales" title="Talk to sales on WhatsApp" includePage={false}/></div><p className="hint" style={{margin:0}}>Press either one and fill it in. The first offers lists for industry and service and adds this page to the message; the second is the plain form with the page line off. Submitting opens WhatsApp with the message composed — <strong>it does not send anything by itself</strong>, and nothing here reaches a server.</p></div>},
 {id:"cta-banner",name:"CtaBanner",group:"Marketing & editorial",summary:"The closing ask. It carries weight through depth and scale rather than a brand fill.",code:`import { Button, CtaBanner } from "@mithtech-bengaluru/tonaldepth-react";\n\n<CtaBanner\n  eyebrow="Next step"\n  title="Talk to a principal consultant"\n  description="Thirty minutes, no deck."\n  actions={<Button size="lg">Book a call</Button>}\n  assurance="Reply within one business hour, IST."\n/>`,options:[["align",`"split" | "center" · default "split"`,<><code>split</code> sets the copy against the actions across the banner — the page-end ask that still has something to say. <code>center</code> stacks everything on the axis, for a short closing line with one button.</>],],notes:[<><strong>Pass your own Buttons to <code>actions</code>.</strong> The banner supplies placement, not button styling — which is what lets one banner carry a primary and a ghost without inventing a third button variant.</>,<><code>assurance</code> is the reassurance under the actions: the reply time, the no-obligation line, the standing fact. It is smaller and quieter than the description on purpose.</>,<><code>eyebrow</code> and <code>description</code> are optional; <code>title</code> is not.</>,<>The banner carries its weight through depth and scale, never a brand fill. If it is not loud enough, the page above it is competing with it.</>,],preview:<CtaBanner eyebrow="Next step" title="Talk to a principal consultant" description="Thirty minutes, no deck. Bring the process that is hurting and we will tell you whether we are the right people for it." actions={<><Button size="lg">Book a call</Button><Button variant="ghost" size="lg">Send a message</Button></>} assurance="Reply within one business hour, IST."/>},
 {id:"timeline",name:"Timeline",group:"Surfaces & data",summary:"Phases, process, roadmaps. State reads from the dot's depth and the current phase is announced in text. One axis prop turns it from a timeline into a roadmap: the same rail, the same dot, the same three states, measured on planning periods instead of elapsed time.",code:`import { Timeline } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* The timeline: time is a stamp against now, so it trails the row. */}\n<Timeline\n  label="Implementation phases"\n  items={[\n    { title: "Discovery", time: "Week 1-2", state: "done" },\n    { title: "Build", time: "Week 3-6", state: "current" },\n  ]}\n/>\n\n{/* The roadmap: time is the window the item belongs to, so it leads it. */}\n<Timeline\n  axis="period"\n  label="Platform roadmap"\n  items={[\n    { title: "Stripe + Razorpay", time: "Q1 2026", state: "done" },\n    { title: "Self-hosted Plane", time: "Q2 2026", state: "current" },\n  ]}\n/>`,options:[["axis",`"elapsed" · default`,<><strong>The timeline. Runs down.</strong> Marks on a vertical rail, newest last. <code>time</code> is a stamp against now — “2 weeks ago”, “week 8” — so it trails the row the way every machine value in this system does. Renders <code>title</code>, <code>time</code>, <code>meta</code>, <code>description</code> and <code>state</code>; the mark is the state.</>],["axis",`"period"`,<><strong>The roadmap. Runs down.</strong> Same rail, same dot, same three states. <code>time</code> is the planning window the item belongs to — “Q4 2025”, “H1 2027” — so it <em>leads</em> the item as its heading, in papaya mono, because the period is what the reader scans down. Renders the same five fields; only <code>time</code>&rsquo;s position moves.</>],["axis",`"flow"`,<><strong>The pipeline. Runs across.</strong> Steps separated by direction marks, scrolling sideways rather than wrapping — a second row would put step 5 under step 1 and the order would stop being readable. Reach for it when the question is “where did it stop” rather than “how long did it take”. Renders the same five fields: a step carrying a <code>description</code> lays out as a column with a capped measure instead of a nowrap pill.</>],["axis",`"feed"`,<><strong>The activity stream. Runs down, newest first.</strong> The mark is the <em>person</em> rather than a state, so pass <code>initials</code> or <code>avatar</code> on the item; <code>time</code> trails the row. Renders the same five fields plus the mark. There is no meaningful “upcoming” — a feed reports what has happened.</>],["marker",`"dot" | "ordinal" · default "dot"`,<><code>dot</code> is the lamp: the state is the whole signal, which is right when the steps have no names of their own. <code>ordinal</code> numbers them, which is what a plan with a fixed order needs — “step 3” is a thing a reader says out loud and a bare dot cannot be referred to. A <code>done</code> step shows a tick rather than its number.</>],["items[].initials / avatar",`string / ReactNode`,<>The mark on the <code>feed</code> axis, and <strong>only</strong> there. The other three axes draw a state, so a person has nowhere to go in them and is ignored rather than crammed in.</>],["items[].state",`"done" | "current" | "upcoming" · default "upcoming"`,<>Read from the dot's depth. <code>current</code> also prints <code>currentLabel</code> as visible text and <code>done</code> announces <code>doneLabel</code> to a screen reader, so the state is never carried by colour alone.</>],["currentLabel",`string · default "Current phase"`,<>The visible marker on the current item.</>],["doneLabel",`string · default "Complete"`,<>The screen-reader-only text on a completed item.</>],],notes:[<>An item takes <code>title</code>, an optional <code>time</code>, <code>meta</code> and <code>description</code>. <code>time</code> is a machine-reported value — a date, a duration, a week number — and is set in mono; prose belongs in <code>meta</code>.</>,<><strong>Every axis renders every field it is given.</strong> That is the contract, and it is worth stating because it was not true: <code>flow</code> took a <code>description</code>, put it in the DOM and hid it with <code>display: none</code>, so five engagements with a paragraph each came out as titles-only in a sideways scroller. The prop was accepted, the component rendered, the data vanished, and nothing warned. Only the <em>mark</em> is axis-specific — <code>initials</code> and <code>avatar</code> belong to <code>feed</code>, because the other three draw a state instead.</>,<><strong>A <code>flow</code> step with a paragraph stops being a pill.</strong> It takes a column layout and a capped measure so the copy reads down; a step with no <code>description</code> is untouched, so the compact pipeline is exactly what it always was. If you want the tight stepper, do not pass one.</>,<><strong>Each axis emits its own class, named for it</strong> — <code>td-mk-timeline--elapsed</code>, <code>--period</code>, <code>--flow</code>, <code>--feed</code> — so reading the DOM answers which axis is active. <code>--elapsed</code> and <code>--period</code> carry no rules of their own: that is the timeline and the roadmap sharing a layout, not a class that went missing.</>,<><code>label</code> names the sequence for a screen reader. The component renders an ordered list, so the reading order is the phase order.</>,<>Nothing enforces one <code>current</code>. Two of them is a roadmap with two live phases, which is sometimes true and usually a mistake.</>,<><strong>There is no separate Roadmap component, and that is the decision rather than an omission.</strong> A roadmap is this component measured on a different axis — same rail, same dot, same three states, same anatomy — so it is <code>axis="period"</code>. Building a second component would have given the design system two things to correct every time the dot changed.</>,<><strong><code>time</code> means something different on each axis, and only one of them is rendered.</strong> On <code>elapsed</code> it trails the row; on <code>period</code> it leads the item. There is no way to show both, because an item has one position on one axis.</>,<>The design system's roadmap pulses its live dot on an infinite animation. That is not reproduced: state here is depth and a named light, and a component that never stops moving is the one thing a reader cannot stop reading.</>,],preview:<div style={{display:"grid",gap:32}}><Timeline label="Implementation phases" items={[{title:"Discovery",time:"Week 1-2",meta:"Two workshops",description:"Process mapping with the people who actually run the process.",state:"done"},{title:"Data migration",time:"Week 7-9",meta:"Two dry runs",description:"Masters first, then open transactions, then a rehearsal cutover.",state:"current"},{title:"Go-live",time:"Week 10",description:"Floor support for the first full cycle."}]}/><Timeline axis="period" label="Platform roadmap" items={[{title:"Discovery and the Commercely foundation",time:"Q4 2025",description:"Scoped the engagement and shipped the first version on Hetzner.",state:"done"},{title:"Stripe and Razorpay",time:"Q1 2026",description:"Live payments on both gateways, with reconciliation and an audit log.",state:"done"},{title:"Self-hosted Plane migration",time:"Q2 2026",description:"Atlassian exit, GitHub sync, custom modules, on-call rotation.",state:"current"},{title:"Cal.com and Twenty CRM",time:"Q3 2026",description:"Self-hosted booking, customer records inside the perimeter."}]}/></div>},
 {id:"theme-toggle",name:"ThemeToggle",group:"Actions",summary:"The system's theme switch — a round icon button whose sun and moon are lamps, or a pill that names the mode it will switch to. Same button, same behaviour, either shape.",code:`import { ThemeToggle } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* Round, icon only. */}\n<ThemeToggle />\n\n{/* A pill that names the mode the press switches TO. */}\n<ThemeToggle showLabel />\n<ThemeToggle showLabel labelText={{ light: "Light", dark: "Dark" }} />`,options:[["showLabel",`boolean · default false`,<>Off is the round icon button. On turns it into a pill with visible text beside the icon — the accessible name still comes from <code>labels</code>, so the pill can stay short.</>],["storageKey",`string | null · default "td-theme"`,<>Where the choice is remembered in <code>localStorage</code>. <code>null</code> keeps it for the session only.</>],["labels",`Record<Theme, string>`,<>The accessible name, keyed by the theme the press will switch <em>to</em>. Defaults to “Switch to light theme” / “Switch to dark theme”.</>],["labelText",`Record<Theme, string>`,<>The visible pill text, keyed the same way. Defaults to “Light mode” / “Dark mode”.</>],],notes:[<><strong>Both label props are keyed by the destination, not the current state.</strong> When the page is dark, the button reads the <code>light</code> entry, because that is what pressing it does.</>,<><strong>The theme lives on the document.</strong> The button stamps <code>data-theme</code> on the root element and mirrors it to storage; it does not hold the theme itself. That is what lets a whole page follow one attribute.</>,<>It watches that attribute, so two toggles on one page stay in step and an app that changes the theme from its own settings screen is picked up without a reload.</>,<>Until it mounts there is no attribute to read, so it renders unpressed and corrects itself in an effect rather than guessing during render and mismatching on hydration.</>,<>Blocked site data — a private window, a browser set to refuse storage — is caught rather than thrown. The toggle still works; the choice just does not survive the tab.</>,<><code>onThemeChange</code> fires with the new theme, for an app that has to persist it somewhere of its own.</>,],preview:<div className="row" style={{gap:14,flexWrap:"wrap",alignItems:"center"}}><ThemeToggle/><ThemeToggle showLabel/><ThemeToggle showLabel labelText={{light:"Light",dark:"Dark"}}/></div>},
 {id:"prose",name:"Prose",group:"Foundations",summary:"Long-form body copy. Styles authored HTML rather than needing a component per element.",code:`import { Prose } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Prose framed>\n  <h2>What an implementation covers</h2>\n  <p>An implementation is not an installation.</p>\n</Prose>`,options:[["size",`"sm" | "md" | "lg" · default "md"`,<>The measure and the type scale of the body copy. <code>lg</code> is the article body; <code>sm</code> is a note or a sidebar.</>],["framed",`boolean · default false`,<>Sets the prose on its own raised panel instead of directly on the page surface.</>],],notes:[<><strong>It styles authored HTML rather than needing a component per element.</strong> Headings h2 to h4, paragraphs, <code>ul</code> / <code>ol</code> / <code>dl</code>, blockquote with <code>cite</code>, inline <code>code</code> and <code>pre</code>, images, figure and figcaption, <code>hr</code> and tables all have rules.</>,<>Pass the markup as children, or hand a CMS body straight in — the rules attach to the elements, not to classes you have to add.</>,<>First and last child margins are collapsed, so a Prose block sits flush in whatever container it is given.</>,<>An h1 is deliberately not styled here. A page has one, and it belongs to <a href="#rect-title">RectTitle</a> or the page header, not to the body copy.</>,],preview:<Prose framed><h2>What an implementation actually covers</h2><p>An implementation is not an installation. The software is the smallest part of it: the work is deciding what your process really is, then making one system hold it.</p><ul><li>A named owner who can settle a process question.</li><li>One month of real transactions, not a sample.</li></ul><blockquote>The migration is the project. Everything else is configuration.<cite>Every ERP rollout, eventually</cite></blockquote><p>You get the <code>docker-compose.yml</code>, the migration scripts and the runbook.</p></Prose>},
 {id:"rect-title",name:"RectTitle",group:"Foundations",summary:"The headline treatment the design system is named for. It splits a line into balanced parts and scales each one until they all end at the same width, so the block reads as a rectangle. Display face, h1 to h3, with the last line landing in papaya.",code:`import { RectTitle } from "@mithtech-bengaluru/tonaldepth-react";\n\n<RectTitle text="Talk to a principal consultant." />\n\n{/* h2 and h3 run the same treatment at the ramp's smaller sizes. */}\n<RectTitle level={2} text="Order to cash, cut to four days" />\n\n{/* accent={false} keeps the whole block in default ink. */}\n<RectTitle level={3} accent={false} text="What an implementation covers" />`,options:[["level",`1 | 2 | 3 · default 1`,<>Which heading element it renders and which step of the display ramp it takes. The rect treatment runs at h1 to h3; h4 and below are the UI face and are not this component.</>],["tones[]",`"ink" | "muted" | "brand" | "accent" | "green" | "error"`,<>The ink per line, in order. These are the system's categories, not free colour — a headline that can take any hex is a headline that can break the palette.</>],["accent",`boolean · default true`,<>Lands the last line in papaya. Ignored entirely when <code>tones</code> is given.</>],["lines",`number`,<><strong>Exactly this many lines</strong>, overriding the automatic count. Reach for it when <code>maxLines</code> looks like it is being ignored: the automatic count is also held down by a words-per-line heuristic, so a five-word headline stays at two lines however high the ceiling goes. Clamped to the word count — four lines out of three words is three lines and a gap.</>],["maxLines",`number · default 3`,<>A ceiling on the split, not a target. Two lines is the floor whenever the text has at least two words.</>],["forceRectangle",`boolean · default false`,<>Squares the block off exactly, however far a line has to stretch. Off, the fitter stops at 1.5x, so a lopsided headline stays slightly ragged rather than turning a two-word line into a billboard.</>],["maxScale",`number · default 1.5`,<>The same ceiling, set by hand. Use it to loosen the fit by a measured amount instead of all the way — <code>forceRectangle</code> is this set to infinity.</>],],notes:[<><strong>The split is balanced by characters, not by words.</strong> Anton is condensed, so three words can be twice the width of three other words; balancing on word count alone produces a visibly lopsided block before the fitter ever sees it.</>,<><strong>A newline in <code>text</code> is an explicit break and beats everything.</strong> It skips the splitter, the automatic count and the two-line floor — a deliberate one-line headline is a decision rather than an accident. Use it when the break carries meaning the splitter cannot see: a name that must not be divided, a line that has to land on a verb.</>,<><strong><code>maxLines</code> is a ceiling, and the split also holds itself to roughly three words a line</strong>, so raising it past what the headline needs changes nothing — which reads as the prop being ignored. <code>lines</code> is the one that asks for a number. Watch the count in the playground above rather than assuming.</>,<>Every line is then measured and scaled up to the longest one. Only <code>font-size</code> moves — letter-spacing is never touched, because tracking a display face is how a wordmark stops being the wordmark.</>,<>If the longest line is wider than its column the whole block shrinks to fit, so the rectangle survives a narrow container instead of running off the side of the page.</>,<><code>tones</code> repeats its last entry, so a one-item list holds the whole block and a two-item list accents every line after the first. It overrides <code>accent</code> when both are set.</>,<><strong><code>splitRectTitle</code> is exported</strong> alongside the component, for when you need the same line break somewhere the component cannot render — a document title, a meta tag, a canvas. It takes the same three arguments in the same order of precedence: <code>splitRectTitle(text, maxLines, exactLines)</code>.</>,<>Fitting reads layout, so a renderer that does no layout (SSR, jsdom) gets the unfitted lines. The heading still reads correctly; it just is not squared until it reaches a browser.</>,],preview:<div style={{display:"grid",gap:34}}><div><h3 style={{margin:"0 0 8px",fontSize:"0.95rem"}}>The treatment, across content and levels</h3><p className="sub" style={{margin:"0 0 16px"}}>Real headlines of real different lengths, at all three levels. A two-word line and a fourteen-word line are different problems for a fitter that scales every line to the longest one — these are here so you can see which.</p><RectTitleSpecimens/></div><div><h3 style={{margin:"0 0 8px",fontSize:"0.95rem"}}>Type your own</h3><p className="sub" style={{margin:"0 0 16px"}}>Every control the component takes, on one headline.</p><RectTitlePlayground/></div></div>},
 {id:"lamp",name:"The lamp",group:"Foundations",summary:"How an icon reports state without changing what it is: unlit at rest, lit on hover, brighter on press. The system\u2019s most-reused interaction idea, and the one most often implemented wrong.",code:`/* Every lamp rides three tokens. Name your glow; ALWAYS give it a fallback. */\n.my-control { --td-lamp-glow: var(--my-brand, var(--td-ink)); }\n\n.my-control .my-mark {\n  color: color-mix(in srgb, var(--my-ink) 68%, transparent);\n  filter: var(--td-lamp-off);\n  transition: filter var(--td-t-base) var(--td-ease), color var(--td-t-base) var(--td-ease);\n}\n.my-control:hover .my-mark { color: var(--my-ink); filter: var(--td-lamp-hover); }\n.my-control:active .my-mark { color: color-mix(in srgb, var(--my-ink) 88%, white); filter: var(--td-lamp-active); }`,options:[["--td-lamp-glow",`<color>`,<>What the lamp lights <em>with</em>. Set it per component. <strong>Always name a fallback</strong> \u2014 see the trap below.</>],["--td-lamp-off",`drop-shadow \u00d7 2`,<>Rest. Two shadows at zero blur and zero alpha \u2014 not <code>none</code>.</>],["--td-lamp-hover",`drop-shadow \u00d7 2`,<>Lit: one bloom at <code>--td-glow-hover-blur</code> (4px) and <code>--td-glow-hover-strength</code> (22%), plus a second at zero.</>],["--td-lamp-active",`drop-shadow \u00d7 2`,<>Pressed: a 6px core at 52% and a 14px halo at 24% \u2014 <code>--td-glow-active-*</code>.</>]],notes:[<><strong>Depth is state, colour is category.</strong> The lamp is how a control reports what is happening to it without changing what its icon <em>means</em>. A glyph that swaps colour to signal hover has stopped naming its category.</>,<><strong>Colour carries the effect; glow supports it.</strong> This is the one people get wrong. <a href="#social-button">SocialButton</a> looked inert because it moved only the <code>drop-shadow</code> \u2014 invisible on a saturated housing. The mark itself has to get brighter: dimmed at rest, full on hover, pushed past full on press. A 4px bloom is barely visible on a bright screen; a colour step always reads.</>,<><strong>A lamp that is off is DIMMER than its housing&rsquo;s ink</strong>, not merely un-glowing. It has to arrive at rest already holding back the brightness it spends on hover and press, or there is nothing to spend.</>,<><strong>\u26a0 The green-default trap.</strong> <code>--td-lamp-glow: var(--td-green)</code> is declared at <code>:root</code> in <code>tokens.css</code>. Any control whose own glow variable fails to resolve inherits a green halo <em>from a file it never imports</em> \u2014 and this shipped. Always write the fallback: <code>var(--td-social-c, var(--td-ink))</code>, never a bare <code>var(--td-social-c)</code>.</>,<><strong>Both filters are always declared, even at zero alpha.</strong> A state with a different <code>drop-shadow</code> <em>count</em> snaps rather than interpolating, which is why press once looked identical to hover. <code>--td-lamp-off</code> is two explicit zero shadows for exactly this reason \u2014 never replace it with <code>none</code>.</>,<><strong>Who rides it.</strong> <a href="#icon-button">IconButton</a> (the glyph carries the whole state; the label never moves), <a href="#button">Button</a> via <code>.td-primary</code> which sets the glow to <code>--td-brand</code> and <code>.td-coloured</code> which sets it to white, <a href="#alert">Alert</a> where the lamp takes the variant&rsquo;s colour, and <a href="#social-button">SocialButton</a> \u2014 the exception, where the mark lights but must never take a state colour, because it is a trademark.</>],preview:<LampDemo/>},
 {id:"overlays",name:"Overlays",group:"Foundations",summary:"Where an overlay has to be rendered, and why a correct stylesheet renders wrong when it is not. A transformed ancestor becomes the containing block for its position: fixed descendants — so a scrim declared to cover the viewport covers the ancestor instead, and its backdrop-filter computes to none. Nothing errors.",code:`/* Every overlay this library ships escapes its trigger's box, so every one\n   of them is portalled out of the tree it is triggered from. */\nimport { createPortal } from "react-dom";\n\nfunction Sheet({ open, onClose }: { open: boolean; onClose: () => void }) {\n  if (!open || typeof document === "undefined") return null;\n  return createPortal(\n    <div className="my-scrim" onClick={onClose} aria-hidden="true" />,\n    document.body,\n  );\n}\n\n/* .my-scrim { position: fixed; inset: 0; backdrop-filter: blur(8px); }\n   Correct — and inert the moment ANY ancestor carries a transform. */`,options:[["transform / translate / rotate / scale",`anything but none`,<>The common one, and the one that bit <a href="#site-navigation">SiteNavigation</a>: a header that animates its retract is transformed for the whole of that transition.</>],["filter / backdrop-filter",`anything but none`,<>A blurred or tinted wrapper traps everything fixed inside it, and opens a new backdrop root besides.</>],["perspective",`anything but none`,<>Rare on a page, ordinary inside a card that tilts.</>],["will-change",`transform | filter | perspective`,<>Establishes the containing block <em>before</em> anything animates. A performance hint with a layout consequence.</>],["contain",`paint | layout | strict | content`,<>Added for rendering cost, keeps fixed descendants in the box as a side effect.</>],["container-type",`inline-size | size`,<>A container query turns the element into a containing block for fixed descendants too.</>]],notes:[<><strong>The rule.</strong> An element carrying any of the properties above becomes the containing block for every <code>position: fixed</code> descendant. Their <code>inset</code> then resolves against <em>that box</em> rather than the viewport, and <code>backdrop-filter</code> has nothing painted behind it to sample. Both consequences are silent: no error, no warning, and the stylesheet still reads as correct.</>,<><strong>So an overlay is portalled, always.</strong> Not "when a problem shows up" — a component cannot know what a consumer will wrap it in, and the property that breaks it is usually added months later for an unrelated reason. <code>createPortal(node, document.body)</code> puts the surface beyond the reach of every ancestor, and settles its stacking at the same time.</>,<><strong>What this cost, measured.</strong> On the production homepage at <code>0.1.0-alpha.26</code>, <a href="#site-navigation">SiteNavigation</a>&rsquo;s scrim declared <code>position: fixed; inset: 0</code> and rendered <strong>86px tall</strong> — the height of the bar — with <code>backdrop-filter</code> computing to <code>none</code>. It was reported as two separate bugs (<em>&ldquo;the mega menu buttons aren&rsquo;t working&rdquo;</em>, <em>&ldquo;the megamenu background is visible&rdquo;</em>) and the buttons were never broken: <code>aria-expanded</code> flipped, the panel mounted at its full height, the scrim appeared in the DOM. Nothing <em>looked</em> like it had happened to the page, so the menu read as inert.</>,<><strong>Test the containing block, not the declaration.</strong> A test that asserts <code>position: fixed</code> and <code>inset: 0</code> passed for the whole life of that defect. What has to be asserted is where the insets resolve — walk the ancestor chain for the properties above and expect nothing. jsdom performs no layout, so this is also the only honest way to check it there.</>,<><strong>Who this applies to.</strong> Every surface that leaves its trigger&rsquo;s box: <a href="#dialog">Dialog</a>, <a href="#toast">Toast</a>, <a href="#tooltip">Tooltip</a>, <a href="#dropdown-menu">DropdownMenu</a>, <a href="#spotlight">Spotlight</a>, <a href="#chat-launcher">ChatLauncher</a> and <a href="#site-navigation">SiteNavigation</a>&rsquo;s sheet. Add one and it inherits this the day a consumer animates something above it.</>,<><strong>The general form.</strong> A property the rendering model drops in silence is worse than one that is wrong, because reviewing the rule will never find it. When depth, cover or blur does not appear and the declaration looks right, ask whether the element generates the box you think it does — the same class of failure as a <code>box-shadow</code> on a row inside a <code>border-collapse: collapse</code> table.</>],preview:<OverlayTrapDemo/>},
 {id:"button",name:"Button",group:"Actions",summary:"Trigger actions. `primary` is the design system's own primary button — the surface housing with the small green lamp, which is grey glass at rest and lights as you reach for it. The papaya fill is `filled`, and it is the variant to reach for last. Every icon is a lamp: it alone changes across rest, hover and press, while the fill and the label hold.",code:`import { Button } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Button variant="primary">Save changes</Button>\n\n{/* The lamp comes with the primary variant. Drop it when the button\n    only fires an action and reports nothing. */}\n<Button variant="primary" dot={false}>Save changes</Button>\n\n{/* The papaya fill. Reserved rather than reached for. */}\n<Button variant="filled">Book the briefing</Button>\n\n{/* A leading icon becomes the lamp — it lights on hover and\n    brightens on press. The label's colour never moves. */}\n<Button leading={<BoxIcon />}>Book a call</Button>\n\n{/* Semantic fills bring their own icon. */}\n<Button variant="accept">Approve</Button>\n<Button variant="cancel">Cancel</Button>\n<Button variant="accent">Details</Button>\n\n{/* Channel buttons: surface housing, the lamp names the channel. */}\n<Button variant="call">Call us</Button>\n<Button variant="email">Email us</Button>\n<Button variant="whatsapp-quiet">WhatsApp us</Button>\n\n{/* The lowest rung — no housing at all. */}\n<Button variant="link">Read the brief</Button>\n\n{/* The small status lamp — for a control that reports a live state. */}\n<Button dot>Live feed</Button>\n\n{/* A call to action is a link. Same housing, same lamp, same ladder. */}\n<Button variant="primary" href="/audit">Book a discovery briefing</Button>\n<Button variant="email" href="mailto:hello@mith.tech">Email the practice lead</Button>\n\n{/* Hand your router the anchor and it is a client-side navigation\n    instead of a document load. */}\n<Button\n  variant="filled"\n  href="/audit"\n  renderLink={({ className, href, style, children }) => (\n    <Link className={className} href={href} style={style}>{children}</Link>\n  )}\n>\n  Request the discovery briefing\n</Button>`,options:[["variant",`"primary" · the lamp button`,<><strong>The design system's own primary button</strong> — the surface housing carrying the small status lamp, grey glass at rest and lit green as the button is reached for. It carries the lamp <em>by default</em>, because every example the system ships has one; <code>dot={false}</code> drops it.</>],["variant",`"secondary" · default`,<>The same surface housing without the lamp. The one most buttons should be: it fires an action and reports nothing.</>],["variant",`"filled" · the orange button, with a lamp`,<><strong>The papaya fill, and it carries the lamp too.</strong> White, because papaya on papaya is invisible. Reserved rather than reached for — filling with the brand colour is the one move the system forbids everywhere else, and a page with two of these has none. One per screen, at most.</>],["variant",`"outline" | "ghost" | "link"`,<>The quieter rungs. <code>link</code> is the lowest and has no housing at all.</>],["variant",`"destructive" | "accept" | "cancel" | "accent"`,<>The semantic fills, where the housing's colour carries the meaning. Each brings its own default icon, so <code>variant="accept"</code> is complete on its own.</>],["variant",`"whatsapp" | "whatsapp-quiet" | "call" | "email"`,<>The channel buttons, where the lamp names the channel. <code>whatsapp</code> is the filled housing; the other three sit on the surface and light azure or WhatsApp green.</>],["size",`"sm" | "md" | "lg" · default "md"`,<>The control height. <code>lg</code> is the page-level call to action; <code>sm</code> belongs in a toolbar or a table row.</>],["loading",`boolean · default false`,<>Swaps the lamp for a spinner, replaces the children with <code>loadingLabel</code>, sets <code>aria-busy</code> and disables the button.</>],["dot",`boolean · default true on "primary" and "filled"`,<>The small status lamp — a 7px disc before the label, grey glass at rest and lit on hover and press. On by default for <code>primary</code> and <code>filled</code> — the two buttons that carry the weight of a screen — and off everywhere else; pass it to add one to any variant that reports a live state, or <code>dot={false}</code> to take it off a primary.</>],["leading / trailing",`ReactNode`,<><code>leading</code> is the lamp and carries the state. <code>trailing</code> is a directional mark — a chevron, an arrow — and is deliberately not a lamp.</>],["glow",`string`,<>Any CSS colour, overriding the variant's lamp colour. Mixed at the <code>--td-glow-*</code> strengths, so it still rides the same ladder and still follows the theme.</>],["href",`string`,<>Renders an <code>&lt;a&gt;</code> instead of a <code>&lt;button&gt;</code>. Nothing about the visual contract changes — same housing, same lamp, same four-step ladder, same base class per variant. <code>type</code> is not emitted on the anchor, and the UA underline is dropped for every variant except <code>link</code>, whose underline <em>is</em> its housing.</>],["renderLink",`(props: { className, href, style, children }) => ReactNode`,<>Hand your router the anchor. Given the class and the href, return the element — with it a call to action is a client-side navigation, without it every one is a document load. Ignored without <code>href</code>.</>],],notes:[<><strong>The dot brightens; it no longer jumps.</strong> Its rest and hover each carried one shadow slot and its press carried two, and a shadow list only interpolates against a list of the same length — so the disc snapped to its pressed state instead of lighting into it, on every primary and every filled button. Every rung now carries the same two, with the unlit one written at zero alpha in the lamp’s own colour.</>,<><strong>On a fill the unlit lamp is glass, not a hole.</strong> It used to be black, with four variants listed by name as exceptions because black on deep green or red is invisible. Black on papaya is not much better — it reads as a hole punched in the button — and a list of exceptions is always one variant behind the variants. A fill is a fill: translucent white dims to glass on all of them.</>,<><strong><code>primary</code> is the surface housing with the lamp, not a fill.</strong> The design system draws exactly one primary button — <code>.td-primary</code>, a carved surface with a 7px lamp that is grey glass at rest and lights green as you reach for it — and every example it ships carries that lamp. The library used to give the name <code>primary</code> to the solid papaya fill, which is the one move the system forbids, and left the real primary button under <code>secondary</code> where nobody found it. The fill is now <code>filled</code> and the names mean what they say.</>,<><strong>Reach for <code>filled</code> last.</strong> A page with two papaya buttons has none: the fill is emphasis, and emphasis divided is emphasis spent. Depth is what separates a control from the page here — the fill is for the one action a screen exists to get.</>,<><strong>Only the icon moves.</strong> Across rest, hover and press the fill and the label hold their colour and depth alone reports the press. On a filled housing the lamp lights white, because papaya on papaya is invisible; on a surface housing it lights the channel's own colour.</>,<><strong><code>type</code> defaults to <code>"button"</code>.</strong> A Button inside a form does not submit it unless you pass <code>type="submit"</code> — which is the safe default, but it does catch people out.</>,<>The four semantic variants supply their own leading icon. Passing <code>leading</code> overrides it; passing <code>leading</code> to an emphasis variant adds one.</>,<><code>loading</code> also sets <code>disabled</code>, so there is no need to set both. Give <code>loadingLabel</code> the verb — “Saving”, not “Loading” — since it replaces the visible text.</>,<><strong>The lamp scales with the label.</strong> A leading or trailing glyph is drawn at 1.5× the label — so it grows with <code>size</code> and you never set a glyph size yourself. Below that ratio the lamp is optically the lightest thing in the button, which is the part carrying the whole state signal. <a href="#icon-button">IconButton</a>, <a href="#split-button">SplitButton</a> and <a href="#filament-button">FilamentButton</a> share it.</>,<><strong>A call to action is a link, so <code>href</code> makes this one.</strong> The library already knew the pattern — <a href="#icon-button">IconButton</a> takes an <code>href</code>, <a href="#social-button">SocialButton</a> takes an <code>href</code> and a <code>renderLink</code> — and the one button that draws the design system's primary control was the one that could not be either. Every consumer fell back to a hand-written <code>&lt;a className="td-primary"&gt;</code> with its own <code>&lt;span className="td-lamp"&gt;</code> inside it, which is this component reimplemented at the call site. Delete those.</>,<><strong>A disabled or loading link renders as <code>&lt;button disabled&gt;</code>.</strong> <code>disabled</code> is not something HTML gives an anchor, and the entire disabled ladder this system ships — the flattened housing, the dead lamp, the suppressed hover — is written at <code>:disabled</code>, which an anchor can never match. An <code>&lt;a aria-disabled="true"&gt;</code> would keep the full lit press ladder and read as pressable while doing nothing. <code>disabled</code> and <code>loading</code> therefore beat <code>href</code>, and <code>renderLink</code> is not called in that state either: a router link that cannot be followed is worse than no link.</>,<><strong><code>renderLink</code> receives four things and no more</strong> — <code>className</code>, <code>href</code>, <code>style</code> and <code>children</code>, the same four <a href="#social-button">SocialButton</a> passes. <code>target</code>, <code>rel</code>, <code>onClick</code> and any <code>aria-*</code> you gave the Button do <em>not</em> reach it; put those on your own element. <code>style</code> carries the <code>glow</code> colour, so spread it or the lamp lights the variant's colour instead of yours.</>,<>The event handlers are typed against the button in both forms, so a handler you already wrote keeps type-checking when you add an <code>href</code>. One that needs the anchor reads <code>event.currentTarget</code> as an <code>HTMLElement</code> and casts.</>,<>Everything native passes through: <code>disabled</code>, <code>onClick</code>, <code>form</code>, <code>name</code>, <code>value</code>, <code>aria-*</code> — plus <code>target</code>, <code>rel</code> and <code>download</code> in the anchor form.</>,],preview:<div style={{display:"flex",flexDirection:"column",gap:16}}><div className="row"><Button variant="primary">Primary</Button><Button variant="secondary">Secondary</Button><Button variant="filled">Filled</Button><Button variant="outline">Outline</Button><Button variant="ghost">Ghost</Button><Button variant="destructive">Delete</Button></div><p className="hint" style={{margin:0}}>The first one is the design system’s primary button: the surface housing with the small lamp. Hover it — the lamp is grey glass at rest and lights green as you reach for it, and it goes fully green while the button is held. <code>filled</code> is the papaya fill, and it is the variant to reach for last.</p><div className="row"><Button variant="accept">Accept</Button><Button variant="cancel">Cancel</Button><Button variant="accent">Details</Button><Button variant="whatsapp">WhatsApp us</Button></div><div className="row"><Button variant="whatsapp-quiet">WhatsApp us</Button><Button variant="call">Call us</Button><Button variant="email">Email us</Button><Button variant="link">Read the brief</Button></div><div className="row"><Button variant="primary">Lamp by default</Button><Button variant="primary" dot={false}>Lamp dropped</Button><Button dot>Live feed</Button><Button variant="outline" dot>Synced</Button></div><div className="row"><Button leading={LAMP_ICON}>Book a call</Button><Button variant="filled" leading={LAMP_ICON}>Save changes</Button><Button variant="outline" leading={LAMP_ICON}>Export</Button><Button leading={LAMP_ICON} loading>Saving</Button></div><p className="hint" style={{margin:0}}>Hover any of them: only the icon moves. The fill and the label are fixed in every state — depth alone reports the press. On a filled housing the lamp lights white, because papaya on papaya would be invisible; on a surface housing it lights the channel's own colour.</p><div className="row"><Button variant="primary" href="#button">Book a discovery briefing</Button><Button variant="filled" href="#button">Request the briefing</Button><Button variant="email" href="mailto:hello@example.com">Email the practice lead</Button><Button variant="link" href="#button">Read the brief</Button></div><p className="hint" style={{margin:0}}>These four are <code>&lt;a&gt;</code> elements. <code>href</code> changes the tag and nothing else — same housing, same lamp, same ladder — so a page&rsquo;s call to action is the design system&rsquo;s primary button rather than an anchor wearing its class. Pass <code>renderLink</code> and your router owns the navigation.</p></div>},
 {id:"badge",name:"Badge",group:"Feedback",summary:"Label compact state, category, or emphasis without implying an action.",code:`import { Badge } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Badge variant="success">Ready</Badge>`,options:[["variant",`"neutral" | "brand" | "success" | "accent" | "danger" · default "neutral"`,<>The category the label belongs to. <code>neutral</code> for a plain tag, <code>success</code> and <code>danger</code> for a state, <code>brand</code> and <code>accent</code> for an emphasis that is not a state.</>],],notes:[<><strong>A badge is a span, not a control.</strong> It has no press state, takes no focus and implies no action. If it is meant to be clicked it is a <a href="#button">Button</a> or a <a href="#filter-bar">FilterBar</a> chip.</>,<>Colour is category here, so pick the variant by what the label <em>means</em>, not by which colour looks right beside it.</>,<>Native span attributes pass through, including <code>title</code> and <code>aria-*</code>.</>,],preview:<div className="row"><Badge>Neutral</Badge><Badge variant="brand">Brand</Badge><Badge variant="success">Ready</Badge><Badge variant="accent">Review</Badge><Badge variant="danger">Blocked</Badge></div>},
 {id:"card",name:"Card",group:"Surfaces & data",summary:"Group related content with TonalDepth surface and depth treatments.",code:`import { Card, CardContent, CardHeader, CardTitle } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Card>\n  <CardHeader><CardTitle>Project status</CardTitle></CardHeader>\n  <CardContent>Ready for review.</CardContent>\n</Card>`,options:[["depth",`"raised" | "flat" | "inset" · default "raised"`,<><code>raised</code> is a plate offered to the reader. <code>flat</code> sits level with the page for a card that is only grouping. <code>inset</code> is cut into the surface — for something being shown rather than offered.</>],["padding",`"default" | "none" · default "default"`,<><code>none</code> gives an unpadded plate whose own children own the gutter, so a seam drawn between them runs the full width of the card instead of stopping short of the edges.</>],],notes:[<><strong>Three parts.</strong> <code>CardHeader</code> is the title row, <code>CardTitle</code> renders an h3 inside it, and <code>CardContent</code> is the body. Each is optional — a Card with plain children is a plain plate.</>,<>A header can hold more than the title: a <a href="#badge">Badge</a>, a meta line, a small action all sit in it and stay aligned.</>,<>Reach for <a href="#frame">Frame</a> instead when the card is housing something measured — a chart, a table. Chrome is raised and data is recessed, and Frame is that pairing already built.</>,],preview:<Card className="sample"><CardHeader><CardTitle>Project status</CardTitle><Badge variant="success">Ready</Badge></CardHeader><CardContent>Content stays owned by the consuming app.</CardContent></Card>},
 {id:"input",name:"Input",group:"Forms",summary:"Single-line text field with optional leading and trailing slots and an invalid state.",code:`import { Input } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Input type="email" placeholder="name@company.com" />`,options:[["invalid",`boolean · default false`,<>Marks the field failed and sets <code>aria-invalid</code>. Inside a <a href="#form-field">FormField</a> with an <code>error</code>, this is set for you.</>],["leading / trailing",`ReactNode`,<>Marks inside the field — a currency sign, a unit, a magnifier. They are marks, not controls: they take no focus and no glow.</>],["containerClassName",`string`,<>Styles the wrapper that holds the field and its slots. <code>className</code> still goes to the input itself.</>],],notes:[<><strong>Every native input attribute passes through</strong> — <code>type</code>, <code>placeholder</code>, <code>value</code>, <code>defaultValue</code>, <code>onChange</code>, <code>required</code>, <code>disabled</code>, <code>autoComplete</code>, <code>inputMode</code>. The component adds treatment, not behaviour.</>,<><strong>It has no label of its own.</strong> Wrap it in a <a href="#form-field">FormField</a> for the label, the help text and the ARIA wiring; a bare Input with only a placeholder has no accessible name.</>,<>The field is carved into the surface rather than raised: a place to put something is never lifted. That is why an Input and a <a href="#button">Button</a> of the same height read as different kinds of thing.</>,<>For a search field with suggestions, use <a href="#search-bar">SearchBar</a> — it carries the combobox pattern this does not.</>,],preview:<div className="stack"><Input type="email" placeholder="name@company.com"/><Input placeholder="Search" leading="?" /><Input placeholder="Blocked" disabled defaultValue="Read only"/></div>},
 {id:"textarea",name:"Textarea",group:"Forms",summary:"Multi-line text field matched to the Input treatment for longer form entry.",code:`import { Textarea } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Textarea placeholder="Describe the work" />`,options:[["invalid",`boolean · default false`,<>Marks the field failed and sets <code>aria-invalid</code>. Set for you when it sits in a <a href="#form-field">FormField</a> with an <code>error</code>.</>],["containerClassName",`string`,<>Styles the wrapper. <code>className</code> goes to the textarea itself.</>],],notes:[<>The same carved treatment as <a href="#input">Input</a>, at multi-line height. Native attributes pass through, <code>rows</code> among them.</>,<>Wrap it in a <a href="#form-field">FormField</a> for the label and the ARIA relationships — on its own it has no accessible name.</>,<>There is no auto-grow. A textarea that resizes as you type moves everything under it, which is worse than a scrollbar in a form.</>,],preview:<div className="stack"><Textarea placeholder="Describe the work"/><Textarea invalid defaultValue="Short" placeholder="Needs more detail"/></div>},
 {id:"form-field",name:"FormField",group:"Forms",summary:"Wire label, help text, error text, and ARIA relationships around a single child control.",code:`import { FormField, Input } from "@mithtech-bengaluru/tonaldepth-react";\n\n<FormField label="Work email" helperText="Used only for notifications" required>\n  <Input type="email" placeholder="name@company.com" />\n</FormField>`,options:[["required",`boolean`,<>Prints the required mark beside the label and sets <code>required</code> on the child, unless the child already sets it.</>],["optional",`boolean`,<>Prints the word Optional beside the label. Purely editorial — it sets nothing on the control.</>],["error",`ReactNode`,<>The failure message. It replaces <code>helperText</code>, flips the field's invalid state, and sets <code>aria-invalid</code> on the child.</>],["helperText",`ReactNode`,<>The standing hint under the control, shown whenever there is no <code>error</code>.</>],["htmlFor",`string`,<>The control's id, when you need to own it. Left off, one is generated and given to the child.</>],],notes:[<><strong>Exactly one child element.</strong> The field clones it to attach <code>id</code>, <code>aria-describedby</code>, <code>aria-invalid</code> and <code>required</code> — so it needs a single element to clone, not a fragment and not two controls.</>,<><strong>It never overrides what the child already sets.</strong> Pass your own <code>id</code> or <code>aria-describedby</code> on the control and it survives; the field only fills gaps.</>,<><code>error</code> wins over <code>helperText</code> when both are given, so you can leave the hint in place and add the error on top of it rather than swapping them yourself.</>,<><strong>The message carries no live region.</strong> It is wired through <code>aria-describedby</code> and read when focus lands on the control. A form that validates several fields at once should announce the failures in one summary above the form — three assertive regions firing together talk over each other and the field message is announced twice.</>,],preview:<div className="stack"><FormField label="Work email" helperText="Used only for notifications" required><Input type="email" placeholder="name@company.com"/></FormField><FormField label="Summary" optional><Textarea placeholder="Describe the work"/></FormField><FormField label="Blocked" error="This field is required"><Input placeholder="Value"/></FormField></div>},
 {id:"checkbox",name:"Checkbox",group:"Forms",summary:"Toggle an independent boolean with an owned label and TonalDepth check treatment.",code:`import { Checkbox } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Checkbox label="Email notifications" defaultChecked />`,notes:[<><strong><code>label</code> is required and the component owns it</strong> — it renders the label element and the association. Do not wrap it in your own label; that gives the control two names.</>,<>Native attributes pass through: <code>checked</code>, <code>defaultChecked</code>, <code>onChange</code>, <code>disabled</code>, <code>name</code>, <code>value</code>, <code>required</code>.</>,<>For a checkbox that needs help text or an error message, put it in a <a href="#form-field">FormField</a> — the label stays here, the message comes from there.</>,<>An independent boolean is a Checkbox; one of several exclusive choices is a <a href="#radio">Radio</a>; a setting that takes effect immediately is a <a href="#switch">Switch</a>.</>,],preview:<div className="stack"><Checkbox label="Email notifications" defaultChecked/><Checkbox label="Weekly summary"/><Checkbox label="Blocked option" disabled/></div>},
 {id:"radio",name:"Radio",group:"Forms",summary:"Choose one option in a group; RadioGroup shares the underlying name and disabled state.",code:`import { Radio, RadioGroup } from "@mithtech-bengaluru/tonaldepth-react";\n\n<RadioGroup legend="Delivery" name="delivery" defaultValue="standard">\n  <Radio label="Standard" value="standard" defaultChecked />\n  <Radio label="Express" value="express" />\n</RadioGroup>`,notes:[<><strong>RadioGroup supplies the <code>name</code>.</strong> It passes it down through context, so the radios inside it belong to one group without repeating it on each. Setting <code>disabled</code> on the group disables all of them the same way.</>,<>Each <code>Radio</code> needs its own <code>value</code>. <code>label</code> is required and owned by the component, as with <a href="#checkbox">Checkbox</a>.</>,<><code>legend</code> names the group. It renders a real fieldset and legend, which is what a screen reader reads before the first option.</>,<>Selection is native — use <code>defaultChecked</code> on one radio, or <code>checked</code> with <code>onChange</code> to control it.</>,],preview:<RadioGroup legend="Delivery" name="delivery"><Radio label="Standard" value="standard" defaultChecked/><Radio label="Express" value="express"/><Radio label="Overnight" value="overnight" disabled/></RadioGroup>},
 {id:"switch",name:"Switch",group:"Forms",summary:"Toggle a setting on or off with a role=switch checkbox and owned label.",code:`import { Switch } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Switch label="Automatic updates" defaultChecked />`,notes:[<>Renders a checkbox with <code>role="switch"</code>, so it is announced as on or off rather than checked or unchecked.</>,<><code>label</code> is required and owned by the component.</>,<><strong>A switch takes effect immediately.</strong> If the change only lands when a form is submitted, that is a <a href="#checkbox">Checkbox</a>, not a switch.</>,<>Native attributes pass through: <code>checked</code>, <code>defaultChecked</code>, <code>onChange</code>, <code>disabled</code>.</>,],preview:<div className="stack"><Switch label="Automatic updates" defaultChecked/><Switch label="Beta features"/><Switch label="Locked" disabled/></div>},
 {id:"alert",name:"Alert",group:"Feedback",summary:"Communicate persistent info, success, warning, or error notices with an optional dismiss control. The category is a lamp — a lens seated in a socket carved from the panel — never a tinted band: one continuous surface, colour only where the light is.",code:`import { Alert } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Alert variant="success" title="Saved">Your changes are available.</Alert>`,options:[["variant",`"info" | "success" | "warning" | "error" · default "info"`,<>The category, carried by one lit lamp. <code>error</code> also renders with <code>role="alert"</code>; the other three take <code>role="status"</code>.</>],["onDismiss",`() => void`,<>Supplying it renders the close button. The alert does not remove itself — you own whether it is still on the page.</>],["dismissLabel",`string · default "Dismiss"`,<>The accessible name of that button.</>],],notes:[<><strong>Children must be inline content.</strong> The body is already a paragraph, so passing a <code>p</code> nests one inside another and breaks hydration. Text, links and spans are fine.</>,<><code>title</code> is required and is the sentence that has to work on its own — the lamp is the category, not the message.</>,<><strong>The category is a lamp, never a tinted band.</strong> One continuous surface with colour only where the light is; that is what keeps four alerts in a column from reading as four different materials.</>,<>For a transient message use <a href="#toast">Toast</a>. An Alert is persistent — it stays until the page or the app takes it away.</>,],preview:<div className="stack"><Alert variant="info" title="Local package">Loaded from the workspace package.</Alert><Alert variant="success" title="Verified">The React test suite passes.</Alert><Alert variant="warning" title="Registry only">GitHub Packages publishing is not yet verified.</Alert><Alert variant="error" title="Blocked">Package registry credentials are missing.</Alert></div>},
 {id:"tooltip",name:"Tooltip",group:"Feedback",summary:"Reveal contextual guidance on hover or focus around a single child element with an ARIA-linked tip.",code:`import { Tooltip, Button } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Tooltip content="Opens guidance"><Button variant="outline">Help</Button></Tooltip>`,options:[["open",`boolean`,<>Forces the tip visible. For documentation, screenshots and tests — leave it off in an app, where hover and focus already reveal it.</>],],notes:[<><strong>Exactly one child element.</strong> It is cloned to attach <code>aria-describedby</code>, so a fragment or a bare string has nothing to attach to.</>,<>Hover and keyboard focus both reveal the tip, which is why the child should be something focusable. A tooltip on a plain span is unreachable without a mouse.</>,<>The tip is always in the DOM and hidden visually, so it is read as the control's description rather than appearing only on a pointer event.</>,<><strong>It describes, it does not name.</strong> A control whose only label is a tooltip has no accessible name — give it an <code>aria-label</code> as well.</>,],preview:<div className="row"><Tooltip content="Keyboard and pointer accessible"><Button variant="outline">Hover or focus</Button></Tooltip><Tooltip content="Persistent open state" open><Button variant="ghost">Always visible</Button></Tooltip></div>},
 {id:"forms",name:"Form controls",group:"Forms",summary:"Compose accessible labels, help, errors, text fields, and selection controls.",code:`import { FormField, Input, Checkbox } from "@mithtech-bengaluru/tonaldepth-react";\n\n<FormField label="Work email" helperText="Used for notifications" required>\n  <Input type="email" placeholder="name@company.com" />\n</FormField>\n<Checkbox label="Email notifications" defaultChecked />`,notes:[<><strong>This page is a composition demo, not a registry item.</strong> There is nothing to install called “form controls” — it shows the parts working together.</>,<>The parts: <a href="#form-field">FormField</a> for the label, help, error and ARIA wiring; <a href="#input">Input</a> and <a href="#textarea">Textarea</a> for text; <a href="#checkbox">Checkbox</a>, <a href="#radio">Radio</a> with RadioGroup, and <a href="#switch">Switch</a> for selection.</>,<>The rule that ties them together: the control owns its own treatment, and FormField owns everything around it. Nothing here needs a form library to be accessible.</>,],preview:<div className="stack"><FormField label="Work email" helperText="Used only for notifications" required><Input type="email" placeholder="name@company.com"/></FormField><FormField label="Summary"><Textarea placeholder="Describe the work"/></FormField><Checkbox label="Email notifications" defaultChecked/><Switch label="Automatic updates" defaultChecked/></div>},
 {id:"tabs",name:"Tabs",group:"Navigation",summary:"Switch between related panels with keyboard-accessible tab semantics.",code:`import { Tabs } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Tabs defaultValue="overview" items={[\n  { value: "overview", label: "Overview", content: "Summary" },\n  { value: "activity", label: "Activity", content: "Recent changes" },\n]} />`,options:[["items[]",`{ value, label, content, disabled? }`,<>One object per tab. <code>content</code> is the panel, so the panels live with the tabs rather than in a separate array you have to keep in step.</>],["value / defaultValue",`string`,<>Pass <code>value</code> with <code>onValueChange</code> to control it. Pass <code>defaultValue</code> — or neither, and the first enabled tab is selected — to leave it uncontrolled.</>],["label",`string · default "Tabs"`,<>Names the tablist for a screen reader. Set it whenever there is more than one tab set on the page.</>],],notes:[<><strong>Selection follows focus.</strong> Arrow keys move between tabs and select as they go; Home and End jump to the ends. A disabled tab is skipped rather than focused and refused.</>,<>The list is a roving tabstop, so one Tab press moves into the panel rather than through every tab.</>,<>Panels are mounted one at a time. Anything expensive in a panel is not paid for until that panel is opened — and any state it holds is lost when it closes.</>,<>For a vertical rail whose selection is a lit filament rather than an underline, use <a href="#side-tabs">SideTabs</a>.</>,],preview:<Tabs defaultValue="overview" items={[{value:"overview",label:"Overview",content:"Current project status and ownership."},{value:"activity",label:"Activity",content:"Recent component-library changes."}]}/>},
 {id:"feedback",name:"Feedback",group:"Feedback",summary:"Communicate persistent alerts and contextual tooltip guidance.",code:`import { Alert, Tooltip, Button } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Alert variant="success" title="Saved">Your changes are available.</Alert>\n<Tooltip content="Opens guidance"><Button variant="outline">Help</Button></Tooltip>`,notes:[<><strong>A composition demo, not a registry item.</strong> It shows <a href="#alert">Alert</a> and <a href="#tooltip">Tooltip</a> on one page — install those two.</>,<>The distinction worth taking from it: an Alert is persistent and page-level, a Tooltip is transient and attached to one control, and a <a href="#toast">Toast</a> is transient and app-level.</>,],preview:<div className="stack"><Alert variant="info" title="Local package">Loaded from the workspace package.</Alert><Alert variant="success" title="Verified">The React test suite passes.</Alert><Tooltip content="Keyboard and pointer accessible"><Button variant="outline">Hover or focus</Button></Tooltip></div>},
 {id:"table",name:"Table",group:"Surfaces & data",summary:"Render semantic tabular data with responsive containment.",code:`import { Table, TableBody, TableCell, TableContainer, TableHead, TableHeader, TableRow } from "@mithtech-bengaluru/tonaldepth-react";\n\n<TableContainer><Table><TableHead><TableRow>\n  <TableHeader>Package</TableHeader><TableHeader>Status</TableHeader>\n</TableRow></TableHead><TableBody><TableRow>\n  <TableCell>React</TableCell><TableCell>Verified</TableCell>\n</TableRow></TableBody></Table></TableContainer>`,notes:[<><strong>Seven exports, one per element.</strong> <code>TableContainer</code>, <code>Table</code>, <code>TableHead</code>, <code>TableBody</code>, <code>TableRow</code>, <code>TableHeader</code> and <code>TableCell</code>. Each renders its native element with the system's treatment and nothing else.</>,<><strong><code>TableContainer</code> is the scroll container.</strong> Without it a wide table pushes the whole page sideways instead of scrolling itself — which is the one thing that goes wrong at 390px.</>,<><code>TableHeader</code> defaults to <code>scope="col"</code>. Pass <code>scope="row"</code> for a row header, as the leftmost cell of each row in a comparison.</>,<><strong>A row is pressed, not tinted.</strong> Hover sinks the row a little and the press sinks it deeper — the same grammar every row in the system uses. Nothing is required of you to get it. Mark the current row with <code>aria-selected="true"</code> (or <code>data-selected="true"</code>) and it rests recessed, the way an open nav button does.</>,<><strong>Do not set <code>border-collapse</code> on the table.</strong> The component ships the separated model with <code>border-spacing: 0</code>, which renders identically to the collapsed one here — the only borders are on the cells. It matters because a <code>&lt;tr&gt;</code> under <code>border-collapse: collapse</code> generates no box for a <code>box-shadow</code> to paint into, so the row's whole depth is discarded in silence and the highlight flattens to a tint.</>,<>There is no sorting, no pagination and no virtualisation here — this is the semantic table. For criteria against options, use <a href="#comparison-table">ComparisonTable</a>; for a table housed as data, put it in a <a href="#frame">Frame</a>.</>,<>Native attributes pass through, so <code>colSpan</code>, <code>rowSpan</code> and <code>aria-*</code> work as usual.</>,],preview:<TableContainer><Table><TableHead><TableRow><TableHeader>Package</TableHeader><TableHeader>Status</TableHeader></TableRow></TableHead><TableBody><TableRow><TableCell>React</TableCell><TableCell><Badge variant="success">Verified</Badge></TableCell></TableRow><TableRow><TableCell>Vue</TableCell><TableCell><Badge variant="accent">P0 only</Badge></TableCell></TableRow></TableBody></Table></TableContainer>},
 {id:"kpi",name:"KPI cards",group:"Surfaces & data",summary:"Present high-level metrics in a responsive token-driven grid.",code:`import { KpiCard, KpiGrid } from "@mithtech-bengaluru/tonaldepth-react";\n\n<KpiGrid>\n  <KpiCard label="Open" value="42" delta="+6" trend="up" />\n  <KpiCard label="Resolved" value="128" delta="+18%" trend="up" />\n</KpiGrid>`,options:[["trend",`"up" | "down" | "neutral" · default "neutral"`,<>Which way the <code>delta</code> reads. It colours the delta only — up is not automatically good, so the word beside it still has to say what happened.</>],["visualization",`ReactNode`,<>The slot under the value, for a sparkline or a small plot. Keep it a shape, not a chart with axes.</>],],notes:[<><code>label</code> and <code>value</code> are both required — a metric with no name is a number nobody can act on.</>,<>The value is set in the machine face. That is the point of the card: it is a measured quantity, and it should not look like prose.</>,<><code>KpiGrid</code> is the responsive grid. It reflows rather than squashing, so four cards become two rows before they become four narrow columns.</>,<><code>delta</code> is free text — “+6”, “+18%”, “2 fewer”. It is not computed for you.</>,],preview:<KpiGrid><KpiCard label="Open" value="42" delta="+6" trend="up"/><KpiCard label="Resolved" value="128" delta="+18%" trend="up"/></KpiGrid>},
 {id:"dialog",name:"Dialog",group:"Overlays",summary:"Focus-trapping modal with title, description, footer actions, Escape and outside-click dismissal.",code:`import { Dialog, Button } from "@mithtech-bengaluru/tonaldepth-react";\nimport { useState } from "react";\n\nfunction DeleteProject() {\n  const [open, setOpen] = useState(false);\n  return (\n    <>\n      <Button onClick={() => setOpen(true)}>Open dialog</Button>\n      <Dialog open={open} onOpenChange={setOpen} title="Delete project" description="This action cannot be undone."\n        footer={<><Button variant="ghost" onClick={() => setOpen(false)}>Cancel</Button><Button variant="destructive" onClick={() => setOpen(false)}>Delete</Button></>}>\n        <p>All history and comments will be permanently removed.</p>\n      </Dialog>\n    </>\n  );\n}`,options:[["open / onOpenChange",`boolean / (open) => void`,<>Both required — the dialog is controlled, always. It renders nothing at all when closed.</>],["description",`ReactNode`,<>Wired to <code>aria-describedby</code>, so it is read after the title. Prose that only matters visually belongs in the children instead.</>],["footer",`ReactNode`,<>The action row along the bottom. Pass your own Buttons; the dialog supplies the placement.</>],["closeLabel",`string · default "Close dialog"`,<>The accessible name of the corner close button.</>],],notes:[<><strong>Focus is trapped and returned.</strong> Opening moves focus to the first focusable element inside; Tab and Shift+Tab cycle within the dialog; closing returns focus to whatever had it before.</>,<><strong>Three ways out, all of them call <code>onOpenChange(false)</code>:</strong> Escape, the corner close button, and a mousedown on the backdrop. The dialog never closes itself — you own the state, so a confirm step can refuse.</>,<>It is <code>role="dialog"</code> with <code>aria-modal</code>, labelled by the title and described by the description when there is one.</>,<>Put the destructive action in the footer on the right and the cancel beside it as a ghost — that pairing is what the preview shows, and it is the one to copy.</>,<><strong>The backdrop is a <code>position: fixed</code> box, so where the dialog is rendered matters.</strong> Mount it anywhere under an ancestor that carries a transform, a filter, <code>will-change</code> or <code>contain</code>, and the scrim covers that ancestor instead of the page while its blur computes to <code>none</code>. Nothing warns. <a href="#overlays">Overlays</a> has the rule and the measurement behind it.</>,],preview:<DialogDemo/>},
 {id:"dropdown-menu",name:"DropdownMenu",group:"Overlays",summary:"Single-selection menu with keyboard navigation, click-outside dismissal, and menuitemradio semantics.",code:`import { DropdownMenu } from "@mithtech-bengaluru/tonaldepth-react";\n\n<DropdownMenu label="Standard" value="standard" onValueChange={console.log} items={[\n  { value: "standard", label: "Standard" },\n  { value: "express", label: "Express" },\n]} />`,options:[["items[]",`{ value, label, disabled? }`,<>One object per item. <code>value</code> is the key and what <code>onValueChange</code> reports.</>],["value / onValueChange",`string / (value) => void`,<>The selection is <strong>controlled</strong> — the menu holds no selection of its own. Store the value and pass it back, or nothing appears chosen.</>],["label",`ReactNode`,<>What the trigger reads. Pass the chosen item's label, which is why the demo above keeps it in the same state as <code>value</code>.</>],],notes:[<><strong>Single selection, with <code>menuitemradio</code> semantics.</strong> This is a chooser, not a list of commands — for a menu of actions, use <a href="#split-button">SplitButton</a>.</>,<>Open and closed <em>is</em> internal. Opening focuses the first enabled item; arrows wrap, Home and End jump; Escape closes and returns focus to the trigger; a mousedown outside closes it.</>,<>Choosing an item closes the menu and returns focus to the trigger, so the keyboard never lands somewhere the reader did not ask for.</>,<>A disabled item stays in the list and is skipped by the arrows, rather than disappearing — the reader can see that the option exists.</>,],preview:<DropdownDemo/>},
 {id:"toast",name:"Toast",group:"Feedback",summary:"Auto-dismissing status queue accessed through a provider and useToast hook. Carved out of the page with a 3px shade against a matching 3px highlight rather than floated on a drop shadow, and its category is the same lamp the Alert uses.",code:`import { ToastProvider, useToast, Button } from "@mithtech-bengaluru/tonaldepth-react";\n\nfunction SaveButton() {\n  const { toast } = useToast();\n  return <Button onClick={() => toast({ title: "Saved", variant: "success" })}>Save</Button>;\n}\n\nexport function App() {\n  return <ToastProvider><SaveButton /></ToastProvider>;\n}`,options:[["toast({ variant })",`"info" | "success" | "error" · default "info"`,<>The category, carried by the same lamp the <a href="#alert">Alert</a> uses. <code>error</code> renders with <code>role="alert"</code>; the other two take <code>role="status"</code>.</>],["toast({ duration })",`number`,<>Milliseconds before it dismisses itself, overriding the provider's default for this one toast. <code>0</code> makes it stay until dismissed.</>],["ToastProvider defaultDuration",`number · default 4000`,<>The dismissal time for every toast that does not set its own.</>],],notes:[<><strong>Wrap the app once in <code>ToastProvider</code>.</strong> It renders the viewport as well as holding the queue, so there is nothing else to place on the page.</>,<><code>useToast()</code> returns <code>toast</code> and <code>dismiss</code>. <code>toast(...)</code> returns the new toast's id, which is what you hand to <code>dismiss(id)</code> to take one away early.</>,<>Called outside the provider, <code>useToast</code> throws rather than silently doing nothing — a toast that never appears is worse to debug than an error at the call site.</>,<>A toast takes a <code>title</code> and an optional <code>description</code>. Keep the title a complete sentence: it is the part that gets read.</>,<>The strip is carved out of the page with a shade against a matching highlight rather than floated on a drop shadow, which is why it reads as part of the surface at any scroll position.</>,],preview:<ToastDemo/>},
 {id:"chart-container",name:"ChartContainer",group:"Surfaces & data",summary:"A chart, housed. A Frame with the slots a plot needs already wired — the caption in the head, the legend under the well, and the well run flush because a plot carries its own margins. Renders a figure, so the plot and its caption are announced as one thing.",code:`import { ChartContainer } from "@mithtech-bengaluru/tonaldepth-react";\n\n<ChartContainer title="Weekly signups" meta="Q3" legend={[{ label: "This week" }, { label: "Last week" }]}>\n  <svg viewBox="0 0 200 60"><polyline fill="none" stroke="currentColor" strokeWidth="2" points="0,50 40,40 80,20 120,30 160,10 200,25"/></svg>\n</ChartContainer>`,options:[["legend[]",`{ label, color? }`,<>One entry per series. <code>color</code> takes any CSS colour; left off, entries fall back to <code>--td-series-1</code> upward in order, which is the palette they should be using anyway.</>],["description",`string`,<>The chart's text alternative. It is visually hidden and wired to <code>aria-describedby</code> — so it is the only thing a screen reader gets from the plot.</>],["meta",`ReactNode`,<>The small value beside the title — a period, a unit, an as-of date.</>],],notes:[<><strong>Write the <code>description</code>.</strong> An SVG is opaque to assistive technology; without this the figure is a title and nothing else. Say what the chart shows and what the shape is, not that it is a line chart.</>,<>It renders a <code>figure</code> with a <code>figcaption</code>, so it is announced as one thing rather than a heading followed by loose graphics.</>,<><strong>You supply the SVG.</strong> There is no charting here — give the child a <code>width: 100%</code> and a <code>viewBox</code> and it scales with the card.</>,<><strong>It is a <a href="#frame">Frame</a>.</strong> A chart is a measured object, so it is shown in a well rather than offered on a plate — this component does not re-implement that pairing, it passes through to it. Reach for <code>Frame</code> directly when you need the eyebrow, a deeper well, or actions that are real controls.</>,],preview:<ChartContainer title="Weekly signups" meta="Q3" description="Weekly signups over the last six weeks." legend={[{label:"This week",color:"var(--td-brand)"},{label:"Last week",color:"var(--td-accent)"}]}><svg viewBox="0 0 200 60" style={{width:"100%",height:"120px",color:"var(--td-brand)"}}><polyline fill="none" stroke="currentColor" strokeWidth="2" points="0,50 40,40 80,20 120,30 160,10 200,25"/></svg></ChartContainer>},
 {id:"filter-bar",name:"FilterBar",group:"Surfaces & data",summary:"Multi-select chip row with counts, per-chip color, disabled chips, and clear-all action.",code:`import { FilterBar } from "@mithtech-bengaluru/tonaldepth-react";\n\n<FilterBar options={[\n  { value: "open", label: "Open", count: 42, color: "brand" },\n  { value: "in-review", label: "In review", count: 12 },\n]} />`,options:[["options[]",`{ value, label, count?, color?, disabled? }`,<>One chip each. <code>count</code> prints the number in the machine face; <code>color</code> takes <code>"brand"</code> or <code>"accent"</code>; <code>disabled</code> greys the chip without removing it.</>],["value / defaultValue",`string[]`,<>An <strong>array</strong> — this is multi-select. Pass <code>value</code> with <code>onValueChange</code> to control it, or <code>defaultValue</code> to leave it uncontrolled.</>],["clearLabel",`string · default "Clear filters"`,<>The words on the clear-all control, which only appears once something is selected.</>],],notes:[<><strong>Chips are toggles, not links.</strong> Each is a button carrying <code>aria-pressed</code>, so a screen reader hears the on or off state rather than having to infer it from the styling.</>,<>Clearing calls <code>onValueChange</code> with an empty array like any other change, so a controlled bar needs no special case for it.</>,<>Disabled chips are deliberately left in place. Removing an option because it currently has no rows tells the reader the filter does not exist.</>,<><code>label</code> names the group. Set it whenever there is more than one filter bar on a page — “Status filters”, “Owner filters”.</>,],preview:<FilterBar options={[{value:"open",label:"Open",count:42,color:"brand"},{value:"in-review",label:"In review",count:12},{value:"done",label:"Done",count:128,color:"accent"},{value:"archived",label:"Archived",disabled:true}]} defaultValue={["open"]}/>},

 {id:"application-shell",name:"ApplicationShell",group:"App patterns",summary:"Grouped sidebar navigation, identity slot, main page header, and content area for signed-in app pages.",code:`import { ApplicationShell } from "@mithtech-bengaluru/tonaldepth-react";\n\n<ApplicationShell identity={<b>Acme</b>}\n  title="Overview" description="Signals from every workspace."\n  sections={[\n    { label: "Work", items: [{ label: "Dashboard", href: "#", current: true }, { label: "Projects", href: "#", count: 12 }] },\n  ]}\n>\n  Content lives here.\n</ApplicationShell>`,options:[["sections[]",`{ label?, items }`,<>Groups in the sidebar. A section's <code>label</code> is optional, so an ungrouped first block is just a section without one.</>],["sections[].items[]",`{ label, href, current?, count? }`,<><code>current</code> marks the open page; <code>count</code> prints a number on the right of the row in the machine face.</>],["identity",`ReactNode`,<>The top-left slot: the workspace, the tenant, the account switcher.</>],["sidebarFooter",`ReactNode`,<>The bottom of the sidebar — a plan badge, a build number, a support link.</>],],notes:[<><strong><code>title</code> is the page header, not the app name.</strong> The shell renders the header for you from <code>title</code>, <code>description</code> and <code>actions</code>; the app's own name belongs in <code>identity</code>.</>,<><code>children</code> is the content area, and it owns its own layout. Put a <a href="#page-patterns">page pattern</a> in it rather than laying the page out here.</>,<><code>sidebarLabel</code> names the sidebar navigation landmark; it defaults to “Application navigation”.</>,<>Marking two items <code>current</code> is not prevented and is almost always a routing bug. One page, one current item.</>,],preview:<ApplicationShell identity={<b>Acme</b>} title="Overview" description="Signals from every workspace." sections={[{label:"Work",items:[{label:"Dashboard",href:"#",current:true},{label:"Projects",href:"#",count:12}]},{label:"Team",items:[{label:"Members",href:"#"},{label:"Billing",href:"#"}]}]} sidebarFooter={<Badge variant="success">Verified</Badge>} actions={<Button size="sm">Invite</Button>}><Card><CardHeader><CardTitle>Recent activity</CardTitle></CardHeader><CardContent>Signals appear here.</CardContent></Card></ApplicationShell>},
 {id:"page-patterns",name:"Page patterns",group:"App patterns",summary:"Composed page templates: DashboardPage, DashboardPanel, DataManagementPage, PageState.",code:`import { DashboardPage, DashboardPanel, KpiCard, KpiGrid, PageState } from "@mithtech-bengaluru/tonaldepth-react";\n\n<DashboardPage title="Overview"\n  metrics={<KpiGrid><KpiCard label="Open" value="42" trend="up" delta="+6"/></KpiGrid>}\n>\n  <DashboardPanel title="Recent activity" span={2}>...</DashboardPanel>\n</DashboardPage>`,options:[["DashboardPanel span",`1 | 2 | "full" · default 1`,<>How many bento columns the panel takes. <code>"full"</code> is the whole row — for the one panel a dashboard is actually about.</>],["PageState variant",`"empty" | "loading" | "error"`,<>Which of the three non-content states the page is in. Required: a PageState with no variant is a state nobody has decided.</>],["DashboardPage filters / metrics",`ReactNode`,<>Two optional bands between the header and the bento — a <a href="#filter-bar">FilterBar</a> and a <a href="#kpi">KpiGrid</a> are what they are shaped for.</>],["DataManagementPage toolbar / footer",`ReactNode`,<>The band above the panel and the row below it — search and bulk actions above, pagination and counts below.</>],],notes:[<><strong>Four exports.</strong> <code>DashboardPage</code> is a header plus optional filters and metrics over a bento grid. <code>DashboardPanel</code> is one cell of that grid. <code>DataManagementPage</code> is a header, a toolbar, one panel and a footer — the list-and-table page. <code>PageState</code> is the empty, loading and error state.</>,<>A <code>DashboardPanel</code> with a <code>title</code> is labelled by it automatically, so each cell is its own landmark for a screen reader. A panel with no title falls back to whatever <code>aria-labelledby</code> you pass. Its <code>meta</code> sits opposite the title in the panel's head — a count, a period, a last-updated stamp — and the head only renders when one of the two is present. <code>span</code> is how many grid columns the cell takes.</>,<><strong><code>DataManagementPage</code> is the list-and-table page.</strong> <code>title</code>, an optional <code>description</code> and <code>actions</code> make the header; <code>toolbar</code> is the row for a <a href="#filter-bar">FilterBar</a> or a <a href="#search-bar">SearchBar</a>; <code>children</code> fill the single panel below it — usually a <a href="#table">Table</a> in its <code>TableContainer</code>; and <code>footer</code> is the result count or the pager.</>,<><code>PageState</code> takes <code>title</code>, an optional <code>description</code>, an <code>illustration</code> slot and one <code>action</code>. One action — a state offering three ways out is a state nobody escapes.</>,<>These are compositions of the primitives, not a layout engine. When a page does not fit one, build it out of <a href="#card">Card</a>, <a href="#frame">Frame</a> and the grids rather than bending a pattern.</>,],preview:<div className="stack"><DashboardPage title="Overview" description="Signals across every workspace." metrics={<KpiGrid><KpiCard label="Open" value="42" delta="+6" trend="up"/><KpiCard label="Resolved" value="128" delta="+18%" trend="up"/></KpiGrid>}><DashboardPanel title="Recent activity" span="full">Signals appear here.</DashboardPanel></DashboardPage><DataManagementPage title="Engagements" description="Every active implementation, and who is on it." actions={<Button size="sm" variant="primary">New engagement</Button>} footer={<span className="hint">3 of 24 shown</span>}><TableContainer><Table><TableHead><TableRow><TableHeader>Client</TableHeader><TableHeader>Platform</TableHeader><TableHeader>Stage</TableHeader></TableRow></TableHead><TableBody><TableRow><TableCell>Rework Industries</TableCell><TableCell>ERPNext</TableCell><TableCell><Badge variant="success">Live</Badge></TableCell></TableRow><TableRow><TableCell>Coastal Freight</TableCell><TableCell>Medusa</TableCell><TableCell><Badge>Build</Badge></TableCell></TableRow><TableRow aria-selected="true"><TableCell>Northwind Foods</TableCell><TableCell>n8n</TableCell><TableCell><Badge variant="brand">Discovery</Badge></TableCell></TableRow></TableBody></Table></TableContainer></DataManagementPage><PageState variant="empty" title="Nothing yet" description="Add your first project to see signals here." action={<Button>New project</Button>}/></div>},
 {id:"filament-button",name:"FilamentButton",group:"Actions",summary:"A tab button that reports its state with a lit filament instead of a fill. Three parts, two of which move independently: the row sinks as it is reached for, the icon tile rides above the row and sinks with it, and the filament only lights — off, dim on hover, white-hot at the press, full while held. The strip runs down the inline-start edge, or along the top for a horizontal bar.",code:`import { FilamentButton } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* Four states. \`active\` is the one that survives the pointer leaving. */}\n<FilamentButton label="Overview" icon={<GridIcon />} />\n<FilamentButton label="Settings" icon={<GearIcon />} active />\n\n{/* Horizontal, for a bar. */}\n<FilamentButton edge="top" label="Alerts" icon={<BellIcon />} tone="brand" />\n\n{/* The collapsed rail — glyph only, so it needs a name. */}\n<FilamentButton size="sm" icon={<GridIcon />} aria-label="Overview" />`,options:[["active",`boolean · default false`,<>Lit and held — the tab whose panel is open. This is the fourth state, and it is the one hover cannot do: the filament stays on when the pointer leaves.</>],["icon",`ReactNode`,<>Goes in the tile — a square button of its own inside the row, raised at rest and sinking as the row is reached for. Pass a filled glyph: the glyph is the lamp and it lights by colour alone, so an outline mark has nothing to light.</>],["tone",`"green" | "brand" | "accent" | "error" · default "green"`,<>What the filament lights. These are the system's categories, not free colour.</>],["edge",`"start" | "top" · default "start"`,<><code>start</code> runs the filament down the inline-start edge — the vertical tab. <code>top</code> lays it along the top edge, for a horizontal bar.</>],["size",`"sm" | "md" · default "md"`,<>The housing. <code>sm</code> is the collapsed-rail form, which is where the icon-only variant belongs.</>],["glow",`string`,<>Any CSS colour, overriding the tone. Mixed at the <code>--td-filament-*</code> strengths, so it still rides the same four-state ladder.</>],],notes:[<><strong>Three parts, and two of them move.</strong> The <em>row</em> is one button — it sinks on hover and deeper on the press. The <em>tile</em> holding the glyph is the other — it rides above the row at rest and sinks with it, keeping a shadow in every state so it always reads as its own control. The <em>filament</em> never moves or grows; it only lights. Nothing is required of you to get this: pass a <code>label</code> and an <code>icon</code>.</>,<><strong>The glyph lights by colour, never by glow.</strong> It steps unlit ink → the tone → white-hot at the press → full tone while held. Do not add a <code>drop-shadow</code> to an icon you pass in: a halo behind a glyph this small paints as a dark smear, and the design system's own row does not have one.</>,<><strong>Four states, not three:</strong> off at rest, dim on hover, held while its panel is open, and brightest for the press. If two of them look the same, the composition has lost a step.</>,<><strong>Omit <code>label</code> for the icon-only rail form and pass <code>aria-label</code></strong> — a glyph is not a name.</>,<><code>icon</code> must be a filled glyph. An outline has almost no alpha for the filament's glow to bloom from.</>,<>This is the button on its own. For a whole tab set with the keyboard pattern and the panels wired up, use <a href="#side-tabs">SideTabs</a> — it is built from this.</>,<>Native button attributes pass through, <code>disabled</code> and <code>onClick</code> included.</>,],preview:<div style={{display:"grid",gap:20}}><div style={{display:"flex",gap:8,flexWrap:"wrap"}}><FilamentButton label="Rest" icon={<IGrid/>}/><FilamentButton label="Held" icon={<IGear/>} active/><FilamentButton label="Papaya" icon={<IBell/>} tone="brand" active/><FilamentButton label="Azure" icon={<IGrid/>} tone="accent" active/><FilamentButton label="Disabled" icon={<IGear/>} disabled/></div><div style={{display:"flex",gap:8,flexWrap:"wrap"}}><FilamentButton edge="top" label="Top edge" icon={<IGrid/>}/><FilamentButton edge="top" label="Top, held" icon={<IGear/>} active/></div><div style={{display:"flex",gap:8}}><FilamentButton size="sm" icon={<IGrid/>} aria-label="Overview"/><FilamentButton size="sm" icon={<IGear/>} aria-label="Settings" active/><FilamentButton size="sm" icon={<IBell/>} aria-label="Alerts" tone="error" active/></div></div>},
 {id:"side-tabs",name:"SideTabs",group:"Navigation",summary:"The sideways tab. A vertical rail whose selection is reported by a lit filament rather than a fill — with labels on desktop, collapsed to glyphs in a narrow rail, or laid horizontally for mobile. Full WAI-ARIA tabs keyboard pattern.",code:`import { SideTabs } from "@mithtech-bengaluru/tonaldepth-react";\n\n<SideTabs\n  label="Account"\n  items={[\n    { id: "overview", label: "Overview", icon: <GridIcon />, panel: <p>…</p> },\n    { id: "settings", label: "Settings", icon: <GearIcon />, panel: <p>…</p> },\n  ]}\n/>\n\n{/* layout="rail" hides the labels; layout="bar" lays it horizontally. */}\n<SideTabs layout="bar" items={items} />`,options:[["layout",`"sidebar" | "rail" | "bar" · default "sidebar"`,<><code>sidebar</code> is the desktop rail with labels. <code>rail</code> collapses to glyphs only. <code>bar</code> lays the tabs horizontally with the filament along the top — the mobile form, and the one for when vertical space is the scarce axis.</>],["items[]",`{ id, label, icon?, panel?, ariaLabel?, disabled? }`,<><code>id</code> is the stable key and what <code>value</code> and <code>onValueChange</code> speak in. <code>panel</code> is the content for that tab.</>],["tone",`"green" | "brand" | "accent" | "error" · default "green"`,<>The filament's colour when lit, shared with <a href="#filament-button">FilamentButton</a>.</>],["value / defaultValue",`string`,<>Control it with <code>value</code> and <code>onValueChange</code>, or leave it uncontrolled. With neither, the first enabled tab is selected.</>],],notes:[<><strong>Every tab is a <a href="#filament-button">FilamentButton</a>,</strong> so each one carries the same three parts: a row that sinks as it is reached for, an icon tile that rides above the row and sinks with it, and a filament that only lights. Give each item an <code>icon</code> and the tile appears; leave it off and the row is label-only.</>,<><strong><code>rail</code> hides the labels, so each item needs an <code>icon</code></strong> — and an <code>ariaLabel</code> too whenever <code>label</code> is not a plain string, because there is no visible text to fall back on.</>,<><strong>Selection follows focus.</strong> Arrows move — up and down in <code>sidebar</code> and <code>rail</code>, left and right in <code>bar</code> — Home and End jump to the ends, and disabled tabs are skipped rather than focused and refused.</>,<>The list is a roving tabstop, so one Tab press moves from the rail into the open panel.</>,<><code>label</code> names the tab list for a screen reader. Set it whenever a page has more than one.</>,<><code>panel</code> is optional — leave it off and the component is a selection rail whose content you render yourself from <code>onValueChange</code>.</>,],preview:<div style={{display:"grid",gap:28}}><SideTabs label="Desktop sidebar" items={[{id:"overview",label:"Overview",icon:<IGrid/>,panel:<p className="sub" style={{margin:0}}>The sidebar form. The filament stays lit while this panel is open — that is the fourth state, and it is the one hover cannot do.</p>},{id:"settings",label:"Settings",icon:<IGear/>,panel:<p className="sub" style={{margin:0}}>Arrow keys move between tabs and selection follows focus. Home and End jump to the ends.</p>},{id:"alerts",label:"Alerts",icon:<IBell/>,panel:<p className="sub" style={{margin:0}}>A disabled tab is skipped by the arrows rather than focused and refused.</p>},{id:"billing",label:"Billing",disabled:true,panel:<p>Unreachable.</p>}]}/><SideTabs layout="bar" tone="brand" label="Mobile bar" items={[{id:"a",label:"Despatch",icon:<IGrid/>,panel:<p className="sub" style={{margin:0}}>The bar form puts the filament along the top edge. Use it when vertical space is the scarce axis.</p>},{id:"b",label:"Returns",icon:<IBell/>,panel:<p className="sub" style={{margin:0}}>The list scrolls itself rather than taking the page's horizontal scroll with it.</p>},{id:"c",label:"Invoices",icon:<IGear/>,panel:<p className="sub" style={{margin:0}}>Third panel.</p>}]}/><SideTabs layout="rail" tone="accent" label="Collapsed rail" items={[{id:"a",label:"Overview",icon:<IGrid/>,panel:<p className="sub" style={{margin:0}}>The rail hides its labels, so each tab takes its name from the label string.</p>},{id:"b",label:"Settings",icon:<IGear/>,panel:<p className="sub" style={{margin:0}}>Shorter filament, smaller housing — for a collapsed sidebar or a mobile rail.</p>}]}/></div>},
 {id:"split-button",name:"SplitButton",group:"Actions",summary:"One action with its alternatives folded behind a disclosure. Give it a default and it acts at once, with the menu as an override; withhold the default and it waits until the reader chooses, for when the choice is load-bearing.",code:`import { SplitButton } from "@mithtech-bengaluru/tonaldepth-react";\n\nconst CHANNELS = [\n  { id: "whatsapp", label: "WhatsApp", detail: "+91 80 4718 2200", icon: <WhatsAppIcon /> },\n  { id: "call", label: "Call", detail: "+91 80 4718 2200", icon: <CallIcon /> },\n  { id: "email", label: "Email", detail: "hello@mith.tech", icon: <EmailIcon /> },\n];\n\n{/* Defaulted — "any" takes the first enabled action and fires at once. */}\n<SplitButton actions={CHANNELS} defaultAction="any" onAction={a => open(a.id)} />\n\n{/* Forced select — inert until the reader picks a channel. */}\n<SplitButton actions={CHANNELS} placeholder="Contact us via…" />`,options:[["renderLink",`(props: { className, href, children }) => ReactNode`,<>Hand your router the primary half, for a chosen action that carries an <code>href</code>. The <code>onAction</code> that half would have fired is <strong>not</strong> passed through it — an action that both navigates and fires a handler is two acts on one press. Ignored when the chosen action has no <code>href</code>, and when the button is disabled or still waiting to be chosen.</>],["defaultAction",`an action id`,<>The primary half fires that action at once, and the menu is an override.</>],["defaultAction",`"any"`,<>Takes the first enabled action. The right default for a “contact us” where every channel reaches the same desk.</>],["defaultAction",`omitted`,<><strong>Forced select.</strong> The primary half stays inert until the reader picks a channel — for when the choice is load-bearing and a wrong default costs them something.</>],["actions[]",`{ id, label, icon?, detail?, href?, disabled? }`,<><code>detail</code> is the second line in the menu — the number, the address, the handle. <code>href</code> turns the primary half into an anchor when that action is the chosen one.</>],["placeholder",`ReactNode · default "Choose an option"`,<>What the primary half reads before anything is chosen. Only visible in forced-select mode.</>],["menuLabel",`string · default "More options"`,<>The accessible name of the disclosure half.</>],],notes:[<><strong>An action with an <code>href</code> makes the primary half an anchor</strong>, and <code>renderLink</code> hands that anchor to your router. Without it a split button whose default action is a link is a document load. The menu half is always a button — picking a channel is not navigation.</>,<><strong>Two callbacks, two questions.</strong> <code>onAction</code> fires with the action that ran — both when the primary half is pressed and when one is picked from the menu. <code>onValueChange</code> only reports which action is now chosen.</>,<><code>value</code> makes the choice controlled; without it the button keeps its own.</>,<>Every label is rendered stacked in one grid cell, so the housing is as wide as its longest option and does not resize when the selection changes.</>,<>In the menu: arrows move, Home and End jump, Escape closes, and a click outside dismisses it. A disabled action stays listed and is skipped.</>,<>The two halves share one housing and are divided by a carved seam. Neither half is filled with the brand colour — the chosen channel is reported by its glyph.</>,],preview:<div style={{display:"grid",gap:20,justifyItems:"start"}}><SplitButton defaultAction="any" menuLabel="Choose a channel" actions={[{id:"whatsapp",label:"WhatsApp",detail:"+91 80 4718 2200",icon:<IWhatsApp/>},{id:"call",label:"Call",detail:"+91 80 4718 2200",icon:<IPhone/>},{id:"email",label:"Email",detail:"hello@mith.tech",icon:<IMail/>}]}/><SplitButton placeholder="Contact us via…" menuLabel="Choose a channel" actions={[{id:"whatsapp",label:"WhatsApp",detail:"+91 80 4718 2200",icon:<IWhatsApp/>},{id:"call",label:"Call",detail:"+91 80 4718 2200",icon:<IPhone/>},{id:"email",label:"Email",detail:"hello@mith.tech",icon:<IMail/>},{id:"post",label:"Post",detail:"Not available",icon:<IMail/>,disabled:true}]}/></div>},
 {id:"search-bar",name:"SearchBar",group:"Forms",summary:"A search field, carved into the surface rather than raised — a place to put something is never lifted. Optional suggestion listbox following the ARIA combobox pattern, in three sizes.",code:`import { SearchBar } from "@mithtech-bengaluru/tonaldepth-react";\n\n<SearchBar placeholder="Search products" onSubmit={q => run(q)} />\n\n{/* With suggestions it is a combobox — arrows move, Escape closes it\n    without clearing what was typed. */}\n<SearchBar\n  suggestions={[{ id: "erpnext", label: "ERPNext", detail: "22 products" }]}\n  onSuggestionSelect={s => go(s.id)}\n  showSubmit\n/>`,options:[["size",`"sm" | "md" | "lg" · default "md"`,<>The field's height and type size. <code>lg</code> is the page-level search; <code>sm</code> filters a table.</>],["block",`boolean · default false`,<>Fills the container instead of taking the field's own natural width.</>],["showSubmit",`boolean · default false`,<>Renders a visible submit button. Enter submits either way, so this is about affordance rather than function.</>],["suggestions[]",`{ id, label, detail? }`,<>Rendered as a listbox under the field, <strong>exactly as given</strong>. <code>detail</code> is the second line — the section, the category, the count.</>],["value / defaultValue",`string`,<>Control the query with <code>value</code> and <code>onValueChange</code>, or leave it uncontrolled with <code>defaultValue</code>.</>],["expand",`boolean · default false`,<><strong>The field grows when it is focused and settles back when it is left.</strong> For a field in chrome, where it has to be small until somebody means to use it. The panel drops from the grown field, so the two read as one movement rather than a box appearing beside a box that just changed size. <code>--td-search-expanded</code> is the width it grows to.</>],["trigger",`boolean · default false`,<><strong>Draws the field as a button that opens a search somewhere else</strong> — a command palette, usually. Same carved housing, same mark, same heights, so it does not read as a second kind of search field; it just does not accept typing. <code>placeholder</code> becomes the visible label and <code>onClick</code> is yours.</>],["shortcut",`ReactNode | false`,<>The hint on a <code>trigger</code>. Defaults to the platform’s own — <code>⌘K</code> on a Mac, <code>Ctrl K</code> everywhere else, resolved after mount because the server has no idea what the reader is typing on. It is a <em>hint</em>: binding the key is yours, because only you know what it opens.</>]],notes:[<><strong>It does no matching.</strong> The suggestion list renders in the order you pass it, so the consumer keeps control of ranking — mith.tech drives this from Fuse.js, and a server route or a plain <code>filter</code> works the same way. <strong>Sort before passing.</strong></>,<><strong>With <code>suggestions</code> it is an ARIA 1.2 combobox.</strong> The field keeps focus while <code>aria-activedescendant</code> moves through the list; Enter takes the highlighted suggestion, or submits the query when nothing is highlighted; Escape closes the list <em>without</em> clearing what was typed.</>,<><code>onSubmit</code> fires on Enter and on the submit button, with the current query. <code>onSuggestionSelect</code> fires instead when a suggestion is taken.</>,<>A blur that lands inside the component — onto a suggestion — is not a dismissal. Only focus leaving the whole thing closes the list.</>,<>The field is carved into the surface rather than raised: a place to put something is never lifted. The magnifier is a mark, not a control, and takes no glow.</>,<><strong>The suggestion list is the field continuing, not a card near it.</strong> It was drawn floating a gap below, which reads as two objects — a field, and something that appeared beside it. Now it is flush, square where the two meet, rounded only where the pair ends, with a carved seam on the join, and it unfolds downward rather than appearing. Use it for searching inside a page, or for type-and-pick — a product, a customer, a tag.</>,<><strong>Three behaviours, one component.</strong> The plain field with its panel is where searching happens in a page. <code>expand</code> is the same field for chrome, small until it is used. <code>trigger</code> is not a field at all — it is the way into a <a href="#spotlight">Spotlight</a> that searches the whole product. These docs use both — the header is a <code>trigger</code>, because a chrome field that types looks like it searches something narrower than the console does, and then a reader has to learn which one they are in.</>,<><code>clearLabel</code> and <code>submitLabel</code> are accessible names, so translate them with the rest of the page.</>,],preview:<div style={{display:"grid",gap:46}}><div><p className="sub" style={{margin:"0 0 12px",fontFamily:"var(--td-font-mono)",fontSize:"0.62rem",letterSpacing:"0.14em",textTransform:"uppercase"}}>One · The field and its panel — type “halo”, or “migration”</p><SearchBarBench placeholder="Search these docs"/><p className="hint" style={{margin:"12px 0 0"}}>The list is the field continuing: flush, square where they meet, unfolding downward. <kbd>↑</kbd><kbd>↓</kbd> move and <kbd>↵</kbd> opens; <strong>Escape closes the list without clearing what you typed.</strong></p></div><div><p className="sub" style={{margin:"0 0 12px",fontFamily:"var(--td-font-mono)",fontSize:"0.62rem",letterSpacing:"0.14em",textTransform:"uppercase"}}>Two · The same field, grown on focus — click into it</p><div style={{maxWidth:620}}><SearchBarBench expand block={false} size="sm" placeholder="Search these docs"/></div><p className="hint" style={{margin:"12px 0 0"}}><code>expand</code> — small until somebody means to use it, then wide enough for a result and its reason. The panel drops from the grown field, so the two are one movement. For chrome: a header, a toolbar, a table’s filter row.</p></div><div><p className="sub" style={{margin:"0 0 12px",fontFamily:"var(--td-font-mono)",fontSize:"0.62rem",letterSpacing:"0.14em",textTransform:"uppercase"}}>Three · The trigger — it opens a console instead</p><div className="row" style={{gap:14,alignItems:"center",flexWrap:"wrap"}}><SearchBar trigger size="sm" placeholder="Search components"/><SearchBar trigger placeholder="Search the product"/><SearchBar trigger size="lg" placeholder="Search everything" shortcut={false}/></div><p className="hint" style={{margin:"12px 0 0"}}>Not a field at all — a button wearing the field’s housing, with the platform’s shortcut on it. It is what the header of these docs uses: press it, or ⌘K. <strong>Binding the key is yours</strong>, because only you know what it opens.</p></div></div>},
 {id:"progress",name:"Progress",group:"Feedback",summary:"A determinate meter. The track is carved into the surface and the filled length is the only thing that carries colour — it is a measured quantity, like a chart series, so it is allowed one.",code:`import { Progress } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* The whole meter line: what, how far, and the percentage. */}\n<Progress label="Deployment" detail="4 of 12" value={33} />\n\n{/* Bare, for a meter inside a row that already says what it is. */}\n<Progress value={75} showValue={false} aria-label="Migration" />\n\n{/* Only when the total genuinely is not known. */}\n<Progress label="Indexing" indeterminate />`,options:[["value",`number`,<>0–100, clamped. It is rounded for display and for <code>aria-valuenow</code>, so the number a reader hears is the number they see.</>],["tone",`"brand" | "accent" | "green" | "error" · default "brand"`,<>Which category the filled length carries. Use it to say what <em>kind</em> of progress this is — <code>error</code> for a budget being consumed, <code>green</code> for a target being met — not to make a row look different from its neighbour.</>],["label / detail",`ReactNode`,<><code>label</code> is what is progressing; <code>detail</code> is the machine face of the count (<code>4 of 12</code>) and is set in mono beside it. Both are optional and the head disappears when neither is present.</>],["showValue",`boolean · default true`,<>The percentage at the end of the meter line. Turn it off where the count in <code>detail</code> already says it.</>],["indeterminate",`boolean · default false`,<>A short length sweeping the track, and no <code>aria-valuenow</code>. Reach for it only when the total is genuinely unknown.</>],],notes:[<><strong>Name it.</strong> With no <code>label</code>, pass <code>aria-label</code> — a bare meter reaches a screen reader as an unnamed number. A string <code>label</code> is used automatically.</>,<><strong>A determinate bar is the better answer.</strong> <code>indeterminate</code> animates forever and tells the reader nothing; if you can compute a fraction, compute it. Under reduced motion the sweep stops rather than spinning silently.</>,<>The filled length carries colour because it is data. Nothing else here does — the track is depth, and there is no tinted plate behind the row.</>,<>For a step-by-step sequence rather than a fraction, use <a href="#timeline">Timeline</a>.</>,],preview:<div className="stack" style={{gap:18}}><Progress label="Deployment" detail="4 of 12" value={33}/><Progress label="Migration" detail="9 of 12" value={75} tone="accent"/><Progress label="Budget consumed" detail="₹8.2L of ₹9L" value={91} tone="error"/><Progress label="Indexing" indeterminate/></div>},
 {id:"copy-chip",name:"CopyChip",group:"Actions",summary:"A machine value the reader can take with them — a host, a command, a URL. Set in mono, and it reports its own success in ink and glyph rather than behind a tinted plate.",code:`import { CopyChip } from "@mithtech-bengaluru/tonaldepth-react";\n\n<CopyChip value="ssh root@po5.mith.tech" />\n\n{/* A long value with a short face. */}\n<CopyChip value="https://github.com/mithtech/commercely" label="commercely repo" />\n\n{/* Hook it up to whatever you count. */}\n<CopyChip value={key} onCopied={() => track("api-key-copied")} />`,options:[["value",`string`,<>What goes on the clipboard, and the visible text unless <code>label</code> overrides it.</>],["label",`ReactNode`,<>A shorter face for a long value. The clipboard still gets <code>value</code>, so the two can differ freely.</>],["holdFor",`number · default 1600`,<>How long the copied state holds, in ms.</>],["copiedLabel",`string · default "Copied"`,<>Announced in the live region while the copied state holds. Translate it with the rest of the page.</>],["onCopied",`(value: string) => void`,<>Fires after a successful write — the place to count the event.</>],],notes:[<><strong>Success is ink, not a fill.</strong> The glyph swaps to the accept mark and the ink steps to green for a moment; the housing does not change colour. A category arrives as ink and light, never as a wash, so the design system's own green plate is deliberately not reproduced.</>,<><strong>It needs a secure context.</strong> <code>navigator.clipboard</code> is unavailable on plain <code>http://</code>. Where it is missing the chip selects its own text instead, so the reader can copy by hand rather than pressing a dead button — but the copied state does not fire, because nothing was copied.</>,<><strong>It names itself.</strong> The accessible name is <code>Copy {"{value}"}</code>, because the visible text is the value and says nothing about what the control does. Pass <code>aria-label</code> to override. The copied state is announced through a polite live region, so it is heard as well as seen.</>,<>Everything native passes through — <code>disabled</code>, <code>onClick</code> (yours runs first; call <code>preventDefault</code> to stop the copy), <code>title</code>.</>,],preview:<div className="stack" style={{gap:10,alignItems:"flex-start"}}><CopyChip value="ssh root@po5.mith.tech"/><CopyChip value="https://github.com/mithtech/commercely" label="commercely repo"/><CopyChip value="pnpm add @mithtech-bengaluru/tonaldepth-react"/><p className="hint" style={{margin:0}}>Press one: the glyph becomes the accept mark and the ink steps to green. The housing holds its colour throughout.</p></div>},
 {id:"toc",name:"TableOfContents",group:"Navigation",summary:"The on-this-page rail. The seam down its side is a filament — always present, off and grey — and the section being read lights its own segment. Nothing moves, so the rail never reflows as the reader scrolls.",code:`import { TableOfContents } from "@mithtech-bengaluru/tonaldepth-react";\n\n<TableOfContents\n  current={active}\n  items={[\n    { id: "scope", label: "What the engagement covers" },\n    { id: "timeline", label: "Timeline and governance gates" },\n    { id: "gate-1", label: "Gate 1 — discovery sign-off", sub: true },\n    { id: "cost", label: "What it costs" },\n  ]}\n/>`,options:[["items[]",`{ id, label, sub? }`,<><code>id</code> is the heading's id without the <code>#</code> — it becomes the href and is what <code>current</code> is matched against. <code>sub</code> indents an entry as a second-level heading. Two levels is the limit on purpose: a rail deeper than that is a document outline, not a way to move around a page.</>],["current",`string`,<>The id of the section being read. Lights that entry's filament and rests the row recessed.</>],["label",`ReactNode · default "On this page"`,<>The heading above the list. Pass <code>null</code> to drop it where the surrounding layout already says it.</>],["ariaLabel",`string · default "On this page"`,<>Names the navigation landmark. Keep it even when <code>label</code> is dropped — it is the only name the landmark has.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor. Given the class, the href, the children and the <code>aria-current</code> state, return the element.</>],],notes:[<><strong>It does not track scrolling, and that is deliberate.</strong> You pass <code>current</code> — from an IntersectionObserver, or your router. Owning it here would mean guessing a root margin that suits every page, and it never does. The rail is the display; deciding which section is being read is the page's job.</>,<><strong>The seam is one line that lights, not a line that appears.</strong> Off is grey glass, so the rail's geometry is identical in every state and nothing reflows under a scrolling reader.</>,<>Each entry takes the row press — hover sinks it, the press sinks it deeper, and the current one rests recessed. <code>aria-current="true"</code> is set on that entry, which is what a screen reader reads.</>,<>In-page anchors are the default and are usually right here. Reach for <code>renderLink</code> when the rail spans routes rather than headings.</>,],preview:<TableOfContents current="timeline" items={[{id:"scope",label:"What the engagement covers"},{id:"timeline",label:"Timeline and governance gates"},{id:"gate-1",label:"Gate 1 — discovery sign-off",sub:true},{id:"gate-2",label:"Gate 2 — cutover readiness",sub:true},{id:"cost",label:"What it costs"},{id:"next",label:"Next step"}]}/>},
 {id:"range",name:"Range",group:"Forms",summary:"A single-value slider on a carved track. A real input[type=range], so the keyboard, the pointer and every assistive technology behave natively — only the track and the thumb are restyled.",code:`import { Range } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Range\n  label="Team size"\n  min={1}\n  max={40}\n  defaultValue={12}\n  format={n => n + ' people'}\n  showBounds\n/>\n\n{/* Controlled. */}\n<Range label="Budget" value={budget} onChange={e => setBudget(+e.target.value)} max={2000000} step={50000} />`,options:[["value / defaultValue",`number`,<>Controlled with <code>value</code> plus <code>onChange</code>; uncontrolled with <code>defaultValue</code>. Left off entirely it starts at <code>min</code>.</>],["min / max / step",`number · default 0 / 100 / 1`,<>The range and its granularity, passed straight to the input, so the keyboard steps by <code>step</code> and Page Up/Down by ten of them.</>],["label",`ReactNode`,<>What is being set. It renders a real <code>label</code> wired to the input, so clicking it focuses the slider.</>],["format",`(value: number) => ReactNode`,<>The current value in the reader's own units — <code>₹4,50,000</code>, <code>12 weeks</code>. Shown in mono at the end of the label row, and reused for the bounds when <code>showBounds</code> is on.</>],["showBounds",`boolean · default false`,<>Prints the min and max under the track. Worth it when the scale is not obvious from the value alone.</>],],notes:[<><strong>It is a real range input.</strong> Arrow keys, Home/End, Page Up/Down, touch dragging and every screen reader's slider mode work because nothing was rebuilt — the track and thumb are reached through the vendor pseudo-elements. That is also why there is no two-handle form here: a native range has one thumb, and a second one is a different component rather than a prop.</>,<><strong>Give it a name.</strong> With no <code>label</code>, pass <code>aria-label</code>. A slider announced only as a number tells the reader how much of nothing.</>,<>The filled length is the one thing carrying colour, for the same reason <a href="#progress">Progress</a>'s bar is: it is a measured quantity rather than decoration.</>,<>Everything native passes through — <code>disabled</code>, <code>name</code>, <code>form</code>, <code>onInput</code>, <code>aria-*</code>.</>,],preview:<div className="stack" style={{gap:22}}><Range label="Team size" min={1} max={40} defaultValue={12} format={n=>`${n} people`} showBounds/><Range label="Go-live window" min={4} max={52} defaultValue={11} step={1} format={n=>`${n} weeks`}/><Range label="Disabled" defaultValue={40} disabled format={n=>`${n}%`}/></div>},
 {id:"data-list",name:"DataList",group:"Surfaces & data",summary:"Four to six fields about one record. A table answers how records compare; this answers what one record is — below about six fields a header row is overhead, and the field name belongs beside its value.",code:`import { DataList } from "@mithtech-bengaluru/tonaldepth-react";\n\n<DataList\n  label="Engagement detail"\n  rows={[\n    { label: "Engagement", value: "Commercely · Medusa replatform", meta: "11 weeks" },\n    { label: "Stack", value: "Medusa · PostgreSQL · Hetzner", meta: "3 services" },\n    { label: "Owner", value: "Manoj Bhat", href: "/team/manoj" },\n  ]}\n/>`,options:[["rows[]",`{ label, value, meta?, href? }`,<><code>label</code> is the field name, set in mono and upper-cased because it is a key rather than prose. <code>value</code> is the content. <code>meta</code> is the machine face at the end of the row — a duration, a count, a state. <code>href</code> makes the whole row a link.</>],["label",`string`,<>Names the list for a screen reader. Worth setting when more than one list is on the page.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor, for rows that carry an <code>href</code>. Without it a linked row is a document load.</>],],notes:[<><strong>It is a real definition list.</strong> Each row is a <code>dt</code> and a <code>dd</code>, so a screen reader reads it as pairs rather than as a run of text. That is the reason to reach for this over a two-column <a href="#table">Table</a> with one record in it.</>,<><strong>Rows press, they do not tint.</strong> Hover sinks the row and steps the label to brand ink; a linked row presses deeper. The row itself never takes a colour — being pointed at is not a category.</>,<><strong>Where the line is.</strong> Four to six fields is the range. More than that and the eye starts scanning for a column, which is what a <a href="#table">Table</a> is for; fewer than three and it is usually just a sentence.</>,<>Below 560px the two columns stack, so the label sits above its value rather than being squeezed into a third of a phone.</>,],preview:<DataList label="Engagement detail" rows={[{label:"Engagement",value:"Commercely · Medusa commerce replatform",meta:"11 weeks"},{label:"Stack",value:"Medusa · PostgreSQL · Hetzner",meta:"3 services"},{label:"Status",value:<Badge variant="success">Live</Badge>,meta:"since Jun"},{label:"Owner",value:"Manoj Bhat",href:"#data-list",meta:"principal"}]}/>},
 {id:"faq",name:"Faq",group:"Marketing & editorial",summary:"Questions that open in place. One carved plate with seams between them rather than a stack of cards — eight raised objects for what is one list reads as eight decisions.",code:`import { Faq } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Faq\n  label="Implementation questions"\n  single\n  defaultValue={["cost"]}\n  items={[\n    { id: "cost", question: "What does an ERPNext rollout cost?", answer: <p>Eleven engagements, ₹6L to ₹42L.</p> },\n    { id: "time", question: "How long does it take?", answer: <p>Nine to sixteen weeks.</p> },\n  ]}\n/>`,options:[["items[]",`{ id, question, answer }`,<><code>id</code> is the stable key and what <code>value</code> speaks in. <code>answer</code> takes nodes, so a real paragraph, a list or a link all work.</>],["single",`boolean · default false`,<>One at a time — opening a question closes the one before it. Off, any number can be open at once.</>],["value / defaultValue / onValueChange",`string[]`,<>The open ids. Control it with <code>value</code> plus <code>onValueChange</code>, or seed it with <code>defaultValue</code> to open a question on arrival.</>],["label",`string`,<>Names the list for a screen reader. Worth setting when a page carries more than one.</>],],notes:[<><strong>It is a real disclosure.</strong> Each question is a <code>button</code> with <code>aria-expanded</code>, and the answer is the region it controls — so the keyboard and a screen reader get the behaviour without anything being reimplemented.</>,<><strong>The answer is hidden with <code>hidden</code>, not with a stylesheet.</strong> The two disagree: a CSS-hidden panel is still found by in-page search in some browsers, which is how a reader ends up scrolled to text they cannot see. The stylesheet honours the attribute rather than overriding it.</>,<><strong>Opening a question carves a well.</strong> The state is told with depth and nothing else — the answer is recessed into the plate and lies in it, because an answer is data resting in the surface rather than chrome sitting on it. The question row itself stays flush when open: recessing the row <em>and</em> the well under it says the same thing twice, and the pair reads as a tinted band rather than as an opening.</>,<>The question row takes the row press on hover, and steps its ink to full strength when it is the live one. The chevron turns and steps its ink with it; it is a direction mark, not a lamp, so it never glows.</>,<>The seams touching an open question retract. A well fenced by hairlines reads as a cell in a table; on its own it reads as the plate opening.</>,<>Each question is wrapped in an <code>h3</code>. If the surrounding page needs a different level, that is a composition change rather than a prop — raise it upstream rather than nesting the list under a heading that does not fit.</>,<><strong>A disclosure is this component with one item.</strong> It always was — the button, <code>aria-expanded</code>, the controlled region, the row press and the chevron are the same object whether the list has one question or eight.</>,<><strong>There is one version of it, deliberately.</strong> A variant that dropped the plate existed briefly; it was removed because two looks for one list is two things to keep beautiful, and the list was the one that mattered.</>,<>The seams between questions are <em>carved</em>, not drawn. They were a 1px border, which is the one thing a boundary in this system must never be — a line painted on a surface sits on it, and a seam is the surface parting. Two hairlines make it: the shade cut into the plate and the light on the lip below.</>,],preview:<div style={{display:"grid",gap:28}}><Faq label="Implementation questions" single defaultValue={["cost"]} items={[{id:"cost",question:"What does an ERPNext implementation actually cost?",answer:<p style={{margin:0}}>Across eleven engagements, ₹6L to ₹42L. The spread is data migration and the number of integrations, not the licence — there is not one.</p>},{id:"time",question:"How long does it take?",answer:<p style={{margin:0}}>Nine to sixteen weeks from discovery to go-live, running in parallel with your existing system until cutover.</p>},{id:"host",question:"Where does it run?",answer:<p style={{margin:0}}>Your infrastructure or ours — self-hosted Docker on a VPS. The source and the data stay in your hands either way.</p>}]}/></div>},
 {id:"link-cells",name:"LinkCells",group:"Navigation",summary:"The where-to-next grid at the foot of a page. The whole cell is the target, so there is no separate read-more link to miss.",code:`import { LinkCells } from "@mithtech-bengaluru/tonaldepth-react";\n\n<LinkCells\n  label="Keep reading"\n  items={[\n    { kicker: "Guide", title: "Migrating from Tally", href: "/services/migration/tally-to-erpnext" },\n    { kicker: "Pricing", title: "What an implementation costs", detail: "Eleven engagements, itemised.", href: "/pricing" },\n  ]}\n/>`,options:[["items[]",`{ href, title, kicker?, detail? }`,<><code>kicker</code> is the category above the title — small caps, a word or two. <code>detail</code> is one line under it, for a destination whose title does not explain itself. Both are optional.</>],["label",`string`,<>Names the navigation landmark. A page with two of these needs it.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor. Without it every cell is a document load.</>],],notes:[<><strong>The cell is the link, not a card with a link in it.</strong> That is what makes the whole area clickable and keeps one tab stop per destination. Do not put a button inside a cell — a control inside a link is unreachable by keyboard in the order a reader expects.</>,<>The arrow moves sideways and steps its ink on hover. It is a direction mark, not a lamp: it never glows, because a glow would report state and there is no state here.</>,<>The grid reflows on its own from 230px, so the count adapts to the column rather than being set.</>,],preview:<LinkCells label="Keep reading" items={[{kicker:"Guide",title:"Migrating from Tally to ERPNext",detail:"The cutover that runs in parallel.",href:"#link-cells"},{kicker:"Pricing",title:"What an implementation actually costs",detail:"Eleven engagements, itemised.",href:"#link-cells"},{kicker:"Case study",title:"Order-to-cash cut to four days",href:"#link-cells"}]}/>},
 {id:"logo-strip",name:"LogoStrip",group:"Marketing & editorial",summary:"A wall of real client artwork — one flat silhouette at rest, the real mark on a light plate on hover. Real marks are third-party proof; a typeset list of names is a claim. Turn on `scroll` and the wall becomes a carousel, for more marks than fit on a line.",code:`import { LogoStrip } from "@mithtech-bengaluru/tonaldepth-react";\n\n<LogoStrip\n  label="Trusted by"\n  items={[\n    { name: "Rework Industries", logo: <img src="/logos/rework.svg" alt="" /> },\n    { name: "Coastal Freight", logo: <img src="/logos/coastal.svg" alt="" />, href: "/case-studies/coastal" },\n  ]}\n/>`,options:[["scroll",`boolean · default false`,<><strong>Turns the wall into a carousel.</strong> For more marks than fit on a line, where a wall would either wrap into a block or have to be cut down to the ones that fit. Off, it is the wall.</>],["speed",`number · default 32`,<>Seconds for one full pass — higher is slower. Only used when <code>scroll</code> is on. Slow enough to read a mark, or the strip is decoration.</>],["reverse",`boolean · default false`,<>Runs the marks the other way. Two strips in opposite directions is the usual reason to reach for it.</>],["items[]",`{ logo, name, href? }`,<><code>logo</code> is the client's own artwork — an <code>img</code> or an inline <code>svg</code>. <code>name</code> is required and becomes the mark's alternative text. <code>href</code> makes that mark a link.</>],["label",`ReactNode`,<>The line above the wall — “Trusted by”, “Selected clients”. Pass <code>null</code> to drop it.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor, for marks that carry an <code>href</code>. Given the class, the href and the children, return the element — without it a linked mark is a document load.</>],],notes:[<><strong><code>name</code> is not optional, and it is why.</strong> A logo is a picture of a word. The name is always in the DOM and visually hidden, so the wall is a list of organisations to a screen reader rather than a row of unlabelled images. Mark the artwork itself <code>alt=""</code> — the component supplies the text.</>,<><strong>Pass the real marks.</strong> Eleven client logos are proof; a neat list of typeset names is an assertion. Where a choice trades credibility for tidiness, credibility wins.</>,<><strong>Rest is a silhouette, not greyscale.</strong> It was <code>grayscale(1)</code> at 62%, which keeps each mark’s own values — and that is the bug: a logo drawn in near-black ink stayed near-black and disappeared on a dark page, and a white one disappears on a light page. Whether a logo can be seen at all should not depend on the colour its owner picked. <code>brightness(0)</code> flattens every mark to one silhouette in the page’s own ink, so the wall is legible in both themes and reads as one material besides.</>,<><strong>The hovered mark is lit by a small white shadow, and there is no plate under it.</strong> A dark-ink logo returning to its real colours on a dark page returns to being invisible, which is what the near-white chip was for — and a flat fill behind every mark is the one move the system forbids, so on <code>#F5F5F5</code> it read as a rendering fault rather than a state. A <code>drop-shadow</code> follows the glyph&rsquo;s own alpha, so the light sits <em>behind the mark</em> rather than under a rectangle containing it: a dark mark gets a rim to sit against and nothing else appears. Two lights at low strength — a tight core and a wider bloom — because one at a readable strength reads as a halo. It is deliberately subtle, and nearly invisible on a light page, where the restored artwork was legible anyway.</>,<><strong>The item carries no background and no <code>box-shadow</code>, in any state.</strong> Both draw a rectangle around the mark, and a rectangle is a card. If you need the hovered mark to read harder, raise the two <code>drop-shadow</code> alphas — do not give it a housing.</>,<><strong>The whole ladder is one filter list.</strong> Rest and hover carry the same five functions in the same order, because a filter list only interpolates against a list of the same shape — the old <code>filter: none</code> on hover snapped the silhouette off instead of fading it. The unlit lights are white at zero alpha rather than <code>transparent</code>, which is black at zero alpha and would smear the mark on its way to being lit.</>,<>Under reduced motion the scale is dropped and only the colour and the light return.</>,<><strong>The carousel is a mode, not a second component.</strong> Same items, same silhouette-to-colour treatment, presented as a moving track instead of a wrapping block — so a logo wall that outgrows its line does not become a different thing to maintain.</>,<><strong>It pauses when a reader engages with it</strong>, on hover and on keyboard focus. A mark that slides out from under the pointer is a link nobody can click, and one that slides away from a focus ring is worse.</>,<><strong>Under <code>prefers-reduced-motion</code> it stops completely</strong> and becomes a track the reader scrolls themselves. Slowing an infinite animation is not honouring that preference — it is the same animation.</>,<>The marks are rendered twice so the loop has no seam. The second run is <code>inert</code>, which takes it out of the tab order and the accessibility tree together; without that a screen reader reads the whole client list twice.</>,<>The edges are masked rather than cut, so the strip reads as continuing past the frame instead of ending at it.</>,<><strong>The wall is quiet until you look at one of them.</strong> Every mark is flattened and dimmed at rest, and the one under the pointer comes back to its real colours, steps forward and lights. It is a <code>filter</code> throughout, so the artwork is never altered, and it is on the artwork rather than the item so the light follows the glyph rather than a box. An inline SVG, a PNG and a file someone just picked all behave identically.</>,<><strong>Inside <code>scroll</code> the viewport clips.</strong> It bleeds by <code>--td-react-logos-bleed</code> (18px) and pulls the same amount back off its margin, so the scaled mark and its light have room without the strip getting taller. Raise it if you raise the scale or the blur; a hover that is sliced off at the top and bottom is the failure it prevents, and it only appears in the moving variant.</>,],preview:<div style={{display:"grid",gap:28}}><div><h3 style={{margin:"0 0 8px",fontSize:"0.95rem"}}>Try your own marks</h3><p className="sub" style={{margin:"0 0 12px"}}>The fixed examples below are typeset shapes, which is the exact thing this component exists to argue against. Put real artwork through it — by URL, or from your computer. Nothing is uploaded and nothing is saved.</p><LogoBench/></div><LogoStrip label="Trusted by — the wall" items={[{name:"Rework Industries",logo:<svg viewBox="0 0 120 30" width="96" height="24"><rect x="0" y="6" width="18" height="18" rx="4" fill="#E4572E"/><text x="26" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Rework</text></svg>},{name:"Coastal Freight",logo:<svg viewBox="0 0 130 30" width="104" height="24"><circle cx="12" cy="15" r="10" fill="#2E86AB"/><text x="28" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Coastal</text></svg>,href:"#logo-strip"},{name:"Northwind Foods",logo:<svg viewBox="0 0 140 30" width="112" height="24"><polygon points="12,4 22,26 2,26" fill="#3B8C4A"/><text x="28" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Northwind</text></svg>},{name:"Halver Logistics",logo:<svg viewBox="0 0 130 30" width="104" height="24"><rect x="0" y="8" width="20" height="14" rx="7" fill="#8A5CD8"/><text x="28" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Halver</text></svg>},{name:"Vestry Retail",logo:<svg viewBox="0 0 120 30" width="96" height="24"><path d="M2 22 L11 5 L20 22 Z" fill="#B08D2F"/><text x="26" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Vestry</text></svg>},{name:"Quanta Labs",logo:<svg viewBox="0 0 125 30" width="100" height="24"><circle cx="11" cy="15" r="9" fill="none" stroke="#1E5FA8" strokeWidth="4"/><text x="27" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Quanta</text></svg>}]}/><LogoStrip scroll speed={26} label="Trusted by — the carousel" items={[{name:"Rework Industries",logo:<svg viewBox="0 0 120 30" width="96" height="24"><rect x="0" y="6" width="18" height="18" rx="4" fill="#E4572E"/><text x="26" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Rework</text></svg>},{name:"Coastal Freight",logo:<svg viewBox="0 0 130 30" width="104" height="24"><circle cx="12" cy="15" r="10" fill="#2E86AB"/><text x="28" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Coastal</text></svg>,href:"#logo-strip"},{name:"Northwind Foods",logo:<svg viewBox="0 0 140 30" width="112" height="24"><polygon points="12,4 22,26 2,26" fill="#3B8C4A"/><text x="28" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Northwind</text></svg>},{name:"Halver Logistics",logo:<svg viewBox="0 0 130 30" width="104" height="24"><rect x="0" y="8" width="20" height="14" rx="7" fill="#8A5CD8"/><text x="28" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Halver</text></svg>},{name:"Vestry Retail",logo:<svg viewBox="0 0 120 30" width="96" height="24"><path d="M2 22 L11 5 L20 22 Z" fill="#B08D2F"/><text x="26" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Vestry</text></svg>},{name:"Quanta Labs",logo:<svg viewBox="0 0 125 30" width="100" height="24"><circle cx="11" cy="15" r="9" fill="none" stroke="#1E5FA8" strokeWidth="4"/><text x="27" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Quanta</text></svg>}]}/><LogoStrip scroll reverse speed={34} label={null} items={[{name:"Rework Industries",logo:<svg viewBox="0 0 120 30" width="96" height="24"><rect x="0" y="6" width="18" height="18" rx="4" fill="#E4572E"/><text x="26" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Rework</text></svg>},{name:"Coastal Freight",logo:<svg viewBox="0 0 130 30" width="104" height="24"><circle cx="12" cy="15" r="10" fill="#2E86AB"/><text x="28" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Coastal</text></svg>,href:"#logo-strip"},{name:"Northwind Foods",logo:<svg viewBox="0 0 140 30" width="112" height="24"><polygon points="12,4 22,26 2,26" fill="#3B8C4A"/><text x="28" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Northwind</text></svg>},{name:"Halver Logistics",logo:<svg viewBox="0 0 130 30" width="104" height="24"><rect x="0" y="8" width="20" height="14" rx="7" fill="#8A5CD8"/><text x="28" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Halver</text></svg>},{name:"Vestry Retail",logo:<svg viewBox="0 0 120 30" width="96" height="24"><path d="M2 22 L11 5 L20 22 Z" fill="#B08D2F"/><text x="26" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Vestry</text></svg>},{name:"Quanta Labs",logo:<svg viewBox="0 0 125 30" width="100" height="24"><circle cx="11" cy="15" r="9" fill="none" stroke="#1E5FA8" strokeWidth="4"/><text x="27" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Quanta</text></svg>}]}/><p className="hint" style={{margin:0}}>Hover the carousel, or tab into it: it stops while you are engaging with it. With <code>prefers-reduced-motion</code> set it does not move at all and becomes a track you scroll yourself.</p></div>},
 {id:"frame",name:"Frame",group:"Surfaces & data",summary:"A raised plate with a well cut into it — the housing anything measured lives inside. Chrome is raised and data is recessed, so a chart or a table reads as data without a single border. Reach for it whenever something is housed rather than offered.",code:`import { Frame, FrameGrid } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* A chart is housed, so it goes in a well. flushContent because a plot\n    already carries its own margins. */}\n<Frame\n  eyebrow="Order to cash"\n  title="Days to collect"\n  description="Median across nine plants, weekly."\n  actions={<Button size="sm" variant="ghost">Export</Button>}\n  footnote={<>Source: ERPNext <code>Sales Invoice</code> · as of 26 Aug 2026</>}\n  flushContent\n>\n  <MyChart />\n</Frame>\n\n{/* depth="flush" cuts no well — for a frame that only supplies a caption. */}\n<Frame title="Notes" depth="flush">…</Frame>\n\n{/* Frames reflow rather than squash. */}\n<FrameGrid min={280}>…</FrameGrid>`,options:[["depth",`"well" | "flush" | "deep" · default "well"`,<>How deep the well is cut. <code>well</code> is the one to reach for. <code>flush</code> cuts no well at all — for a frame only supplying a caption and a rule. <code>deep</code> is for a single hero object on a page with nothing competing with it.</>],["as",`"section" | "figure" | "article" | "div" · default "section"`,<>The element the frame renders as. <code>figure</code> is for a well holding one self-contained object the surrounding prose refers to — a chart, a specimen; it is what <a href="#chart-container">ChartContainer</a> passes. Everything else wants the default.</>],["titleAs",`"h2" | "h3" | "h4" | "p" · default "h3"`,<>The heading level the title renders at. A document&rsquo;s headings are an outline and a missing level breaks it, so the caller says where the frame sits: <code>h2</code> for a frame taken as a section&rsquo;s own heading, <code>h3</code> inside a section, <code>h4</code> inside a subsection. <code>p</code> is the opt-out, for a caption that belongs in no outline at all — it is a paragraph, so nothing announces it as a heading.</>],["titleScale",`"caption" | "section" · default "caption"`,<><code>caption</code> is 16px and is right for a figure inside prose: a chart caption should not out-shout the paragraph it belongs to. <code>section</code> is the system&rsquo;s own h4 step, for a frame that <em>is</em> a section of the page and whose title is the claim being made — where 16px reads as filler beside the thing it introduces.</>],["flushContent",`boolean · default false`,<>Lets the well's content bleed to its edges. Charts usually want this: a plot already carries its own margins and would otherwise sit in two.</>],["FrameGrid min",`number`,<>The smallest a frame may get before the grid drops a column. Frames reflow rather than squash.</>],],notes:[<><strong>Chrome is raised, data is recessed.</strong> That pairing is the whole component — a chart or a table inside it reads as data without a single border being drawn.</>,<><strong>The head slots work at section scale, not only at figure scale.</strong> The title used to be a hard <code>h3</code> at 16px with no way to change either, so a consumer whose page headed at <code>h2</code> either skipped a level or dropped the title slot and composed the header outside the frame — which makes <code>eyebrow</code>, <code>title</code> and <code>description</code> unusable for every frame that is a section rather than a figure inside prose. Use them either way now.</>,<><strong><code>titleAs</code> and <code>titleScale</code> are deliberately independent, and neither wins.</strong> One decides where the title sits in the document outline and the other decides how big it is drawn. They are separate because both mismatches are real: a section heading that has to stay quiet beside a busy plot, and a figure caption that carries the strongest claim on the page. Set the level from the page&rsquo;s outline and the scale from what the title has to do.</>,<><code>title</code> also names the frame for a screen reader, through <code>aria-labelledby</code> — that wiring holds at every level, including <code>titleAs="p"</code>. A frame with no <code>title</code> and a name worth having takes <code>aria-label</code> or <code>aria-labelledby</code> directly.</>,<>Every slot is optional: <code>eyebrow</code>, <code>title</code>, <code>description</code>, <code>actions</code> and <code>footnote</code>. A Frame with only children is a bare well, which is a legitimate thing to want.</>,<><code>footnote</code> is where the source, the as-of date and the caveat go — under the well, in the quiet face, so the number above it is not carrying its own disclaimer.</>,<><code>actions</code> sits opposite the title: a range picker, an export. Keep it to controls that act on what is in the well.</>,<>Reach for it whenever something is <em>housed</em> rather than offered. A <a href="#card">Card</a> groups; a Frame contains.</>,<><strong>The well's radius is the plate's minus the padding.</strong> That subtraction is what makes it read as a well cut into the plate rather than a sticker stuck on it, and it is why the three values come from <code>--td-frame-pad</code>, <code>--td-frame-radius</code> and <code>--td-well-radius</code> rather than loose radius steps.</>,<>Anything that carries its own plate — a <code>TableContainer</code>, a bento panel — drops it on the way into the well. A raised box inside a trough inverts the whole idea.</>,],preview:<div style={{display:"grid",gap:20}}><Frame eyebrow="Order to cash" title="Days to collect" description="Median across nine plants, weekly." footnote={<>Source: ERPNext <code>Sales Invoice</code> · as of 26 Aug 2026</>}><div style={{display:"flex",alignItems:"flex-end",gap:10,height:120}}>{[38,34,31,29,26,24,21,19].map((v,i)=><div key={i} style={{flex:1,height:`${v*2.4}%`,borderRadius:"4px 4px 0 0",background:`var(--td-series-${i%8+1})`}}/>)}</div></Frame><FrameGrid min={260}><Frame eyebrow="Deep" title="A single hero object" depth="deep"><p className="sub" style={{margin:0}}>A deeper cut, for one thing with nothing competing.</p></Frame><Frame eyebrow="Flush" title="No well" depth="flush"><p className="sub" style={{margin:0}}>Caption and boundary only — nothing is being housed.</p></Frame></FrameGrid></div>},
 {id:"file-tree",name:"FileTree",group:"Navigation",summary:"A repository or docs tree. Every row presses — hover sinks it, the press sinks it deeper, and the file being read rests recessed. The chevron turns to say which way a folder is facing; it is a direction mark, not a lamp, so it never glows.",code:`import { FileTree } from "@mithtech-bengaluru/tonaldepth-react";\n\n<FileTree\n  label="Repository"\n  activeId="checkout"\n  defaultOpen={["root", "storefront"]}\n  nodes={[\n    {\n      id: "root",\n      name: "commercely",\n      children: [\n        { id: "checkout", name: "checkout.tsx", meta: "TSX", href: "/src/checkout.tsx" },\n        { id: "cart", name: "cart.ts", meta: "TS", href: "/src/cart.ts" },\n      ],\n    },\n    { id: "docs", name: "docs", children: [] },\n  ]}\n/>`,options:[["nodes[]",`{ id, name, meta?, href?, children? }`,<><strong><code>children</code> is what makes a node a folder</strong> — present means folder, absent means file. An empty array is a folder with nothing in it, which is a different thing from a file and draws as one. <code>meta</code> is the machine face at the end of the row: a format, a size, a count.</>],["activeId",`string`,<>The file being read. That row rests recessed and takes papaya as ink. Folders are never “active” — a folder's state is open or closed.</>],["open / defaultOpen / onOpenChange",`string[]`,<>The open folder ids. Control them with <code>open</code> plus <code>onOpenChange</code>, or seed them with <code>defaultOpen</code> so a docs sidebar arrives showing the section being read.</>],["onSelect",`(node) => void`,<>Fires when a file row is chosen. A folder row expands instead and never calls it.</>],["href on a node",`string`,<>Renders that file row as an anchor. Without one the row is a button and <code>onSelect</code> is the only way it reports.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor. It is given the class, the href and the row's own <code>data-kind</code> / <code>data-active</code> / <code>aria-current</code> attributes, so the tree keeps ownership of the state and you keep ownership of navigation.</>],["label",`string`,<>Names the navigation landmark. Set it whenever a page carries more than one tree.</>],],notes:[<><strong>It is a nested list of disclosures, not an ARIA tree widget.</strong> Every row is a real button or anchor in the tab order and each folder carries <code>aria-expanded</code> — there is no roving tabstop and no arrow-key navigation. A file browser that needs those is a different component; this is the sidebar shape, and pretending otherwise would ship a <code>role="tree"</code> the keyboard does not honour.</>,<><strong>It reads no filesystem.</strong> You pass <code>nodes</code>, already sorted, already filtered. The tree renders them in the order given.</>,<><strong>A closed folder is hidden with <code>hidden</code>, not with a stylesheet</strong> — so its rows are out of the accessibility tree and out of in-page search, rather than being findable text the reader cannot see.</>,<>Rows press rather than tint. The design system's own tree washed a hovered row in 6% ink and the active row in 12% brand; a row being pointed at is not a category, so both are depth here and papaya arrives as ink.</>,<>The chevron carries no glow. It turns and steps its ink — a glow is how this system reports state, and the state is already in the depth under it.</>,<>When both <code>href</code> and <code>onSelect</code> are given, both fire: the anchor navigates and the callback runs. Prevent the default in your own handler if you are routing yourself, or reach for <code>renderLink</code>.</>,],preview:<FileTree label="Repository" activeId="checkout" defaultOpen={["root","storefront"]} nodes={[{id:"root",name:"commercely",children:[{id:"storefront",name:"storefront",children:[{id:"checkout",name:"checkout.tsx",meta:"TSX"},{id:"cart",name:"cart.ts",meta:"TS"},{id:"theme",name:"theme.css",meta:"CSS"}]},{id:"api",name:"api",children:[{id:"routes",name:"routes.ts",meta:"TS"}]},{id:"pkg",name:"package.json",meta:"JSON"}]},{id:"docs",name:"docs",children:[{id:"runbook",name:"runbook.md",meta:"MD"}]}]}/>},
 {id:"pricing-table",name:"PricingTable",group:"Marketing & editorial",summary:"The plan grid: a price, what it includes, and the way to take it. One card per plan, each carrying its own call to action, so the reader decides and acts in the same place. The plan being argued for is reported by depth and papaya ink — never by a fill.",code:`import { PricingTable, Button } from "@mithtech-bengaluru/tonaldepth-react";\n\n<PricingTable\n  label="Engagement models"\n  plans={[\n    {\n      id: "discovery",\n      name: "Discovery",\n      price: "₹2.4L",\n      period: "/ 2 weeks",\n      features: ["Architecture review", "Engagement plan and estimate"],\n      action: <Button size="lg" style={{ width: "100%" }}>Start discovery</Button>,\n    },\n    {\n      id: "engagement",\n      name: "Engagement",\n      price: "₹8L+",\n      period: "/ month",\n      featured: true,\n      features: ["4-week sprints, weekly demos", "Senior pair, runbook-led"],\n      action: <Button size="lg" style={{ width: "100%" }}>Start engagement</Button>,\n    },\n  ]}\n/>`,options:[["plans[]",`{ id, name, price, period?, description?, features[], action?, featured?, featuredLabel? }`,<><code>price</code> is rendered exactly as given — the component does no currency work, no rounding and no localisation, because a price is copy. <code>period</code> is the mono line beside it: <em>/ month</em>, <em>/ 2 weeks</em>.</>],["featured",`boolean`,<>Marks the plan the page is arguing for. It sits further out of the page than its neighbours and the edge ring it already carries turns papaya. Mark <strong>one</strong>: two featured plans is the same as none.</>],["featuredLabel",`ReactNode · default "Most picked"`,<>What the mark on the featured plan reads. Say why it is picked — “Most picked”, “Best for 20–50 seats” — rather than repeating the plan's name.</>],["action",`ReactNode`,<>The plan's own call to action. You supply the control, so it can be a <code>Button</code>, an anchor, or a form submit. Give it <code>width: 100%</code> if you want it to fill the card.</>],["features[]",`ReactNode[]`,<>What the plan <strong>includes</strong>. Every entry is marked with the same tick a comparison table uses for <em>yes</em>.</>],["min",`number · default 260`,<>Smallest a plan may get before the grid drops a column.</>],["label",`string`,<>Names the group of plans for a screen reader.</>],],notes:[<><strong>This is not <a href="#comparison-table">ComparisonTable</a>, and the two are not interchangeable.</strong> A pricing table is an <em>offer</em> — one card per plan with its own call to action, so the reader chooses and acts in one place. A comparison table is an <em>argument</em> — a matrix of criteria against options, with nothing to act on. A page that needs both uses both: the grid to decide, the matrix to justify. Building this out of a comparison table with a price row leaves you a price in a cell and nothing to press.</>,<><strong>There is no “not included” row.</strong> Every feature listed is an inclusion. A plan that has to say what it leaves out is making a comparison, and that is <code>ComparisonTable</code>'s job — it draws a real cross for <code>false</code>, which a greyed tick never does.</>,<><strong>It does no arithmetic.</strong> No annual/monthly toggle, no seat multiplier, no tax. Pass the numbers you want shown; a calculator is page state and belongs above the component.</>,<>The design system's own card fills its “most picked” mark with papaya and rings the plan in 2px of brand. Neither is reproduced: the mark is a carved chip carrying papaya as ink, and the emphasis is depth.</>,<>The action is pinned to the foot of the card, so a row of plans with different feature counts still lines its buttons up.</>,<>Each plan is an <code>article</code> labelled by its own name, so a screen reader announces the plan before its price rather than reading a loose column of numbers.</>,],preview:<PricingTable label="Engagement models" plans={[{id:"discovery",name:"Discovery",price:"₹2.4L",period:"/ 2 weeks",description:"A scoped fortnight before anyone writes code.",features:["Architecture review","Engagement plan and estimate","No code, no surprises"],action:<Button size="lg" style={{width:"100%"}}>Start discovery</Button>},{id:"engagement",name:"Engagement",price:"₹8L+",period:"/ month",featured:true,description:"The build, run by a senior pair.",features:["4-week sprints, weekly demos","Senior pair, runbook-led","Hetzner, AWS or on-prem","Quarterly tune-ups included"],action:<Button size="lg" style={{width:"100%"}}>Start engagement</Button>},{id:"managed",name:"Managed",price:"₹2.4L+",period:"/ month",description:"After go-live, for as long as you want us.",features:["24×7 on-call rotation","Dependency and architecture care","4-hour response SLA"],action:<Button size="lg" variant="outline" style={{width:"100%"}}>Talk to managed</Button>}]}/>},
 {id:"code-block",name:"CodeBlock",group:"Surfaces & data",summary:"Code, housed. A Frame with the slots a listing needs already wired — the language and the file above, a CopyChip in the corner, the source in the well. It does no syntax highlighting: you pass pre-highlighted markup and it draws the box.",code:`import { CodeBlock } from "@mithtech-bengaluru/tonaldepth-react";\n\nconst SOURCE = \`export default defineEventHandler(async event => {\n  const id = getRouterParam(event, "id");\n  return db.engagements.find({ id });\n});\`;\n\n{/* Plain text — no highlighter involved. */}\n<CodeBlock language="TypeScript" title="server/api/[id].ts" code={SOURCE} />\n\n{/* Pre-highlighted: the markup is yours, the four token classes are ours. */}\n<CodeBlock language="TypeScript" code={SOURCE}>\n  <span className="td-cb-k">const</span> id = <span className="td-cb-n">getRouterParam</span>(event, <span className="td-cb-s">"id"</span>);\n</CodeBlock>`,options:[["code",`string`,<><strong>Required.</strong> The raw source. It is what the copy control puts on the clipboard, and what is rendered when no <code>children</code> are passed. Keep it in sync with the markup — nothing checks that they agree.</>],["children",`ReactNode`,<>Pre-highlighted markup. Replaces the plain text on screen; <code>code</code> is still what gets copied.</>],["language",`ReactNode`,<>The language tag above the well. A tag, not a sentence — “TypeScript”, “bash”, “JSON”.</>],["title",`ReactNode`,<>What the block is: a route, a path, a filename.</>],["footnote",`ReactNode`,<>A line under the well — where the source came from, what it assumes, which version it is from.</>],["copy",`boolean · default true`,<>The copy chip in the corner. Turn it off for a listing nobody would run — an error message, a diff.</>],["copyLabel / copiedLabel",`string · default "Copy" / "Copied"`,<>The chip's visible text before and while the copied state holds.</>],["copyAriaLabel",`string · default "Copy code"`,<>The chip's accessible name. It has its own prop because the value is a whole file, and a screen reader reading the listing aloud as a button name is not a name.</>],["wrap",`boolean · default false`,<>Wrap long lines instead of scrolling them. Off is right for code, where a wrapped line changes what the code appears to say; on is right for a shell transcript or a log.</>],],notes:[<><strong>It does no syntax highlighting, and it never will.</strong> A highlighter is a grammar per language and a theme per grammar — a dependency the size of this library behind a component that draws a box. Bring your own (Shiki, Prism, highlight.js, a server route) and pass the markup as <code>children</code>. Four token classes are styled for you: <code>td-cb-k</code> keyword, <code>td-cb-s</code> string, <code>td-cb-n</code> name, <code>td-cb-c</code> comment. Anything else you class yourself.</>,<><strong>The well is the surface pressed in, not a dark slab.</strong> The design system's own panel hardcodes <code>#1A1815</code> and <code>#F0EDE5</code> in both themes. A well is the plain material carved inward, and a fixed dark ground on a paper page is a tinted band — so the recess carries the separation and the token colours follow the theme.</>,<><strong>No line numbers, no diff gutter, no line highlighting.</strong> Each of those is a second column of markup the caller would have to produce anyway; when you need them, put them in the highlighted markup you are already passing.</>,<>The listing is its own scroller and is focusable, so a line wider than the page can be reached from the keyboard rather than only by dragging.</>,<><code>code</code> is what is copied even when <code>children</code> are given. If the two disagree the reader copies <code>code</code> — which is the right way round, because that is the text that runs.</>,<>The whole thing is a <code>figure</code>, so the listing and its caption are announced as one object rather than a heading followed by loose text.</>,],preview:<div style={{display:"grid",gap:20}}><CodeBlock language="TypeScript" title="server/api/engagements/[id].ts" code={'import { defineEventHandler } from "h3";\n\nexport default defineEventHandler(async event => {\n  const id = getRouterParam(event, "id");\n  return db.engagements.find({ id });\n});'} footnote="Nuxt 4 · h3 route handler"><span className="td-cb-c">{"// discovery route"}</span>{"\n"}<span className="td-cb-k">import</span>{" { "}<span className="td-cb-n">defineEventHandler</span>{" } "}<span className="td-cb-k">from</span> <span className="td-cb-s">{"\"h3\""}</span>{";\n\n"}<span className="td-cb-k">export default</span> <span className="td-cb-n">defineEventHandler</span>{"("}<span className="td-cb-k">async</span>{" event => {\n  "}<span className="td-cb-k">const</span>{" id = "}<span className="td-cb-n">getRouterParam</span>{"(event, "}<span className="td-cb-s">{"\"id\""}</span>{");\n  "}<span className="td-cb-k">return</span>{" db.engagements.find({ id });\n});"}</CodeBlock><CodeBlock language="bash" copy={false} wrap code={"pnpm add @mithtech-bengaluru/tonaldepth-react --registry https://npm.po5.in"}/></div>},
 {id:"breadcrumbs",name:"Breadcrumbs",group:"Navigation",summary:"Where this page sits, and the way back up. Three forms on one prop — chevrons, slashes, and the condensed bar that houses them. The last crumb is the page you are on, so it is not a link.",code:`import { Breadcrumbs } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Breadcrumbs\n  items={[\n    { label: "mith.tech", href: "/" },\n    { label: "Work", href: "/work" },\n    { label: "2026", href: "/work/2026" },\n    { label: "Commercely replatform" },\n  ]}\n/>\n\n{/* The condensed form: chevrons inside a housed bar, for a dense header. */}\n<Breadcrumbs separator="condensed" items={items} />`,options:[["separator",`"chevron" · default`,<>A single right-angle mark between crumbs. The default, and the one for an application header.</>],["separator",`"slash"`,<>A forward slash. Reads as a path, which is what you want when the trail <em>is</em> a path — a docs tree, a file browser, a URL.</>],["separator",`"condensed"`,<>Chevrons inside a housed bar. The trail becomes one raised object that scrolls sideways rather than wrapping, for a header with no room to give it two lines.</>],["items[]",`{ label, href? }`,<>In order, root first. A crumb with no <code>href</code> renders as plain text — useful for a level that exists in the hierarchy but has no page of its own.</>],["label",`string · default "Breadcrumb"`,<>Names the navigation landmark. Change it when a page has more than one trail.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor. Given the class, the href and the children, return the element. The last crumb never reaches it.</>],],notes:[<><strong>The last crumb is never a link, and its <code>href</code> is ignored.</strong> It is the page the reader is already on: a link to where you already are is not a destination, and it would make the crumb's press read as a control that does nothing. It carries <code>aria-current="page"</code> instead, which is what a screen reader announces.</>,<><strong>Three forms, one prop, no cross product.</strong> <code>condensed</code> is a value of <code>separator</code> rather than a second <code>housed</code> boolean, because the design system draws exactly these three — and a separator-times-housing prop pair would let you build a slash-in-a-bar nobody has drawn.</>,<><strong>It does not truncate.</strong> A trail too long for its line wraps, and the condensed form scrolls inside its own bar. Collapsing the middle behind an ellipsis loses the one thing a breadcrumb is for; shorten the labels instead, or pass fewer crumbs.</>,<>Crumbs that lead somewhere press — hover sinks them, the press sinks them deeper. The current crumb does not press at all, because it is not a control.</>,<>The separator is drawn in CSS as punctuation, not as an icon. It sits between two words and means nothing on its own, so it is never a lamp and never carries a glow.</>,<>It renders a real <code>nav &gt; ol</code>, so the order is announced as an ordered list rather than as a row of loose links.</>,],preview:<div style={{display:"grid",gap:20,justifyItems:"start"}}><Breadcrumbs items={[{label:"Dashboard",href:"#breadcrumbs"},{label:"Engagements",href:"#breadcrumbs"},{label:"Commercely",href:"#breadcrumbs"},{label:"Build sprint 4"}]}/><Breadcrumbs separator="slash" items={[{label:"mith.tech",href:"#breadcrumbs"},{label:"Work",href:"#breadcrumbs"},{label:"2026",href:"#breadcrumbs"},{label:"Commercely"}]}/><Breadcrumbs separator="condensed" items={[{label:"Work",href:"#breadcrumbs"},{label:"SaaS",href:"#breadcrumbs"},{label:"Commercely replatform"}]}/></div>},
 {id:"pagination",name:"Pagination",group:"Navigation",summary:"The page trail, cut where it has to be. The page you are on is not a target — it rests recessed with papaya ink rather than being filled with the brand colour, because a button that reloads where you already are is a control that appears to do nothing.",code:`import { Pagination } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* Button mode — you own the state. */}\n<Pagination page={page} pageCount={42} onPageChange={setPage} />\n\n{/* Link mode — real hrefs, which is what a crawler and a middle-click need. */}\n<Pagination\n  page={page}\n  pageCount={42}\n  href={n => \`/blog/page/\${n}\`}\n  renderLink={({ className, href, children, ...rest }) => (\n    <Link className={className} href={href} {...rest}>{children}</Link>\n  )}\n/>`,options:[["page / pageCount",`number`,<>Both 1-based. <code>page</code> is the page being read; the component derives everything else from the pair.</>],["onPageChange",`(page: number) => void`,<>Fires with the page that was chosen. Ignored in link mode — there the anchor navigates.</>],["siblings",`number · default 1`,<>How many pages stay visible either side of the current one before the trail is cut.</>],["boundaries",`number · default 1`,<>How many pages stay visible at each end. Raise it when the last page number is itself information — a 214-page archive says something the ellipsis does not.</>],["href",`(page: number) => string`,<>Give it a builder and every target renders as a real anchor instead of a button. That is the right mode for anything a crawler reads or a reader middle-clicks.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor. Given the class, the href, the children and the accessible name, return the element. Only used alongside <code>href</code>.</>],["label / previousLabel / nextLabel",`string`,<>Names for the landmark and the two edge controls. Translate them with the rest of the page.</>],["pageLabel",`(page: number) => string · default "Page {n}"`,<>The accessible name of a numbered target. The visible text is the bare number, which on its own is not a name.</>],],notes:[<><strong>The current page is not a target.</strong> It renders as plain text with <code>aria-current="page"</code> and rests recessed. A button that reloads where you already are appears to do nothing, and the recess is already how this system says “this one is selected”.</>,<><strong>It holds no state.</strong> You pass <code>page</code> and you move it — from your own state in button mode, or from the route in link mode. Owning the page number here would fight every router that already owns it.</>,<><strong>It does not know how many rows there are.</strong> Pass <code>pageCount</code>; deriving it from a total and a page size is arithmetic the caller already did to fetch the rows.</>,<><strong>A cut is only drawn where it saves more than one number.</strong> Replacing a single hidden page with an ellipsis costs the same width and takes away a target, so the trail shows that page instead.</>,<>The edge controls stay drawn when they are out of reach — disabled rather than removed — so the row does not change width as the reader walks it. They carry <code>aria-disabled</code> and never fire.</>,<>Every target presses; none of them tints. The previous and next marks are direction marks and carry no glow.</>,],preview:<div style={{display:"grid",gap:20,justifyItems:"start"}}><Pagination page={1} pageCount={4}/><Pagination page={8} pageCount={42}/><Pagination page={42} pageCount={42} boundaries={2}/></div>},
 {id:"map",name:"Map",group:"Surfaces & data",summary:"A static locator. No tile provider and no network call — a carved ground, an optional graticule, and pins placed at percentages you give it. Bring your own outline; the component positions the lamps over it.",code:`import { Map } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* \`Map\` shadows the global. Alias it wherever you also use the built-in. */}\nimport { Map as LocatorMap } from "@mithtech-bengaluru/tonaldepth-react";\n\n<LocatorMap\n  label="Where we work"\n  pins={[\n    { id: "blr", label: "Bengaluru", x: 34, y: 72 },\n    { id: "bom", label: "Mumbai", x: 22, y: 58, tone: "accent" },\n    { id: "del", label: "Delhi", x: 33, y: 28, tone: "accent" },\n  ]}\n>\n  <svg viewBox="0 0 100 100" aria-hidden="true">{/* your outline */}</svg>\n</LocatorMap>`,options:[["pins[]",`{ id, label, x, y, tone?, description? }`,<><code>x</code> and <code>y</code> are percentages of the box measured from its top left, <strong>not</strong> latitude and longitude. <code>description</code> is read after the label where the name alone does not say enough.</>],["pins[].tone",`"brand" · default`,<>The papaya lamp. Where every pin means the same thing, leave them all on it — colour is category, and one category is no colour at all.</>],["pins[].tone",`"accent" | "green" | "error" | "neutral"`,<>The other categories: azure, green, red, and an unlit grey for a location that is only context. Reach for these when the pins genuinely differ in kind — offices against sites, live against planned.</>],["label",`string`,<><strong>Required.</strong> The map's accessible name. It has no other one, because the ground is decorative and the pins are just text.</>],["children",`ReactNode`,<>The ground: your own outline, as inline SVG or an image. It is rendered <code>aria-hidden</code> and stretched to the box.</>],["grid",`boolean · default true`,<>The graticule under the ground. Ink at low alpha — it is a ruler, not a signal.</>],["ratio",`number · default 16 / 9`,<>Width over height. The map takes its container's width and derives its height from this.</>],["showLabels",`boolean · default true`,<>Off leaves the lamps on the map and keeps every name readable to a screen reader. For a dense map where the labels would collide.</>],],notes:[<><strong>No tile provider, no network call, and no key.</strong> Reaching a tile server would put a third party in the render path of every page that shows an office address, and it would want a key, a consent banner and an attribution line for a picture that never changes. Pass your own outline instead.</>,<><strong>It does not project coordinates.</strong> <code>x</code> and <code>y</code> are percentages of the box. The outline is yours, so only you know what projection it is in — converting latitude and longitude here would mean guessing at one.</>,<><strong>It is already a well.</strong> A map is a measured object and data is recessed, so it is the surface pressed in rather than a plate. If you need a title, an eyebrow or a source line around it, put it in a <a href="#frame">Frame</a> — the map drops its own recess on the way into the frame's well rather than sitting as a trough inside a trough.</>,<><strong>The export is named <code>Map</code> and shadows the JavaScript built-in.</strong> Alias it on import — <code>import {"{ Map as LocatorMap }"}</code> — in any module that also constructs a <code>new Map()</code>. The registry copy is <code>TonalDepthMap</code> and has no such clash.</>,<>The design system's own map fills its ground with an accent-to-brand gradient. That is not reproduced: filling with the brand colour is the one move the system forbids, and a tinted plane is not a boundary. The ground is the plain surface carved inward.</>,<>Each pin is a lamp in a socket — the socket is the map's own material and is never tinted, the lens is lit from a named light, and colour exists only where the light is.</>,<>Pins are not interactive. There is no hover card, no click target and no clustering; a map that has to be operated is a different component and wants a real mapping library behind it.</>,],preview:<LocatorMap label="Where we work" pins={[{id:"blr",label:"Bengaluru",x:32,y:74},{id:"bom",label:"Mumbai",x:20,y:60,tone:"accent"},{id:"del",label:"Delhi",x:31,y:26,tone:"accent"},{id:"maa",label:"Chennai",x:40,y:84,tone:"neutral"}]}/>},
 {id:"profile-card",name:"ProfileCard",group:"Marketing & editorial",summary:"A person: the mark, the name, the role, and what they own. One card covers the profile card and the team wall — the same parts in a different reading order, so they are two layouts rather than two components.",code:`import { ProfileCard, Button, SocialButton } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* The byline form: the mark beside the name. */}\n<ProfileCard name="Manoj M" role="Principal · Engagements" initials="MM" href="/about/manoj" />\n\n{/* The team wall: the mark above the name, with a bio and controls.\n    Library controls, all at size="sm", so the row sits on one baseline. */}\n<ProfileCard\n  layout="stack"\n  name="Manoj M"\n  role="Principal · Engagements"\n  initials="MM"\n  actions={<>\n    <Button size="sm" variant="email">Email</Button>\n    <SocialButton size="sm" network="linkedin" href="…" label="Manoj on LinkedIn" />\n    <SocialButton size="sm" network="github" href="…" label="Manoj on GitHub" />\n  </>}\n>\n  Owns the engagement model, the runbook template and the Friday status email.\n</ProfileCard>`,options:[["layout",`"row" · default`,<><code>05-cards/profile</code>: the mark beside the name. For a byline, an owner, a contact — anywhere a person is a fact about something else.</>],["layout",`"stack"`,<><code>10-marketing/team</code>: the mark above the name, with room for a bio under it. For a wall of people, where the person <em>is</em> the content.</>],["initials",`string`,<>Two letters, when there is no photograph. Set in the display face inside a carved disc.</>],["avatar",`ReactNode`,<>A photograph or a drawn mark. <strong>It wins over <code>initials</code></strong>, and it is cropped to the disc — pass a square image or expect the sides to go.</>],["role",`ReactNode`,<>The line under the name, in mono small caps. The role, not a sentence.</>],["children",`ReactNode`,<>The bio. Capped at 46 characters a line, because it is prose and prose has a measure.</>],["actions",`ReactNode`,<>Controls at the foot of the card — an <a href="#icon-button">IconButton</a> per channel, a <a href="#button">Button</a>. You supply them, so they are real components rather than a link shape invented here.</>],["href",`string`,<>Makes the name a link — and the whole card a target when there are no <code>actions</code>.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor. Given the class, the href and the children, return the element.</>],],notes:[<><strong>One card for two design pages, on purpose.</strong> <code>05-cards/profile</code> and <code>10-marketing/team</code> are the same parts — mark, name, role, bio, controls — in a different reading order. Two components would have meant correcting the avatar, the role line and the depth ladder twice, in step, forever.</>,<><strong><code>href</code> and <code>actions</code> disagree, and <code>actions</code> wins.</strong> The whole card is a target only when it carries none: a full-card overlay on top of an email button is an overlay that eats the button. With actions present, <code>href</code> links the name alone.</>,<><strong>The team card's gradient avatar is not reproduced.</strong> The design system fills it brand-to-accent with white initials; filling with the brand colour is the one move the system forbids, so the mark is a disc carved from the surface with the initials in the display face.</>,<><strong>Nor is its papaya role line.</strong> A role is not a category, and a wall of eight people would put papaya on all eight — spending the one signal the system reserves for meaning. The role is ink.</>,<>It renders an <code>article</code> labelled by the name, so a screen reader announces who this is before reading the role.</>,<>There is no social-link row of its own. Channel controls are <code>IconButton</code>s in <code>actions</code>, which is how every other channel in the system is drawn — icon as the lamp, label as its accessible name.</>,<><strong>Keep the actions quiet.</strong> A <em>labelled</em> <a href="#icon-button">IconButton</a> is drawn at the large control height, which is right for a page's primary call to action and far too loud inside a person card — it ends up taller than the name it belongs to. Icon-only ones and <code>Button size="sm"</code> are the right weight here, which is what the design system's own profile and team cards use.</>,],preview:<div style={{display:"grid",gap:20}}><ProfileCard name="Manoj M" role="Principal · Engagements" initials="MM" href="#profile-card"/><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(260px,1fr))",gap:20}}><ProfileCard layout="stack" name="Manoj M" role="Principal · Engagements" initials="MM" actions={<><Button size="sm" variant="email">Email</Button><SocialButton size="sm" network="linkedin" href="#profile-card" label="Manoj on LinkedIn"/><SocialButton size="sm" network="github" href="#profile-card" label="Manoj on GitHub"/></>}>Owns the engagement model, the runbook template and the Friday status email.</ProfileCard><ProfileCard layout="stack" name="Rohan Iyer" role="Lead · Platform" initials="RI" actions={<><Button size="sm" variant="email">Email</Button><SocialButton size="sm" network="x" href="#profile-card" label="Rohan on X"/><SocialButton size="sm" network="linkedin" href="#profile-card" label="Rohan on LinkedIn"/></>}>Runs the Hetzner estate, the backup drills and the on-call rotation.</ProfileCard></div><p className="hint" style={{margin:0}}>The actions are library controls, not one-offs: <code>Button</code> at <code>variant="email"</code>, which brings its own mark, and <a href="#social-button"><code>SocialButton</code></a> for the profiles. All three are <code>size="sm"</code>, and a small SocialButton is 34px square — the exact height a small Button is — so the row sits on one baseline instead of missing it by two pixels.</p></div>},
 {id:"mega-cascade",name:"MegaCascade",group:"Mega menus",summary:"The three-level panel: categories, subcategories, items. Each column is a well, both rails are roving-tabindex tablists, and selection deliberately never resets on mouse-out — snapping back while the pointer travels toward the next column is the classic mega-menu bug.",code:`import { MegaCascade } from "@mithtech-bengaluru/tonaldepth-react";\n\n<MegaCascade\n  renderLink={({ className, href, children }) => (\n    <Link className={className} href={href}>{children}</Link>\n  )}\n  groups={[\n    {\n      id: "run",\n      label: "What we run",\n      branches: [\n        {\n          id: "erp",\n          title: "ERP",\n          hint: "Process, hosting, tuning",\n          href: "/services/erp",\n          items: [{ href: "/services/erpnext", title: "ERPNext implementation", detail: "9 pages" }],\n        },\n      ],\n    },\n  ]}\n/>`,options:[["groups[]",`{ id, label, icon?, count?, branches[] }`,<>Column one. <code>count</code> defaults to the sum of the branches’ items; pass <code>null</code> to show no number at all.</>],["groups[].branches[]",`{ id, title, hint?, href?, count?, items[] }`,<>Column two. <code>hint</code> is the line under the title — what this slice is <em>for</em>. <code>href</code> makes the branch itself navigable and adds a “See all” under its items.</>],["branches[].items[]",`{ href, title, detail? }`,<>Column three, the leaves. <code>detail</code> is the dimmer half after the title: the platform, the format, the year.</>],["renderLink",`(props) => ReactNode`,<>Hand your router every anchor in column three. Without it they are plain anchors, which in a SPA is a full document load out of an open menu.</>],["categoriesLabel",`string · default "Categories"`,<>Names the first rail for a screen reader. The second names itself from the chosen category.</>],],notes:[<><strong>Three levels, not two, and that is a sizing decision.</strong> Two puts the whole leaf set in column two, so the panel is sized by the biggest category — fourteen topics in one column with no room to say anything about any of them. The third level lets a category be deep without being tall.</>,<><strong>Column one is click-only; column two follows the pointer.</strong> Hovering across five rows on the way to column two would otherwise change the selection on every row the pointer crosses, and the sheet reads as resizing even though its frame never moves. There is no journey to protect inside column two, so it switches at once — a delay on an already-open sheet reads as lag.</>,<><strong>Selection never resets on mouse-out.</strong> Snapping back to the first category while the pointer travels toward the next column is the classic mega-menu bug, and three columns make that journey longer.</>,<><strong>Every column is a well.</strong> Chrome is raised and the things you are choosing between are recessed, so the sheet reads as a housing with contents rather than three floating lists.</>,<>Both rails are roving-tabindex tablists: up and down move within a rail, right steps into the next, left steps back, Home and End jump to the ends, and Tab leaves for the item links.</>,<>It renders the panel body only. The sheet, its head, its close control and its footer belong to <a href="#site-navigation">SiteNavigation</a>; this goes in a menu item’s <code>content</code>.</>,],preview:<div className="mega-stage"><MegaCascade groups={[{id:"run",label:"What we run",icon:<ICube/>,branches:[{id:"erp",title:"ERP",hint:"Process, hosting, tuning",href:"#mega-cascade",items:[{href:"#mega-cascade",title:"ERPNext implementation",detail:"9 pages"},{href:"#mega-cascade",title:"Data migration",detail:"Tally, SAP, sheets"},{href:"#mega-cascade",title:"Module customisation"},{href:"#mega-cascade",title:"Upgrades and tune-ups"}]},{id:"commerce",title:"Commerce",hint:"Storefront, checkout, catalogue",href:"#mega-cascade",items:[{href:"#mega-cascade",title:"Medusa storefronts",detail:"Headless"},{href:"#mega-cascade",title:"Payments",detail:"Stripe, Razorpay"},{href:"#mega-cascade",title:"Shopify migration"}]},{id:"automation",title:"Automation",hint:"The wiring between systems",items:[{href:"#mega-cascade",title:"n8n workflows"},{href:"#mega-cascade",title:"Event pipelines"},{href:"#mega-cascade",title:"Custom integrations"}]}]},{id:"know",label:"Knowledge",icon:<IList/>,branches:[{id:"guides",title:"Guides",hint:"Long-form, start to finish",href:"#mega-cascade",items:[{href:"#mega-cascade",title:"ERPNext in 90 days"},{href:"#mega-cascade",title:"Choosing a gateway"},{href:"#mega-cascade",title:"Self-hosting on Hetzner"}]},{id:"comparisons",title:"Comparisons",hint:"One against another, with numbers",count:46,items:[{href:"#mega-cascade",title:"ERPNext vs SAP B1"},{href:"#mega-cascade",title:"Medusa vs Shopify"},{href:"#mega-cascade",title:"Plane vs Jira"}]},{id:"studies",title:"Case studies",hint:"What shipped, and what it cost",items:[{href:"#mega-cascade",title:"Commercely replatform",detail:"Retail"},{href:"#mega-cascade",title:"Rework Industries",detail:"Manufacturing"}]}]},{id:"company",label:"Company",icon:<IGear/>,branches:[{id:"about",title:"About",hint:"Who is actually doing the work",items:[{href:"#mega-cascade",title:"How we work"},{href:"#mega-cascade",title:"The team"},{href:"#mega-cascade",title:"Careers",detail:"3 open"}]}]}]}/></div>},
 {id:"mega-tabs",name:"MegaTabs",group:"Mega menus",summary:"The two-column panel: a rail of options on the left, one pane on the right. Reach for it when each option deserves a paragraph — what it includes, what it costs, where to read more.",code:`import { MegaTabs } from "@mithtech-bengaluru/tonaldepth-react";\n\n<MegaTabs\n  label="Services"\n  items={[\n    {\n      id: "erpnext",\n      label: "ERPNext operations",\n      hint: "Process design, hosting and tuning",\n      panel: <ServicePane />,\n    },\n  ]}\n/>`,options:[["items[]",`{ id, label, hint?, icon?, panel }`,<><code>hint</code> is the second line in the rail — what the option is, in a few words. <code>panel</code> is what it is worth saying at length.</>],["value / defaultValue / onValueChange",`string`,<>Control the open option, or leave it uncontrolled. With neither, the first item opens.</>],["label",`string · default "Options"`,<>Names the rail for a screen reader.</>],],notes:[<><strong>The pane changes on click, never on hover.</strong> It followed the pointer at first, on the reasoning that one rail has no journey to protect. That is wrong for a different reason: the pane is the panel’s whole right-hand side, so a pointer crossing the rail on its way anywhere repaints most of the sheet. A rail that swaps a paragraph under the pointer reads as the menu being unstable, not as it being responsive.</>,<><strong>Choose between the two by what an option is worth.</strong> If each one deserves a paragraph, this. If the options are themselves categories with depth under them, the cascade — putting depth in a pane makes the pane the panel’s height.</>,<>The rail is a real tablist: up and down move, Home and End jump to the ends, and the pane is the tabpanel the selected tab controls.</>,<>Both columns are wells, and the option rows take the system’s row ladder — hover sinks, the press sinks deeper, and the chosen row rests recessed.</>,],preview:<div className="mega-stage"><MegaTabs label="Services" items={[{id:"erpnext",label:"ERPNext operations",hint:"Process design, hosting and tuning",icon:<ICube/>,panel:<><h4 style={{margin:0}}>ERPNext operations</h4><p className="sub" style={{margin:0}}>We pick the modules, design the workflows and own the infrastructure — your team runs the day to day.</p><ul className="td-react-mega-items"><li><a href="#mega-tabs">Process design and module customisation</a></li><li><a href="#mega-tabs">Self-hosting on Hetzner, AWS or on-prem</a></li><li><a href="#mega-tabs">Monthly tune-ups and quarterly upgrades</a></li></ul><a className="td-mega-cta" href="#mega-tabs">Engagement model</a></>},{id:"medusa",label:"Medusa commerce",hint:"Headless storefronts, not Shopify",icon:<IGrid/>,panel:<><h4 style={{margin:0}}>Medusa commerce</h4><p className="sub" style={{margin:0}}>Storefront, checkout and the ERP bridge — and the catalogue migrated without taking the shop down.</p><ul className="td-react-mega-items"><li><a href="#mega-tabs">Storefront and checkout on Medusa</a></li><li><a href="#mega-tabs">Stripe, Razorpay or your own gateway</a></li><li><a href="#mega-tabs">Inventory and ERP sync</a></li></ul><a className="td-mega-cta" href="#mega-tabs">Engagement model</a></>},{id:"plane",label:"Plane workflows",hint:"Execution without the SaaS bill",icon:<IList/>,panel:<><h4 style={{margin:0}}>Plane workflows</h4><p className="sub" style={{margin:0}}>Issues, cycles and modules, self-hosted, without Atlassian per-seat pricing.</p><ul className="td-react-mega-items"><li><a href="#mega-tabs">Self-hosted Plane and custom modules</a></li><li><a href="#mega-tabs">GitHub and GitLab sync</a></li></ul><a className="td-mega-cta" href="#mega-tabs">Engagement model</a></>}]}/></div>},
 {id:"mega-grid",name:"MegaGrid",group:"Mega menus",summary:"Cards in a well — the simplest panel, and the one most likely to be got wrong. A grid of cards sitting directly on the sheet has the cards and their housing at the same depth, so nothing reads as contained. MegaActions is the footer rail that goes with it.",code:`import { MegaGrid, MegaActions, FeatureCard, Button } from "@mithtech-bengaluru/tonaldepth-react";\n\n<MegaGrid min={220}>\n  <FeatureCard tone="brand" title="ERPNext" href="/services/erpnext">\n    The full rollout.\n  </FeatureCard>\n</MegaGrid>\n\n{/* In the panel footer slot, not in a column. */}\n<MegaActions>\n  <a className="td-cta" href="/pricing">Pricing</a>\n  <Button variant="primary" size="sm">Talk to us</Button>\n</MegaActions>`,options:[["min",`number · default 220`,<>Smallest a card may get before the grid drops a column.</>],["children",`ReactNode`,<>The cards. <a href="#feature-card">FeatureCard</a> is the shape this was drawn for; anything else that is a card works the same.</>],],notes:[<><strong>Give every card an <code>href</code>.</strong> A card in a menu that cannot be clicked is a picture of a menu — and with one it takes the whole-card link ladder, so it lifts on hover and presses under the pointer like everything else in the system.</>,<><strong>It is a well, not a grid.</strong> That is the whole component: <code>display: grid</code> on the panel body is two lines anyone would write, and it produces cards floating on their own housing at the same depth. Chrome is raised, what you are choosing between is recessed.</>,<><strong><code>MegaActions</code> belongs in the panel footer, not in a column.</strong> In a column it spends a third of the sheet on links that never change and scrolls away with the content; in the footer it sits outside the scroll area and stays reachable however far a column grows.</>,<>Use it when the options need no explaining beyond a line each. When they do, reach for <a href="#mega-tabs">MegaTabs</a>; when they have depth under them, <a href="#mega-cascade">MegaCascade</a>.</>,],preview:<div className="mega-stage"><MegaGrid><FeatureCard tone="brand" icon={ICON_DEMO} title="ERPNext" href="#mega-grid" points={["Discovery to go-live"]}>The full rollout, run by the people who stay.</FeatureCard><FeatureCard tone="accent" icon={ICON_DEMO} title="Medusa" href="#mega-grid" points={["Headless catalogue"]}>Commerce, front and back.</FeatureCard><FeatureCard tone="green" icon={ICON_DEMO} title="n8n" href="#mega-grid" points={["Event-driven flows"]}>The wiring between the systems.</FeatureCard><FeatureCard tone="brand" icon={ICON_DEMO} title="Plane" href="#mega-grid" points={["GitHub sync"]}>Execution without the SaaS bill.</FeatureCard></MegaGrid><MegaActions style={{marginTop:16}}><a className="td-cta" href="#mega-grid">Pricing</a><Button variant="primary" size="sm">Talk to us</Button></MegaActions></div>},
 {id:"mega-columns",name:"MegaColumns",group:"Mega menus",summary:"The widest panel, and the one for a menu that has to teach as well as navigate: a feature that makes the case beside titled columns of destinations, with a rail across the foot. Cascade is for depth, tabs are for options that need a paragraph — this is for breadth.",code:`import { MegaColumns, MegaFeature, Button } from "@mithtech-bengaluru/tonaldepth-react";\n\n<MegaColumns\n  feature={\n    <MegaFeature\n      eyebrow="New to open source ERP?"\n      title="Start with the basics"\n      steps={["Read how it runs", "Book a call", "Agree the scope", "Go live"]}\n      action={<Button variant="primary" size="sm">Open the learn hub</Button>}\n    >\n      A plain-English walkthrough of how a rollout actually works.\n    </MegaFeature>\n  }\n  sections={[\n    {\n      id: "read",\n      label: "Read & learn",\n      links: [{ href: "/learn", title: "Learn hub", detail: "Every guide, by topic" }],\n    },\n  ]}\n  footer={<Button variant="primary" size="sm">Create a free account</Button>}\n/>`,options:[["sections[]",`{ id, label, links[] }`,<>One titled column each. <code>label</code> is a category in small caps, not a sentence — it is marked with a short papaya rule rather than a line across the column, because a full-width rule is a divider and this is a label.</>],["sections[].links[]",`{ href, title, detail?, icon? }`,<><code>detail</code> is what the reader gets for the click, and it is the difference between a menu and a list of nouns. <code>icon</code> takes a filled glyph in its own tile.</>],["feature",`ReactNode`,<>The panel argument, in a fixed first track. A <a href="#mega-columns">MegaFeature</a>, or anything else that earns the width. Omit it and the sections take the whole sheet.</>],["footer",`ReactNode`,<>A rail across the foot, outside the columns’ scroll: app badges, a standing offer, the last link.</>],["renderLink",`(props) => ReactNode`,<>Hand your router every destination in the columns.</>],["MegaFeature",`{ eyebrow?, title, icon?, children, steps?, action? }`,<><code>steps</code> is a numbered sequence on a rail, for the “here is how this works” a menu sometimes has to carry before anything else makes sense. <code>action</code> is <strong>one</strong> control — a panel with two calls to action has none.</>],],notes:[<><strong>Three panels, three jobs.</strong> <a href="#mega-cascade">MegaCascade</a> is for depth, <a href="#mega-tabs">MegaTabs</a> is for options that each need a paragraph, and this is for <em>breadth</em>: destinations a reader scans rather than drills into, with one panel making the case for the section as a whole.</>,<><strong>The feature panel is not a coloured card.</strong> The shape it is drawn from fills the panel with a brand colour and sets white on it. Filling with the brand colour is the one move this system forbids, so it is a well instead — the argument is content, and content is recessed — with papaya arriving as <em>ink</em> on the eyebrow and the step numbers, which is where the emphasis was doing real work in the original.</>,<><strong>The steps are lamps in sockets on a rail</strong>, which is <a href="#timeline">Timeline</a>’s anatomy. A numbered sequence and a phase sequence are the same object read at two scales, so they are drawn the same way rather than invented twice.</>,<>Every column is a well and scrolls itself, so a column with fourteen links does not make the sheet taller. The panel stays one fixed size whatever is in it.</>,<>The footer sits outside the columns’ scroll, so it stays reachable however far a column grows — the same reason <a href="#mega-grid">MegaActions</a> belongs in the panel footer rather than in a column.</>,],preview:<div className="mega-stage mega-stage--wide"><MegaColumns feature={<MegaFeature icon={<ICube/>} eyebrow="New to open source ERP?" title="Start with the basics" steps={["Read how an implementation actually runs","Book a discovery call — about 30 minutes","Agree the scope and the fixed price","Go live, then hand over the runbook"]} action={<Button variant="primary" size="sm">Open the learn hub</Button>}>A plain-English walkthrough of how a self-hosted rollout actually works, and what it costs.</MegaFeature>} sections={[{id:"read",label:"Read & learn",links:[{href:"#mega-columns",title:"Learn hub",detail:"Every guide and article, by topic",icon:<ICube/>},{href:"#mega-columns",title:"News & updates",detail:"What changed this week",icon:<IList/>},{href:"#mega-columns",title:"How it works",detail:"7 steps, signup to go-live",icon:<IGrid/>},{href:"#mega-columns",title:"Glossary",detail:"The terms, explained plainly",icon:<IList/>},{href:"#mega-columns",title:"Release tracker",detail:"Shipped and shipping",icon:<IBell/>}]},{id:"tools",label:"Tools & pricing",links:[{href:"#mega-columns",title:"Calculators",detail:"Cost, sizing and 20 more",icon:<IGrid/>},{href:"#mega-columns",title:"Tools hub",detail:"Calculators, lookups, converters",icon:<ICube/>},{href:"#mega-columns",title:"Migration guide",detail:"Tally, SAP and spreadsheets",icon:<IList/>},{href:"#mega-columns",title:"Pricing methodology",detail:"How we scope and quote",icon:<IGear/>},{href:"#mega-columns",title:"Our fees",detail:"Fixed scope, no hidden hours",icon:<IGrid/>}]}]} footer={<><span className="sub" style={{margin:0,fontFamily:"var(--td-font-mono)",fontSize:"0.62rem",letterSpacing:"0.16em",textTransform:"uppercase"}}>Get the app</span><div style={{display:"flex",gap:10,flexWrap:"wrap"}}><a className="td-cta" href="#mega-columns">App Store</a><a className="td-cta" href="#mega-columns">Google Play</a><Button variant="primary" size="sm">Create a free account</Button></div></>}/></div>},
 {id:"ordered-states",name:"Ordered states",group:"Surfaces & data",summary:"The family page. A workflow's stages, a migration from legacy to live, an ERPNext docstatus going draft → submitted → cancelled, a CI pipeline, an activity stream — all of them are one thing moving through ordered states, and all of them resolve to Timeline on an axis, or to Progress, or to MultiStep. Read the table, pick the axis, stop building a fifth component.",code:`import { Timeline, Progress, MultiStep } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* Which state is it in? Timeline. */}\n<Timeline axis="flow" items={stages} />\n\n{/* How much is done? Progress. */}\n<Progress label="Migration" value={45} />\n\n{/* Both, for a run in flight — compose them, do not reach for a component. */}\n<Progress label="Migration" detail="Step 3 of 6" value={45} />\n<Timeline items={steps} />\n\n{/* Is the reader MOVING through it? MultiStep. */}\n<MultiStep steps={panes} />`,notes:[<><strong>The test is what the reader is asking.</strong> “How much is left” is a quantity and wants <a href="#progress">Progress</a>. “Where did it stop” is a position and wants <a href="#timeline">Timeline</a>. “What do I do next” means the reader is <em>inside</em> the sequence and wants <a href="#multi-step">MultiStep</a>.</>,<><strong>A meter and a step list are a composition, not a component.</strong> A migration in flight shows both — a percentage and the step it is on. That is <code>Progress</code> above <code>Timeline</code>, exactly as a services tile is <code>FeatureCard</code> in a two-column <code>FeatureGrid</code>. Wrapping the pair in a <code>Migration</code> component would buy one import and cost a component nobody can reuse.</>,<><strong>All four Timeline axes share one anatomy.</strong> Same three states, same rail, same dot, same items array — which is why they are a prop and not four lookalike components. If you find yourself wanting a fifth axis, check first that it is not one of these four wearing different words.</>,<><strong>The one thing that is genuinely not in this family is a board.</strong> A deal pipeline with columns of cards is not one thing moving through states; it is many things grouped by the state they are in, and the reader scans it for workload rather than position. Compose that from <a href="#frame">FrameGrid</a>, <a href="#frame">Frame</a> and <a href="#card">Card</a> — one Frame per column, its count in the actions slot, the deals in the well.</>],preview:<div className="family"><div className="family-case"><p className="hint">“Where did it stop?” — <code>Timeline axis="flow"</code></p><Timeline axis="flow" items={[{title:"Lint",state:"done"},{title:"Type-check",state:"done"},{title:"Unit tests",state:"done"},{title:"Build",state:"current"},{title:"Deploy",state:"upcoming"}]}/></div><div className="family-case"><p className="hint">“How much is left?” — <code>Progress</code></p><Progress label="Copy data" detail="Step 3 of 6" value={45}/></div><div className="family-case"><p className="hint">“When is each stage due?” — <code>Timeline marker="ordinal"</code></p><Timeline marker="ordinal" items={[{title:"Vision + interest inventory",time:"Aug 02",state:"done"},{title:"Strengths / needs assessment",time:"Aug 10",state:"done"},{title:"Course of study",time:"Aug 22",state:"current"},{title:"Post-secondary goal",time:"Sep 05",state:"upcoming"}]}/></div><div className="family-case"><p className="hint">“What just happened?” — <code>Timeline axis="feed"</code></p><Timeline axis="feed" items={[{title:<><strong>Sameer</strong> deployed <strong>v2.4.1</strong> to po5.in</>,time:"just now",initials:"SK"},{title:<><strong>Arun</strong> opened PR <strong>#142</strong></>,time:"4m ago",initials:"AJ"},{title:<><strong>Riya</strong> updated the engagement model</>,time:"22m ago",initials:"RP"}]}/></div><div className="family-case"><p className="hint">“What is the plan?” — <code>Timeline axis="period"</code></p><Timeline axis="period" items={[{title:"Discovery",time:"Q1 2026",state:"done"},{title:"Rollout",time:"Q2 2026",state:"current"},{title:"Managed ops",time:"Q3 2026",state:"upcoming"}]}/></div><div className="family-case"><p className="hint">“What do I do next?” — <code>MultiStep</code></p><MultiStep steps={[{label:"Discovery",title:"Scope the problem",description:"Two weeks reading the current state."},{label:"Scope",title:"Build a plan",description:"Fixed scope, weekly demos."},{label:"Build",title:"Ship in sprints",description:"Four-week sprints, each ending in a deploy."}]}/></div></div>},
 {id:"reading-progress",name:"ReadingProgress",group:"Feedback",summary:"The thin bar across the top of the viewport that reports how far into a piece the reader has come. Progress with the label, the percentage and the track taken away, and a scroll position it works out for itself — which is why it is its own module: Progress is server-renderable and used on dashboards by the dozen, and a scroll listener in it would push a client boundary onto all of them.",code:`import { ReadingProgress } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* The whole document. */}\n<ReadingProgress />\n\n{/* Better: the article, so a long footer does not eat 30% of the bar. */}\n<ReadingProgress target="#article" tone="brand" />`,options:[["target",`string`,<>A CSS selector for the element being read. Without one it measures the whole document — which is the difference between “you are 90% down this page” and “you have read 90% of the piece”. A selector that matches nothing warns and falls back rather than reporting a confident 0%.</>],["tone",`"brand" | "accent" | "green" | "error"`,<>Which category the filled length carries. <code>brand</code> unless the page has a reason.</>],["height",`number · default 2`,<>Track thickness in pixels. This is chrome; 2 is the design.</>]],notes:[<><strong>It is the one bar in the system that is not carved.</strong> Every other meter is a well with a fill in it. A carved trough across the top of every page is a permanent horizontal rule the reader has to look past, so the bar exists only where it has something to report and the unfilled part is simply the page.</>,<><strong>It reports; it is not operated.</strong> <code>pointer-events: none</code>, so it cannot eat a click on a skip link or a promo bar in the top two pixels.</>,<><strong>A page with nothing to scroll reads 100%, not 0%.</strong> A piece shorter than the viewport is not one you have read none of.</>,<>Position is <code>fixed</code> at <code>z-index: 80</code>. If your header sits above that, raise the header rather than the bar — the bar belongs under the chrome.</>],preview:<div className="stack"><p className="hint">Fixed to the viewport, so the live one is at the very top of this window rather than in this well. The static specimens below show the shape at three positions.</p><Frame depth="flush"><div className="readingbar"><span className="readingbar-fill readingbar-fill--a"/></div><div className="readingbar"><span className="readingbar-fill readingbar-fill--b"/></div><div className="readingbar"><span className="readingbar-fill readingbar-fill--c"/></div></Frame></div>},
 {id:"counter",name:"Counter",group:"Feedback",summary:"A statistic that counts up to itself when it is scrolled into view. The marketing form of KpiCard — the same label-and-value pair with the plate taken away and the value at display size, because a hero stat row is read at a glance from across the page rather than scanned in a grid.",code:`import { Counter, CounterRow } from "@mithtech-bengaluru/tonaldepth-react";\n\n<CounterRow>\n  <Counter value={23} label="Engagements" />\n  <Counter value={184} suffix="ms" label="p95 latency" />\n  <Counter value={98} suffix="%" label="Retention" />\n  <Counter value={4.5} precision={1} label="Handoff score" />\n</CounterRow>`,options:[["suffix",`ReactNode`,<>The unit, set smaller and in papaya beside the value. It is a separate prop because it is not counted — animating <code>98</code> up to <code>98%</code> would run the percent sign through the digits.</>],["precision",`number · default 0`,<>Decimal places held while counting.</>],["duration",`number · default 1200`,<>How long the count takes, in milliseconds.</>]],notes:[<><strong>The count runs once, on the way in.</strong> A number that re-animates every time it crosses the viewport reads as a loading state rather than as a fact.</>,<><strong>Reduced motion gets the number, not the animation.</strong> So does any browser without <code>IntersectionObserver</code> or <code>matchMedia</code> — both are checked, because an effect that throws leaves a blank stat rather than a still one.</>,<><strong>The digits are tabular.</strong> Without that the label jitters under the number on every frame, which is the one thing that makes a count-up read as broken.</>,<><strong>Not <a href="#kpi">KpiCard</a>.</strong> That one is for inside a product — it carries a delta, a trend and a sparkline, and it is server-renderable. This is a client component and it deliberately has no plate.</>],preview:<CounterRow><Counter value={23} label="Engagements"/><Counter value={184} suffix="ms" label="p95 latency"/><Counter value={98} suffix="%" label="Retention"/><Counter value={4.5} precision={1} label="Handoff score"/></CounterRow>},
 {id:"testimonial",name:"Testimonial",group:"Marketing & editorial",summary:"A quotation with its attribution. Not ProfileCard: a profile card is about the person and you go to it to find out who someone is, while a testimonial is about the claim and the person is the evidence for it — which is why the quote is set at reading size and the name at 12px underneath. Swap them round and it becomes a team card with a long bio.",code:`import { Testimonial, TestimonialGrid } from "@mithtech-bengaluru/tonaldepth-react";\n\n<TestimonialGrid>\n  <Testimonial name="Rajesh Sharma" role="CTO · Rajesh & Co" initials="RS">\n    They owned the deploy, the on-call rotation and the runbook — and they\n    still pair with us every quarter.\n  </Testimonial>\n</TestimonialGrid>`,options:[["initials",`string`,<>Two or three letters for the avatar tile. Initials rather than a photo is the default on purpose: a wall of six headshots at 38px is six unreadable faces, while six initial tiles read as one material.</>],["avatar",`ReactNode`,<>A photograph or a logo, in place of the initials tile. Wins over <code>initials</code> when both are passed.</>],["source",`string`,<>A URL for the blockquote’s <code>cite</code> attribute — where the quote is published.</>]],notes:[<><strong>Do not type a quote mark.</strong> The opening one is drawn by the stylesheet as a watermark, so a typed one reads as a nested quotation — and a drawn one is not read aloud as stray punctuation.</>,<><strong>The card stretches, the attribution aligns.</strong> A row of testimonials whose names sit at four different heights reads as four unrelated things, so the grid stretches and the caption is pushed to the bottom.</>,<><strong>It is a <code>figure</code> with a <code>blockquote</code> and a <code>figcaption</code>.</strong> That is what a quotation with an attribution is, and it is what a screen reader needs to tell the two apart.</>],preview:<TestimonialGrid><Testimonial name="Rajesh Sharma" role="CTO · Rajesh & Co" initials="RS">They owned the deploy, the on-call rotation and the runbook — and they still pair with us every quarter.</Testimonial><Testimonial name="Divya Nair" role="Head of Ops · Commercely" initials="DN">Six weeks from kickoff to a live storefront, and the runbook was ours from day one.</Testimonial></TestimonialGrid>},
 {id:"iso-stack",name:"IsoStack",group:"Surfaces & data",summary:"A deck of cards seen at an angle, which fans apart when the reader points at it. The one component whose subject is the SET rather than any card in it: three engagements stacked says “there is a body of this work” in a way three cards side by side does not.",code:`import { IsoStack } from "@mithtech-bengaluru/tonaldepth-react";\n\n<IsoStack\n  label="Recent engagements"\n  cards={[\n    { eyebrow: "Q1 2026", title: "Commercely", description: "Headless commerce, 6 weeks." },\n    { eyebrow: "Q2 2026", title: "Planely", description: "Self-hosted Plane + GitHub sync." },\n    { eyebrow: "Q3 2026", title: "Calmedly", description: "Cal.com sovereignty build." },\n  ]}\n/>`,options:[["cards",`IsoStackCard[]`,<>Front to back — the first is the one on top, so the DOM order is the order the reader sees. Three is the design; past five it stops reading as a deck.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor when the cards link somewhere.</>]],notes:[<><strong>If the reader needs to compare the cards, this is the wrong component.</strong> Overlapping them hides most of each one. Reach for <a href="#case-card">CaseCardGrid</a> or <a href="#feature-card">FeatureGrid</a> instead.</>,<><strong>The deck opens on keyboard focus, not only on hover.</strong> Without <code>:focus-within</code> a buried card can be tabbed to but never seen.</>,<><strong>Reduced motion still opens the deck</strong> — the fan is the affordance, so it just stops animating on the way.</>],preview:<IsoStack label="Recent engagements" cards={[{eyebrow:"Q1 2026",title:"Commercely",description:"Headless commerce, 6 weeks.",href:"#iso-stack"},{eyebrow:"Q2 2026",title:"Planely",description:"Self-hosted Plane + GitHub sync.",href:"#iso-stack"},{eyebrow:"Q3 2026",title:"Calmedly",description:"Cal.com sovereignty build.",href:"#iso-stack"}]}/>},
 {id:"terminal",name:"Terminal",group:"Surfaces & data",summary:"A transcript of something that ran. Not CodeBlock, and the test is what the reader does with it: a code block is source you copy and run, which is why it carries a copy chip; a terminal is the record of a run that already happened, and copying a transcript — prompts, spinners and timings — is not a thing anyone wants.",code:`import { Terminal } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Terminal\n  title="deploy · commercely · main"\n  live\n  lines={[\n    { kind: "command", text: "docker compose up -d --build" },\n    { kind: "dim", text: "[+] Running 4/4" },\n    { kind: "info", text: "Healthcheck passed: 200 OK in 124ms" },\n    { kind: "ok", text: "✓ Deploy complete in 11.2s" },\n  ]}\n/>`,options:[["lines[].kind",`"command" | "output" | "dim" | "info" | "ok" | "error"`,<>The severities of a <em>run</em>, not the tokens of a language — which is the whole difference from <a href="#code-block">CodeBlock</a>. Only <code>command</code> gets a prompt in front of it.</>],["live",`boolean`,<>A blinking cursor after the last line: the run is still going. It stops blinking under reduced motion but stays lit, which still reads as “waiting”.</>],["prompt",`string · default "$"`,<>The character in front of a <code>command</code> line.</>]],notes:[<><strong>It runs nothing, streams nothing, and does not interpret ANSI escape codes.</strong> Give it lines with a kind; the component sets them.</>,<><strong>The well is the surface pressed in, not a black slab.</strong> A terminal painted <code>#000</code> is a fill doing depth’s job, and it becomes the one dark hole on a paper page.</>,<><strong>The body is focusable</strong> because it scrolls — a scrollable region that cannot be focused cannot be scrolled from the keyboard.</>],preview:<Terminal title="deploy · commercely · main" live lines={[{kind:"command",text:"ssh root@po5.in ‘docker compose up -d --build’"},{kind:"dim",text:"[+] Running 4/4"},{kind:"dim",text:" ⠿ Container commercely-web    Started    0.8s"},{kind:"dim",text:" ⠿ Container commercely-pg     Healthy    0.4s"},{kind:"info",text:"i Healthcheck passed: 200 OK in 124ms"},{kind:"ok",text:"✓ Deploy complete in 11.2s"}]}/>},
 {id:"file-preview",name:"FilePreview",group:"Surfaces & data",summary:"A document offered for opening — the thing an attachment row is. Frame’s anatomy turned on its side: the preview is the measured object and sits in the well, while the name, the facts and the buttons are chrome on the plate beside it. That is why it reads as a document rather than as a card with a picture in it.",code:`import { FilePreview, FilePreviewList, IconButton } from "@mithtech-bengaluru/tonaldepth-react";\n\n<FilePreviewList>\n  <FilePreview\n    name="Discovery-SOW-commercely.pdf"\n    meta="142 KB · 4 pages · 17 Aug"\n    href="/files/sow.pdf"\n    actions={<IconButton icon={<DownloadIcon />} aria-label="Download" />}\n  />\n</FilePreviewList>`,options:[["thumbnail",`ReactNode`,<>A real preview you have rendered yourself. Without one the component draws a page of ruled lines, which says “a document” without pretending to show its first page — and hides itself from assistive tech, because a drawn placeholder is decoration.</>],["meta",`ReactNode`,<>The machine facts, already formatted. The component does not format bytes or dates: whether 142000 is “142 KB” or “138.7 KiB”, and in which locale, is something the caller knows better.</>],["actions",`ReactNode`,<>Open, download, share. <a href="#icon-button">IconButton</a> is the one to reach for.</>]],notes:[<><strong>It renders no PDF.</strong> No viewer, no page navigation, no network.</>,<><strong>The filename truncates rather than wrapping.</strong> It is one token and will not wrap usefully.</>,<><strong>Not <a href="#file-tree">FileTree</a>.</strong> That is a structure of many files; this is one document being offered.</>],preview:<FilePreviewList><FilePreview name="Discovery-SOW-commercely.pdf" meta="142 KB · 4 pages · 17 Aug" href="#file-preview" actions={<><IconButton icon={ICON_DEMO} aria-label="Open"/><IconButton icon={ICON_DEMO} aria-label="Download"/></>}/><FilePreview name="Runbook-2026-Q2.pdf" meta="1.2 MB · 28 pages · 04 Jul" actions={<IconButton icon={ICON_DEMO} aria-label="Download"/>}/></FilePreviewList>},
 {id:"sub-nav",name:"SubNav",group:"Navigation",summary:"A grouped list of links with counts — the second-level navigation inside a section of a product. Not a new design: it is the nav ApplicationShell has always drawn, lifted out so a page that is not a shell can use it. One implementation, two entry points; the shell renders this component.",code:`import { SubNav } from "@mithtech-bengaluru/tonaldepth-react";\n\n<SubNav\n  label="Settings"\n  sections={[\n    { label: "Workspace", items: [\n      { label: "General", href: "/settings", icon: <GearIcon />, count: 12 },\n      { label: "Billing", href: "/settings/billing", current: true },\n    ]},\n    { label: "Security", items: [{ label: "Secrets", href: "/settings/secrets" }] },\n  ]}\n/>`,options:[["plate",`boolean · default true`,<>Draws the raised panel around the links. <a href="#application-shell">ApplicationShell</a> passes <code>false</code>, because there the sidebar is already the plate and a second one nests chrome in chrome.</>],["items[].icon",`ReactNode`,<>Optional — but all or none. A nav with icons on some rows and not others reads as broken.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor. Without it every link is a document load.</>]],notes:[<><strong>Not <a href="#side-tabs">SideTabs</a> or <a href="#tabs">Tabs</a>.</strong> Those switch a panel in place and own a <code>value</code>. Every entry here goes somewhere, and which one is current is the router’s answer rather than the component’s.</>,<><strong>A row presses; it never tints.</strong> Being pointed at is not a category, and selected rests recessed with papaya <em>ink</em> — never an orange fill.</>,<><code>aria-current="page"</code> carries the selection, so it does not depend on colour alone.</>],preview:<SubNav label="Settings" sections={[{label:"Workspace",items:[{label:"General",href:"#sub-nav",icon:ICON_DEMO,count:12},{label:"Billing",href:"#sub-nav",icon:ICON_DEMO,count:8,current:true},{label:"Team",href:"#sub-nav",icon:ICON_DEMO,count:14}]},{label:"Security",items:[{label:"Secrets",href:"#sub-nav",icon:ICON_DEMO},{label:"Sessions",href:"#sub-nav",icon:ICON_DEMO,count:3}]}]}/>},
 {id:"confirm-button",name:"ConfirmButton",group:"Actions",summary:"A destructive action that asks once, in place. The first press arms it and the label changes; the second press inside the timeout commits. Nothing else moves — no dialog, no toast, no second control appearing beside it — so the reader’s pointer is already where it needs to be.",code:`import { ConfirmButton } from "@mithtech-bengaluru/tonaldepth-react";\n\n<ConfirmButton\n  label="Delete build"\n  confirmLabel="Sure?"\n  onConfirm={() => deleteBuild(id)}\n/>`,options:[["confirmLabel",`string · default "Sure?"`,<>What it says once armed. Keep it shorter than the resting label if you can — the button is sized to hold the longer of the two.</>],["timeout",`number · default 3000`,<>How long it stays armed. A button that stays armed forever is one that will be pressed by accident an hour later.</>],["onConfirm",`() => void`,<>Fires on the <strong>second</strong> press only. The first press does nothing but ask.</>]],notes:[<><strong>Use it for the reversible-but-annoying.</strong> Deleting a build, rolling back a deploy, archiving a project. For something genuinely unrecoverable — an account, a customer, a ledger — use <a href="#dialog">Dialog</a>, where the reader has to read a sentence and the consequence can be spelled out. An inline confirm is a speed bump, not informed consent.</>,<><strong>The label change is announced.</strong> <code>aria-live="polite"</code>, because otherwise a screen-reader user presses “Delete build”, hears nothing, and presses it again — which commits.</>,<><strong>It disarms on Escape and on blur.</strong> Both are the shape every other dismissable thing in the system has.</>,<><strong>The first press calls <code>preventDefault</code>,</strong> so a ConfirmButton inside a form does not submit it while asking.</>],preview:<div className="row"><ConfirmButton label="Delete build"/><ConfirmButton label="Roll back deploy" confirmLabel="Confirm"/><ConfirmButton label="Archive project"/></div>},
 {id:"multi-step",name:"MultiStep",group:"Forms",summary:"A form broken into panes, with the step indicator that belongs to it. The indicator is the same three-state sequence Timeline draws — done, current, upcoming — laid out as a segmented bar, and it lives here rather than beside the form because this sequence is operable: the reader moves through it, so the indicator and the controls that move it have to agree about where they are.",code:`import { MultiStep } from "@mithtech-bengaluru/tonaldepth-react";\n\n<MultiStep\n  label="Engagement"\n  steps={[\n    { label: "Discovery", title: "Scope the problem", children: <ScopeFields /> },\n    { label: "Scope", title: "Build a plan", children: <PlanFields /> },\n    { label: "Build", title: "Ship in sprints", children: <SprintFields /> },\n  ]}\n  onComplete={submit}\n/>`,options:[["value / onValueChange",`number / (i: number) => void`,<>Hold the position yourself to gate movement on validity. Left off, the component owns its own position.</>],["onComplete",`() => void`,<>Fires when Next is pressed on the last step — the button reads <code>completeLabel</code> there rather than advancing off the end.</>],["completeLabel",`string · default "Submit"`,<>What the last step’s Next button says.</>]],notes:[<><strong>It owns the position and nothing else.</strong> No validation, no blocking Next on an invalid pane, no collecting values — hold your form state where you already hold it.</>,<><strong>The bar reports; it is not a tablist.</strong> Its segments are not buttons, because moving out of order is what Back and Next are for and a clickable segment invites skipping a required pane.</>,<><strong>Each step is named for a screen reader</strong> even though a 5px bar has no room to show it — a progress bar whose steps have no names is a row of anonymous stripes.</>,<><strong>Not <a href="#timeline">Timeline</a>.</strong> That one is read; this one is moved through. See <a href="#ordered-states">Ordered states</a> for the whole family.</>],preview:<MultiStep label="Engagement" steps={[{label:"Discovery",title:"Scope the problem",description:"We start with a two-week discovery. Read the current state, talk to the team, write a scoped engagement plan."},{label:"Scope",title:"Build a plan",description:"A fixed-scope plan with weekly demos. You see every PR, every deploy, every metric."},{label:"Build",title:"Ship in sprints",description:"Four-week sprints. Each ends with a deploy to your infra and a thirty-minute review."},{label:"Operate",title:"Operate with us",description:"Quarterly tune-ups, on-call rotation, a runbook your team can own from day one."}]}/>},
 {id:"select",name:"Select",group:"Forms",summary:"A native select in the system's housing. The platform picker, the keyboard and the type-ahead arrive already correct; only the carve is ours.",code:`import { Select } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Select\n  options={[{ value: "blr", label: "Bengaluru" }, { value: "mum", label: "Mumbai" }]}\n  placeholder="Choose a city"\n  value={city}\n  onChange={e => setCity(e.target.value)}\n/>`,options:[["options",`SelectOption[]`,<>Value and label per row. Labels are rendered as text because a native <code>option</code> cannot hold markup — pass a string.</>],["placeholder",`string`,<>A disabled empty-value first row. Use it when there is no sensible default; do not use it as a label.</>],["invalid",`boolean`,<>Draws the error state and sets <code>aria-invalid</code>. Reads <code>aria-invalid</code> too, so a form library that sets only that still gets the styling.</>]],notes:[<><strong>Native on purpose.</strong> On a phone the reader gets the OS wheel rather than a listbox rebuilt in a page, and every assistive technology already knows what this is.</>,<><strong>Past about twenty options, reach for <a href="#combobox">Combobox</a>.</strong> Beyond that the reader is scanning rather than reading, and a native select cannot carry a filter.</>],preview:<SelectDemo/>},
 {id:"combobox",name:"Combobox",group:"Forms",summary:"A filtered listbox with type-ahead. The same component is the multi-select — one `multiple` prop — because picking one and picking several is the same gesture with a different arity.",code:`import { Combobox } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* One value */}\n<Combobox options={cities} value={city} onValueChange={setCity} label="City" />\n\n{/* Several — this IS the multi-select */}\n<Combobox multiple options={cities} value={cities} onValueChange={setCities} label="Cities" />`,options:[["multiple",`boolean`,<>Turns it into the multi-select. Chips render above the field in the same object <a href="#tag-input">TagInput</a> uses, so the two read as one family.</>],["options",`ComboboxOption[]`,<><code>value</code>, <code>label</code>, and an optional <code>mark</code> — the right-hand mono note for a dial code, a count or a shortcut.</>],["emptyText",`string`,<>What the list says when the filter matches nothing. Say what would help, not "No results".</>]],notes:[<><strong>Focus never leaves the input.</strong> The highlight moves with <code>aria-activedescendant</code>, so typing and arrowing are one gesture rather than two modes.</>,<><strong>Backspace on an empty field</strong> removes the last chip when <code>multiple</code> — the standard gesture, and the only way to undo without the mouse.</>,<>Escape closes, Enter takes the highlighted row, Home and End jump the list. A pointer press is taken on <code>pointerdown</code> so the list closes before anything underneath it reacts.</>],preview:<div className="stack"><ComboboxDemo/><MultiSelectDemo/></div>},
 {id:"tag-input",name:"TagInput",group:"Forms",summary:"Free-text tags in a carved well, committed on Enter or comma and taken back on Backspace.",code:`import { TagInput } from "@mithtech-bengaluru/tonaldepth-react";\n\n<TagInput value={tags} onValueChange={setTags} label="Tags" placeholder="Add a tag" max={8} />`,options:[["commitKeys",`string[]`,<>Which keys commit what is typed. Enter and comma by default; add <code>Tab</code> where the field is one of many.</>],["max",`number`,<>Refuse past this count — the input disappears rather than failing silently when it is reached.</>],["unique",`boolean`,<>Reject a duplicate rather than adding it twice. On by default, because two identical tags are always a mistake.</>]],notes:[<><strong>The difference from <a href="#combobox">Combobox multiple</a> is the set, not the shape.</strong> That one picks from a list you defined; this one lets the reader invent values. Free text where a closed set was meant gives you four spellings of one tag.</>,<>Blur commits whatever is half-typed, so a reader who tabs away does not lose the word they were in the middle of.</>],preview:<TagInputDemo/>},
 {id:"date-picker",name:"Date & time fields",group:"Forms",summary:"Four fields for one decision: how much of an instant you need. A day, a time of day, a span of days, or a precise moment — all on the same calendar, popover and carved trigger.",code:`import { DatePicker, TimePicker, DateRangePicker, DateTimePicker } from "@mithtech-bengaluru/tonaldepth-react";\n\n<DatePicker value={date} onValueChange={setDate} label="Invoice date" />\n<TimePicker value={time} onValueChange={setTime} label="Slot" />\n<DateRangePicker start={from} end={to} onRangeChange={(a, b) => setRange([a, b])} />\n<DateTimePicker date={date} time={time} onDateTimeChange={(d, t) => setWhen([d, t])} />`,options:[["value / start,end / date,time",`string`,<>ISO strings — <code>YYYY-MM-DD</code> and <code>HH:MM</code>, never a <code>Date</code>. A <code>Date</code> is an instant in a timezone, and a birthday is not 00:00 UTC.</>],["min / max",`string`,<>Bound the calendar. Out-of-range days are disabled rather than hidden, so the reader can see the edge of what is allowed.</>],["presets",`DateRangePreset[]`,<>Quick spans on the range picker — "7D", "QTD". The reader's real question is usually one of these.</>],["minuteStep",`number`,<>Minutes between offered slots. Five by default, which is twelve cells and one grid.</>],["hourCycle",`12 | 24 · default 24`,<>On <a href="#time-picker">TimePicker</a> and <a href="#date-time-picker">DateTimePicker</a>: which clock the reader sees. The value stored is 24-hour <code>HH:MM</code> in both.</>]],notes:[<><strong>You have a day → <a href="#date-picker">DatePicker</a>. A time on a known day → <a href="#time-picker">TimePicker</a>. A span → <a href="#date-range-picker">DateRangePicker</a>. An exact moment → <a href="#date-time-picker">DateTimePicker</a>.</strong> Picking the wrong one shows up as a meeting scheduled for "Tuesday".</>,<><strong>The time selector is a grid, not a list.</strong> It used to be one scrolling column of every slot, so 14:45 meant scrolling past fifty-nine options. Hours and minutes are now two grids — any time on the clock is two presses, and the calendar beside it already worked this way.</>,<>Arrow keys walk days, PageUp and PageDown walk months, Home and End jump to the ends of the month. Escape closes and hands focus back to the trigger.</>],preview:<DateFamilyDemo/>},
 {id:"time-picker",name:"TimePicker",group:"Forms",summary:"A time of day on hour and minute grids — two presses for any time on the clock, with nothing to scroll.",code:`import { TimePicker } from "@mithtech-bengaluru/tonaldepth-react";\n\n<TimePicker value={time} onValueChange={setTime} label="Slot" minuteStep={15} />`,options:[["minuteStep",`number`,<>Minutes between slots. <code>15</code> gives four cells and suits booking; <code>5</code> is the default.</>],["hourCycle",`12 | 24 · default 24`,<><code>12</code> runs the hour column <code>12, 1…11</code>, adds an AM/PM column beside Hour and Min, and writes the field as <code>9:30 AM</code>. <strong>The stored value does not move</strong> — it is <code>HH:MM</code>, 24-hour, in both cycles.</>],["value",`string`,<><code>HH:MM</code>, 24-hour — in both cycles. <code>hourCycle</code> is the one dial that changes how it is shown.</>]],notes:[<><strong>Two grids rather than one list.</strong> The three depth recipes are unchanged from the list it replaces — flat at rest, a shallow well on hover, a deeper well with papaya text when selected. Only the layout moved.</>,<><strong>The cycle is presentation; the value is not.</strong> <code>hourCycle={12}</code> changes the grid and the field text and nothing else. A field that changed its wire format with its display would make every consumer parse <code>9:30 AM</code> back to know what it holds, and two forms on one page could not agree.</>,<>See <a href="#date-picker">Date &amp; time fields</a> for how this sits against the other three.</>],preview:<TimeDemo/>},
 {id:"date-range-picker",name:"DateRangePicker",group:"Forms",summary:"A start and an end on one calendar, filled in turn, with the days between them washed rather than pressed.",code:`import { DateRangePicker } from "@mithtech-bengaluru/tonaldepth-react";\n\n<DateRangePicker start={from} end={to} onRangeChange={(a, b) => setRange([a, b])} presets={QUICK_SPANS} />`,options:[["presets",`DateRangePreset[]`,<>Quick spans. Each returns <code>[start, end]</code>, so "this quarter" is computed rather than typed.</>],["startLabel / endLabel",`string`,<>What the two ends are called here — "Check-in" and "Check-out" beat "From" and "To" on a booking form.</>]],notes:[<><strong>One calendar, not two.</strong> Picking a start moves the reader to the end automatically, and the pair is ordered whichever end they set first — so an end before a start corrects itself instead of producing an invalid range.</>,<>Days inside the range take a wash, not a well: they are included, but the reader did not choose them one at a time.</>,<>See <a href="#date-picker">Date &amp; time fields</a> for the decision table.</>],preview:<DateFamilyDemo/>},
 {id:"date-time-picker",name:"DateTimePicker",group:"Forms",summary:"A precise instant — the calendar and the time grid in one popover, so both are set without closing anything.",code:`import { DateTimePicker } from "@mithtech-bengaluru/tonaldepth-react";\n\n<DateTimePicker date={date} time={time} onDateTimeChange={(d, t) => setWhen([d, t])} label="Publish at" />`,options:[["date / time",`string`,<>Reported separately rather than as one string, because a form usually stores them in two columns.</>],["minuteStep",`number`,<>As <a href="#time-picker">TimePicker</a>.</>],["hourCycle",`12 | 24 · default 24`,<>Passed through to the time half. <code>12</code> adds the AM/PM column and writes the field as <code>14 Sep 2026 · 9:30 AM</code>; <code>time</code> stays 24-hour <code>HH:MM</code>.</>]],notes:[<><strong>Both instruments in one popover.</strong> Two separate fields let a reader set a time against no date, which is how a record ends up scheduled for 00:00 on the epoch.</>,<>Picking a day with no time yet defaults to 09:00 rather than midnight — the start of a working day is a better guess than the start of a calendar one.</>,<>See <a href="#date-picker">Date &amp; time fields</a> for the decision table.</>],preview:<DateFamilyDemo/>},
 {id:"file-upload",name:"FileUpload",group:"Forms",summary:"A dropzone with a real keyboard path, size limits, and a list of what has been picked. `preview` is what makes it an image upload.",code:`import { FileUpload } from "@mithtech-bengaluru/tonaldepth-react";\n\n<FileUpload files={files} onFilesChange={setFiles} multiple maxSize={5 * 1024 * 1024} />\n\n{/* The image upload — same component */}\n<FileUpload accept="image/*" preview files={images} onFilesChange={setImages} />`,options:[["preview",`boolean`,<>Draw a thumbnail for each image. This is the whole difference between a file upload and an image upload, which is why there is no second component.</>],["maxSize",`number`,<>Bytes. Anything larger is refused with a message rather than silently dropped.</>],["multiple",`boolean`,<>Accept more than one. Without it a second pick replaces the first rather than adding to it.</>]],notes:[<><strong>The input covers the plate.</strong> A visually-hidden input would leave the zone unreachable by Tab; this way the whole dropzone is one pointer target and one keyboard stop.</>,<><strong>What has been picked is shown.</strong> A zone that still says "drop a file here" after a file was dropped is the most common bug in this pattern.</>,<>Object URLs for thumbnails are revoked when the item goes, so a long form does not leak a blob per preview.</>],preview:<div className="stack"><UploadDemo/><ImageUploadDemo/></div>},
 {id:"otp-input",name:"OtpInput",group:"Forms",summary:"A one-time code, one cell per digit, with paste spread across the cells and Backspace that steps back.",code:`import { OtpInput } from "@mithtech-bengaluru/tonaldepth-react";\n\n<OtpInput length={6} value={code} onValueChange={setCode} onComplete={submit} />`,options:[["length",`number`,<>How many cells. Six unless the sender says otherwise.</>],["onComplete",`(value: string) => void`,<>Fired when the last cell fills — usually submits, so the reader never presses a button after typing the last digit.</>],["mode",`"numeric" | "text"`,<><code>numeric</code> restricts to digits and asks for the number pad. <code>text</code> allows alphanumeric codes and upper-cases them.</>]],notes:[<><strong>Paste is the whole point.</strong> A code arrives as one string from an SMS; a field that takes only the first character of a paste is the reason readers hate this pattern. Here it spreads across the cells and lands the caret after the last one.</>,<>The first cell carries <code>autocomplete="one-time-code"</code>, so iOS offers the code from the message.</>,<>Arrow keys walk the cells, Home and End jump the ends, and focusing a cell selects it so typing replaces rather than appends.</>],preview:<OtpDemo/>},
 {id:"rating",name:"Rating",group:"Forms",summary:"Stars, read or set. `readOnly` is the display form and honours halves; without it the stars are a radio group with arrow keys.",code:`import { Rating } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* The reader's own score */}\n<Rating value={score} onValueChange={setScore} showValue />\n\n{/* An average somebody else produced */}\n<Rating value={4.5} readOnly showValue count={128} size="lg" inset />`,options:[["readOnly",`boolean`,<>The display form: halves render, nothing is focusable, and the whole thing becomes one labelled image rather than five controls.</>],["count",`number`,<>The sample size. A 5.0 from one review and a 4.6 from nine hundred are different claims.</>],["inset",`boolean`,<>Seat the whole thing in a carved pill — for a rating sitting on a card rather than in running text.</>]],notes:[<><strong>One component, not two.</strong> A page usually shows both forms within a few hundred pixels of each other; two components would let the star shapes drift apart.</>,<>Interactive ratings are a radio group, so arrows set the value and the group takes one tab stop rather than five.</>],preview:<RatingDemo/>},
 {id:"color-picker",name:"ColorPicker",group:"Forms",summary:"A colour from a palette somebody curated, with the platform picker behind `allowCustom` for the cases a hex has to be typed.",code:`import { ColorPicker } from "@mithtech-bengaluru/tonaldepth-react";\n\n<ColorPicker value={colour} onValueChange={setColour} allowCustom />`,options:[["swatches",`ColorSwatch[]`,<>The palette. Defaults to the design system's own eight — pass your own for a brand set.</>],["allowCustom",`boolean`,<>Adds the platform colour input under the grid. Leave it off where the palette is the point.</>]],notes:[<><strong>A grid, not a spectrum.</strong> A design system that hands the reader an eyedropper has stopped being a design system; the palette is the constraint.</>,<>The grid is a listbox: one cell is tabbable and the arrows move between them, so it costs one tab stop rather than eight.</>,<>Colours are painted through a CSS custom property set on the node, never through a <code>style</code> prop — that pattern is what took fifty-five pages to a 500 while the types stayed green.</>],preview:<ColorDemo/>},
 {id:"number-field",name:"NumberField",group:"Forms",summary:"A number with its two nudge buttons. A `prefix` or `suffix` makes it the currency or the percent field — there is no third component.",code:`import { NumberField } from "@mithtech-bengaluru/tonaldepth-react";\n\n<NumberField value={qty} onValueChange={setQty} min={0} max={99} label="Quantity" />\n\n{/* The currency field */}\n<NumberField value={amount} onValueChange={setAmount} prefix="₹" step={5000} label="Amount" />\n\n{/* The percent field */}\n<NumberField value={gst} onValueChange={setGst} suffix="%" min={0} max={100} label="GST" />`,options:[["prefix / suffix",`ReactNode`,<>Go into <a href="#input">Input</a>'s existing leading and trailing slots. This is the whole of what a "CurrencyField" would have been.</>],["step",`number`,<>What the buttons and the arrow keys move by. PageUp and PageDown move ten of them.</>],["precision",`number`,<>Decimals to show when the field is not being typed in, so a column of amounts lines up.</>]],notes:[<><strong>The input is the spinbutton.</strong> Assistive technology reads the value and its bounds from the field itself rather than from the two buttons either side of it.</>,<><strong>Half-typed values survive.</strong> "-" and "1." are not numbers yet; the field keeps what was typed instead of round-tripping it through <code>Number</code> on every keystroke and eating the minus sign.</>,<>For a value the reader picks roughly rather than states exactly, use <a href="#range">Range</a>. For a code that happens to be digits, use <a href="#input">Input</a> — an invoice number must not be nudgeable.</>],preview:<NumberDemo/>},
 {id:"phone-field",name:"PhoneField",group:"Forms",summary:"A phone number with a searchable country selector over all 239 dialling codes, reported as E.164.",code:`import { PhoneField, emptyPhone } from "@mithtech-bengaluru/tonaldepth-react";\n\nconst [phone, setPhone] = useState(() => emptyPhone("IN"));\n\n<PhoneField value={phone} onValueChange={setPhone} />\n{/* phone.e164 → "+919008770738" */}`,options:[["value",`PhoneValue`,<><code>e164</code> for submission, <code>national</code> as typed, plus <code>iso</code> and <code>dial</code> so the country can be stored rather than re-derived from the number.</>],["countries",`PhoneCountry[]`,<>Restrict the list — a form that only ships to three places has no business offering 239.</>]],notes:[<><strong>A listbox, not a <code>select</code>.</strong> A native select cannot carry a search box, and with 239 rows that matters; its type-ahead also matches from the start of the option text, which a leading flag emoji breaks.</>,<><strong>The dial code is searchable too.</strong> Somebody who knows "+971" should not have to remember which country that is.</>,<>Flags are derived from the ISO pair rather than stored, so there is no sprite sheet to keep in sync. Windows ships no flag font and renders the pair as letters, which is why every row shows the code beside it.</>],preview:<PhoneDemo/>},
 {id:"address-field",name:"AddressField",group:"Forms",summary:"A postal address as one value, in the order each line narrows the next — country, then state, then city.",code:`import { AddressField, emptyAddress } from "@mithtech-bengaluru/tonaldepth-react";\n\n<AddressField value={address} onValueChange={setAddress} stateLabel="State" postcodeLabel="PIN code" />`,options:[["countries / states",`ComboboxOption[]`,<>Given, those lines become <a href="#combobox">Comboboxes</a>. Absent, they are plain text fields — which is right when the form is global and no list would be complete.</>],["stateLabel / postcodeLabel",`string`,<>What the two are called here — "Province" and "ZIP", "State" and "PIN code". Getting these wrong is the fastest way to look foreign to a reader.</>]],notes:[<><strong>The order is the design.</strong> Country first, because it decides what the next two lines are even called; changing it clears the state, since a state from the previous country is worse than an empty one.</>,<>Pure composition — every part is an existing component in its own housing, so there is no new CSS here beyond the grid they sit in.</>,<>Every line carries the right <code>autocomplete</code> token, so a browser fills the whole address in one gesture.</>],preview:<AddressDemo/>},
 {id:"checkbox-group",name:"CheckboxGroup",group:"Forms",summary:"Several checkboxes read as one question, in a fieldset with a legend — the same shape RadioGroup uses.",code:`import { CheckboxGroup, Checkbox } from "@mithtech-bengaluru/tonaldepth-react";\n\n<CheckboxGroup legend="Notify me about">\n  <Checkbox label="Deploys" />\n  <Checkbox label="Failed jobs" />\n</CheckboxGroup>`,options:[["legend",`ReactNode`,<>The group's name. Without it a row of boxes is a row of unrelated questions to anyone who cannot see that they are lined up.</>],["disabled",`boolean`,<>Disables every box in the group, because <code>fieldset</code> already does.</>]],notes:[<><strong>No shared <code>name</code>.</strong> Unlike <a href="#radio">RadioGroup</a>, checkboxes in a group do not share one — each is its own field, which is exactly what "any number, including none" means.</>,<>Reach for <a href="#combobox">Combobox multiple</a> once the list runs past a dozen. Fifteen checkboxes is a wall; a filtered multi-select is a field.</>],preview:<CheckboxGroupDemo/>},
 {id:"range-dual",name:"RangeDual",group:"Forms",summary:"Range's two-thumb form — a span rather than a point, on two native inputs so each thumb keeps its own keyboard.",code:`import { RangeDual } from "@mithtech-bengaluru/tonaldepth-react";\n\n<RangeDual value={budget} onValueChange={setBudget} min={0} max={1000000} step={10000} format={n => \`₹\${(n / 100000).toFixed(1)}L\`} />`,options:[["value",`[number, number]`,<>Low and high. The pair is sorted on every change, so dragging one thumb past the other swaps them instead of inverting the fill.</>],["format",`(value: number) => ReactNode`,<>The reader's units. A budget slider that says "450000" makes them count digits.</>]],notes:[<><strong>Two real range inputs.</strong> Each thumb gets the native keyboard and its own accessible name — "Budget minimum" and "Budget maximum" — rather than one rebuilt widget with neither.</>,<>The fill between the thumbs is positioned through properties set on the node, not a <code>style</code> prop.</>,<>For one end only, use <a href="#range">Range</a>. For exact figures the reader already knows, use <a href="#number-field">NumberField</a>.</>],preview:<RangeDualDemo/>},
 {id:"spotlight",name:"Spotlight",group:"Overlays",summary:"The command palette: a search field over the whole product, on a scrim. Not SearchBar — a search bar is a field on the page that filters what is already in front of the reader and stays put, while this takes the screen, takes the keyboard, and its results go somewhere. A reader reaches for one to narrow and the other to leave.",code:`import { Spotlight } from "@mithtech-bengaluru/tonaldepth-react";\nimport Fuse from "fuse.js";\n\nconst fuse = new Fuse(everything, { keys: ["label", "detail"], threshold: 0.35 });\nconst results = query ? fuse.search(query).map(r => r.item) : everything;\n\n<Spotlight\n  open={open}\n  onOpenChange={setOpen}\n  query={query}\n  onQueryChange={setQuery}\n  actions={results}\n  onSelect={action => router.push(action.href)}\n/>`,options:[["actions",`SpotlightAction[]`,<>The rows to show, <strong>already filtered and ordered</strong>. Rows sharing a <code>group</code> are headed together, in the order they arrive.</>],["query / onQueryChange",`string / (q: string) => void`,<>The field is controlled by you, because the matching is.</>],["empty",`ReactNode`,<>Shown in place of the list when <code>actions</code> is empty.</>]],notes:[<><strong>It does no matching.</strong> Ranking a command palette is a judgement — recency, fuzzy scoring, weighting a title over a path — and a library that picks one for you is a library you fight. These docs use Fuse.js; so should you.</>,<><strong>You own ⌘K.</strong> The component owns the overlay, the roving selection, and returning focus to whatever opened it.</>,<><strong>The cursor resets whenever the results change.</strong> Leaving it where it was means Enter fires whatever happened to slide into that row.</>,<><strong>The scrim dismisses only when the scrim itself was hit,</strong> so a drag that starts inside the panel and ends outside does not close it.</>],preview:<SpotlightDemo/>},
 {id:"page-nav",name:"PageNav",group:"Navigation",summary:"The secondary header: the bar under the main one that moves between sections of the page you are already on. It sticks with the site header rather than measuring it, and on a narrow screen the tabs scroll inside the bar instead of wrapping it onto a second line.",code:`import { PageNav } from "@mithtech-bengaluru/tonaldepth-react";\n\n<PageNav\n  eyebrow="Engagement"\n  title="Commercely replatform"\n  label="Engagement sections"\n  items={[\n    { label: "Overview", href: "/e/1", current: true },\n    { label: "Milestones", href: "/e/1/milestones", count: 12 },\n    { label: "Invoices", href: "/e/1/invoices", count: 3 },\n  ]}\n  actions={<Button variant="primary" size="sm">Share</Button>}\n/>`,options:[["items[]",`{ label, href, current?, count?, disabled? }`,<>Every item is a URL. <code>current</code> is the router’s answer, not the component’s — nothing here owns which section you are in. <code>count</code> is a resolved number, never an estimate.</>],["title / eyebrow",`ReactNode`,<>What page this bar belongs to. Both are hidden below 720px: on a phone the reader already knows what page they are on, and the tabs are the part that has to stay reachable.</>],["sticky",`boolean · default true`,<>Stack under the main header rather than scrolling away. It reads <code>--nav-offset</code>, which <a href="#site-navigation">SiteNavigation</a> publishes, so neither bar has to know the other’s height.</>],["actions",`ReactNode`,<>Controls at the end — a primary action, a filter, a search.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor. It is given the class, the href and the <code>aria-current</code> state.</>],],notes:[<><strong>It stacks with the main header rather than measuring it.</strong> <code>SiteNavigation</code> publishes <code>--nav-offset</code> and this reads it, so a retracting header does not drag the secondary bar out of place and neither component has to be told the other exists.</>,<><strong>The tabs are a segmented control, not five buttons.</strong> The group lifts off the bar as one raised piece and the current tab is a well pressed into it — which is what makes a row of links read as one control with a position in it.</>,<><strong>On a narrow screen the tabs scroll; they never wrap.</strong> A secondary header that grows to two lines pushes the page down every time the section changes and the reader loses their place. The bar keeps its height, the tabs move inside it, and the ends are masked so the row reads as cut rather than ended.</>,<>Not <a href="#sub-nav">SubNav</a>, which is the vertical grouped directory a product’s sidebar draws, and not <a href="#tabs">Tabs</a>, which switches a panel in place and owns a <code>value</code>. Every item here goes somewhere.</>,],preview:<div style={{display:"grid",gap:18}}><PageNav sticky={false} eyebrow="Engagement" title="Commercely replatform" label="Engagement sections" items={[{label:"Overview",href:"#page-nav",current:true},{label:"Milestones",href:"#page-nav",count:12},{label:"Invoices",href:"#page-nav",count:3},{label:"Runbook",href:"#page-nav"},{label:"Archive",href:"#page-nav",disabled:true}]} actions={<Button variant="primary" size="sm">Share</Button>}/><PageNav sticky={false} label="Sections only" items={[{label:"All",href:"#page-nav",current:true},{label:"Open",href:"#page-nav",count:8},{label:"Blocked",href:"#page-nav",count:2},{label:"Shipped",href:"#page-nav",count:41}]}/><p className="hint" style={{margin:0}}>Narrow the window: the identity drops out first and the tabs scroll inside the bar rather than wrapping it onto a second line.</p></div>},
 {id:"chat-launcher",name:"ChatLauncher",group:"Overlays",summary:"The floating chat launcher and its panel — support, sales, or an AI assistant. It is deliberately not a Dialog: no scrim, no focus trap, the page stays readable and scrollable while the conversation waits. AiHalo is the revolving shine that marks a control as AI, and it wraps anything.",code:`import { ChatLauncher, AiHalo, Button } from "@mithtech-bengaluru/tonaldepth-react";\n\n<ChatLauncher\n  presence="online"\n  title="Chat with us"\n  description="Replies in about 2 minutes"\n  footer={<Input placeholder="Type a message" />}\n>\n  <Transcript />\n</ChatLauncher>\n\n{/* An AI channel: the launcher takes the shine. */}\n<ChatLauncher ai label="Ask AI" title="Ask the docs" />\n\n{/* Or put the shine on any control of your own. */}\n<AiHalo><Button variant="primary">Ask AI</Button></AiHalo>`,options:[["presence",`"online" | "away" | "offline"`,<>The lamp, and the words a screen reader gets. <strong>Say the truth</strong> — an always-green lamp is worse than no lamp, because a reader who waits on it and gets nothing will not come back.</>],["ai",`boolean · default false`,<>Marks the channel as an assistant rather than a person, and gives the launcher the revolving halo.</>],["label",`ReactNode · default "Chat with us"`,<>The launcher’s visible text. Pass <code>null</code> for a round, wordless launcher.</>],["title / description",`ReactNode`,<>The panel’s heading, and one line under it — who answers, and how fast.</>],["children / footer",`ReactNode`,<>The conversation, and what is pinned under it. The transcript sits in a well; the composer goes in <code>footer</code> so it stays put while the transcript scrolls.</>],["avatar",`ReactNode`,<>A face on the launcher, in a carved socket beside the label. A launcher with a face is answered more often than one with a glyph — but only if it is the person who actually replies.</>],["unread",`number`,<>A resolved count, never a bare dot. A dot says <em>something happened</em>, which is the sales pattern that trains readers to ignore launchers; a number says how much is waiting. <code>0</code> and <code>undefined</code> draw nothing.</>],["teaser / teaserDismissLabel",`ReactNode · string`,<>An opening line beside the launcher, with its own dismiss. Say something the reader can answer — a question beats “Hi there!”. Dismissing the line does not open the panel.</>],["pinned",`boolean · default true`,<>Off renders the launcher in normal flow instead of <code>position: fixed</code>, which is how the variants below sit side by side. Use it to place a launcher inside a page section; leave it on for the real one.</>],["side",`"end" | "start" · default "end"`,<>Which side it sits on, in reading order.</>],["open / defaultOpen / onOpenChange",`boolean`,<>Control it, or let it hold its own state.</>],["AiHalo active",`boolean · default true`,<>Off stops the travel dead and leaves the resting ring lit, so nothing reflows and the control keeps its mark.</>],["AiHalo speed",`number · default 3.2`,<><strong>Seconds for one revolution</strong> — lower is faster. Slower reads as considered, faster as busy. The default is 3.2, a quarter quicker than the 4 it started at, because the light only runs while somebody is engaging with the control and a lap that outlasts the hover never completes. <code>&lt;AiHalo speed={2}&gt;</code> for urgent, <code>speed={7}</code> for calm.</>],["--td-ai-speed",`CSS length · default 3.2s`,<>The same knob as a custom property, for a halo you cannot pass a prop to. Set it on any ancestor — <code>{`style={{ "--td-ai-speed": "2s" }}`}</code> on a section retimes every halo inside it. The prop writes this property, so the two are one control rather than two.</>],["ChatLauncher aiSpeed",`number`,<>Retimes the launcher’s own halo, which it builds internally. Only read when <code>ai</code> is on.</>],["AiHalo radius",`string · default "12px"`,<><strong>Must match the control it wraps.</strong> CSS cannot read the radius off the child, so it is stated: <code>12px</code> for a Button, <code>999px</code> for a pill, <code>50%</code> for a disc. Get it wrong and the bright arc of the sweep pokes past the corners, which reads as a smear rather than a light travelling an edge.</>],],notes:[<><strong>It is not a <a href="#dialog">Dialog</a>, and that is the whole design.</strong> A dialog scrims the page, traps focus and demands an answer before anything else happens. Live chat is the opposite: the reader keeps reading and the conversation waits. So there is no scrim, no focus trap and no <code>aria-modal</code> — Escape closes it and focus returns to the launcher, which is all the containment a side panel should have.</>,<><strong>The presence lamp is a lamp, not a coloured disc.</strong> A lens in a socket carved from the launcher, lit green when someone is there and grey glass when nobody is — and the state is in text as well as in the light, because a status carried by colour alone is a status half the readers cannot read.</>,<><strong>The halo is light, not a fill.</strong> The control underneath keeps its own carved surface and its own ladder; the shine sits behind it. Its colour is the two the system already owns, azure into papaya, so it says <em>this one is different</em> without introducing a palette.</>,<><strong>The light travels the edge; nothing rotates.</strong> It used to be a blurred conic gradient behind the control with <code>transform: rotate()</code> on it, which does not read as a light going round a button — the whole shape turns and its bright part crosses the middle. Now <code>padding</code> plus <code>mask-composite: exclude</code> carves a band exactly <code>--td-ai-ring</code> thick out of the pseudo-element, so what is painted is a ring hugging the border radius, and rotating the gradient <em>inside</em> that ring moves a short arc around it.</>,<><strong>It runs when the control is engaged with</strong> — hover, keyboard focus, press — rather than forever. A perpetual animation in the corner of a page is a thing readers learn to filter out, and the moment the mark actually has to say something is the moment somebody reaches for the control. Pressed, it runs at double the pace: the control is working, and the light says so.</>,<><strong>The resting ring is not conditional.</strong> A dim, still hairline in the same two colours is always there, because a mark that only exists on hover marks nothing to a reader who never hovers. Under <code>prefers-reduced-motion</code> that is all there is — the travel stops and the light stays lit and still. A shine that merely slows is the same shine.</>,<><strong><code>radius</code> must match the control.</strong> CSS cannot read the radius off the child, so the ring would sit off the corners of anything it guesses wrong about. The halo animates a registered custom property (<code>@property --td-ai-angle</code>), which is what makes the angle sweep instead of step.</>,<>The design system’s own floating button is a solid papaya pill with white text. Filling with the brand colour is the one move the system forbids, so this is the carved surface every other control uses with papaya as ink.</>,<>It renders <code>position: fixed</code>. In the preview below it is pinned to the corner of the window, not of the card.</>,],preview:<div style={{display:"grid",gap:28}}><div className="row" style={{gap:16,flexWrap:"wrap"}}><AiHalo radius="10px"><Button variant="primary" size="sm">Ask AI · 3.2s</Button></AiHalo><AiHalo radius="10px" speed={1.6}><Button variant="secondary" size="sm">Twice as fast · 1.6s</Button></AiHalo><AiHalo radius="10px" speed={7}><Button variant="secondary" size="sm">Calm · 7s</Button></AiHalo><AiHalo radius="10px" active={false}><Button variant="secondary" size="sm">Travel off</Button></AiHalo></div><p className="hint" style={{margin:0}}><strong>Hover one, then hold the mouse down on it.</strong> The light only travels while the control is engaged with, and doubles its pace on press. The halo wraps any control, so an “Ask AI” button gets it without being a ChatLauncher — pass <code>radius</code> to match whatever it is wrapping.</p><div style={{display:"grid",gap:24}}><div><p className="sub" style={{margin:"0 0 10px",fontFamily:"var(--td-font-mono)",fontSize:"0.62rem",letterSpacing:"0.14em",textTransform:"uppercase"}}>1 · Labelled — the default</p><ChatLauncher pinned={false} presence="online"/></div><div><p className="sub" style={{margin:"0 0 10px",fontFamily:"var(--td-font-mono)",fontSize:"0.62rem",letterSpacing:"0.14em",textTransform:"uppercase"}}>2 · Wordless — for a page that already has a sticky call to action</p><ChatLauncher pinned={false} label={null} presence="online"/></div><div><p className="sub" style={{margin:"0 0 10px",fontFamily:"var(--td-font-mono)",fontSize:"0.62rem",letterSpacing:"0.14em",textTransform:"uppercase"}}>3 · With a face — answered more often than a glyph</p><ChatLauncher pinned={false} avatar={<span>MM</span>} label="Chat with Manoj" presence="online"/></div><div><p className="sub" style={{margin:"0 0 10px",fontFamily:"var(--td-font-mono)",fontSize:"0.62rem",letterSpacing:"0.14em",textTransform:"uppercase"}}>4 · Unread — a resolved count, never a bare dot</p><ChatLauncher pinned={false} avatar={<span>MM</span>} label="Chat with us" unread={3} presence="online"/></div><div><p className="sub" style={{margin:"0 0 10px",fontFamily:"var(--td-font-mono)",fontSize:"0.62rem",letterSpacing:"0.14em",textTransform:"uppercase"}}>5 · Away, and offline — the lamp says which, and so does the text</p><div className="row" style={{gap:20}}><ChatLauncher pinned={false} label="Chat with us" presence="away"/><ChatLauncher pinned={false} label="Leave a message" presence="offline"/></div></div><div><p className="sub" style={{margin:"0 0 10px",fontFamily:"var(--td-font-mono)",fontSize:"0.62rem",letterSpacing:"0.14em",textTransform:"uppercase"}}>6 · AI — the revolving halo</p><ChatLauncher pinned={false} ai label="Ask AI" title="Ask the docs" presence="online"/></div><div><p className="sub" style={{margin:"0 0 10px",fontFamily:"var(--td-font-mono)",fontSize:"0.62rem",letterSpacing:"0.14em",textTransform:"uppercase"}}>7 · With an opening line — dismissible, and dismissing it is not opening the panel</p><ChatLauncher pinned={false} avatar={<span>MM</span>} label="Chat with us" presence="online" teaser="Sizing an ERPNext rollout? Tell me how many people use it today and I will give you a range."/></div></div><p className="hint" style={{margin:0}}>Every launcher above is <code>pinned={false}</code> so they can sit apart and be compared. The real one is <code>position: fixed</code> — it is in the corner of this window now; open it there.</p><ChatLauncher presence="online" title="Chat with us" description="Replies in about 2 minutes" unread={2} avatar={<span>MM</span>} footer={<SearchBar size="sm" block placeholder="Type a message"/>}><p style={{margin:0}}>Hello — ask us anything about an implementation, a migration or a price. A person answers during business hours in IST.</p></ChatLauncher></div>},
];
const docs:Doc[]=authored.map(entry=>({...entry,...GUIDANCE[entry.id]}));
/* `whenNotToUse` points at a sibling by id, because an id is checkable and a
   display name is not. The reader still needs the name. */
const NAME_OF=new Map<string,string>(docs.map(doc=>[doc.id,doc.name]));
/* The logo bench.

   A logo wall is the one component whose whole point is REAL artwork ([[L13]]),
   and the docs previewed it with three typeset shapes — which is the exact
   thing the component exists to argue against. This lets a reader put their own
   marks through it: pick files, or paste a URL.

   NOTHING IS SAVED. The logos live in this component's state and nowhere else —
   no localStorage, no fixture file, nothing written into the library. A picked
   file becomes an object URL, and the URL is revoked when the logo is removed
   or the page is left, so the blob does not leak for the life of the tab. Say
   so in the UI, because a reader who does not know that will not paste their
   client's mark in. */
function LogoBench(){
  type Mark={id:string;name:string;src:string;blob:boolean;failed?:boolean};
  const[logos,setLogos]=useState<Mark[]>([]);
  const[url,setUrl]=useState("");
  const[scroll,setScroll]=useState(false);
  const[dragging,setDragging]=useState(false);
  const fileInput=useRef<HTMLInputElement>(null);
  /* Ids come from a counter rather than from the list length.
     `${file.name}-${logos.length}` collided the moment anything was removed —
     drop the first of three and the next file added takes the id the third
     already has, so React reconciles two different marks as one and the wrong
     image is shown under the wrong name. */
  const nextId=useRef(0);
  /* A live mirror of the list, so the unmount cleanup below can read the final
     one without depending on it. */
  const live=useRef<Mark[]>([]);
  live.current=logos;
  /* Revoke ON UNMOUNT ONLY. This effect used to carry `[logos]`, which meant
     React ran its cleanup on every change — so adding a second file revoked
     the first file's object URL and blanked a mark the reader had just added.
     A blob URL is held by the document until it is revoked, so the cleanup
     itself is necessary; it just has to happen once, at the end. */
  useEffect(()=>()=>{live.current.forEach(l=>{if(l.blob)URL.revokeObjectURL(l.src)})},[]);

  const addFiles=(files:FileList|File[]|null)=>{
    if(!files)return;
    const picked=Array.from(files).filter(f=>f.type.startsWith("image/"));
    if(!picked.length)return;
    setLogos(current=>[...current,...picked.map(file=>({
      id:`m${nextId.current++}`,
      name:file.name.replace(/\.[a-z0-9]+$/i,""),
      src:URL.createObjectURL(file),
      blob:true,
    }))]);
    if(fileInput.current)fileInput.current.value="";
  };
  const addUrl=()=>{
    const value=url.trim();
    if(!value)return;
    let name=value;
    try{name=decodeURIComponent(new URL(value,location.href).pathname.split("/").pop()||value).replace(/\.[a-z0-9]+$/i,"")}catch{/* not a URL we can parse — the raw string is a fine name */}
    setLogos(current=>[...current,{id:`m${nextId.current++}`,name:name||"Logo",src:value,blob:false}]);
    setUrl("");
  };
  const remove=(id:string)=>setLogos(current=>{
    const gone=current.find(l=>l.id===id);
    if(gone?.blob)URL.revokeObjectURL(gone.src);
    return current.filter(l=>l.id!==id);
  });
  const rename=(id:string,name:string)=>setLogos(current=>current.map(l=>l.id===id?{...l,name}:l));
  const clear=()=>setLogos(current=>{current.forEach(l=>{if(l.blob)URL.revokeObjectURL(l.src)});return[]});
  /* A URL that does not resolve otherwise leaves an empty gap in the wall with
     nothing to say why — the reader assumes the component is broken rather
     than the address. */
  const fail=(id:string)=>setLogos(current=>current.map(l=>l.id===id?{...l,failed:true}:l));

  const ok=logos.filter(l=>!l.failed);
  const items=ok.map(l=>({name:l.name,logo:<img src={l.src} alt="" onError={()=>fail(l.id)}/>}));

  return <div className="playground">
    <div className="playground-controls">
      <label className="pg-field"><span>Logo URL</span>
        <Input value={url} placeholder="https://example.com/logo.svg" onChange={e=>setUrl(e.target.value)}
          onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();addUrl()}}}/></label>
      <Button size="sm" variant="primary" onClick={addUrl} disabled={!url.trim()}>+ Add URL</Button>
      <Button size="sm" variant="outline" onClick={()=>fileInput.current?.click()}>+ Add files</Button>
      <input ref={fileInput} type="file" accept="image/*" multiple hidden onChange={e=>addFiles(e.target.files)}/>
      <Checkbox label="scroll" checked={scroll} onChange={e=>setScroll(e.target.checked)}/>
      {logos.length>0&&<Button size="sm" variant="ghost" onClick={clear}>Clear all ({logos.length})</Button>}
    </div>
    {logos.length>0&&<div className="pg-marks">
      {logos.map(l=><div className={`pg-mark${l.failed?" is-failed":""}`} key={l.id}>
        <span className="pg-mark-art">{l.failed?<span className="pg-mark-x" aria-hidden="true">!</span>:<img src={l.src} alt="" onError={()=>fail(l.id)}/>}</span>
        <input className="pg-mark-name" value={l.name} aria-label={`Name for ${l.name}`}
          onChange={e=>rename(l.id,e.target.value)}/>
        {l.failed&&<span className="pg-mark-note">could not load</span>}
        <IconButton tone="neutral" icon={<CloseIcon weight={LAMP_WEIGHT}/>} aria-label={`Remove ${l.name||"logo"}`} onClick={()=>remove(l.id)}/>
      </div>)}
    </div>}
    <div className={`preview pg-drop${dragging?" is-dragging":""}`}
      onDragOver={e=>{e.preventDefault();setDragging(true)}}
      onDragLeave={()=>setDragging(false)}
      onDrop={e=>{e.preventDefault();setDragging(false);addFiles(e.dataTransfer.files)}}>
      <span>Live React component</span>
      {ok.length
        ?<Specimen><LogoStrip scroll={scroll} speed={26} label={null} items={items}/></Specimen>
        :<p className="hint" style={{margin:0}}>Add a logo by URL, from your computer, or by dropping files here. They are held in this page only — nothing is uploaded, nothing is saved, and a picked file is released the moment you remove it or leave.</p>}
    </div>
    <p className="hint"><strong>Nothing here is saved.</strong> The marks live in this page’s memory and nowhere else — no storage, no fixture, nothing written into the library — so a client’s artwork can be tried here without it ending up in the repository. Hover one: the wall is a flat silhouette until you look at a mark, and the one you are looking at comes back to its real colours on a light plate.</p>
  </div>;
}

/* A specimen is operated, not followed.

   Previews carry real hrefs — a FileTree row, a LinkCells card, a breadcrumb —
   because a link with no href is not the component being documented. But
   pressing one to see how it behaves navigated away from the docs, which makes
   the interaction untestable: the thing you were judging is gone.

   The default is cancelled on capture, so the anchor does not navigate while
   every handler the component has still runs and every state — hover, press,
   focus — still reads. `auxclick` covers the middle button, which is a
   separate event and would otherwise open a tab. */
function Specimen({children}:{children:ReactNode}){
  const hold=(event:ReactMouseEvent)=>{
    if((event.target as HTMLElement).closest?.("a[href]")) event.preventDefault();
  };
  return <div className="specimen" onClickCapture={hold} onAuxClickCapture={hold}>{children}</div>;
}
function Copy({text}:{text:string}){const[copied,setCopied]=useState(false);async function run(){await navigator.clipboard.writeText(text);setCopied(true);setTimeout(()=>setCopied(false),1400)}return <Button size="sm" variant="outline" onClick={run}>{copied?"Copied":"Copy"}</Button>}
function Code({children,label="tsx"}:{children:string;label?:string}){return <div className="code"><div><span>{label}</span><Copy text={children}/></div><pre><code>{children}</code></pre></div>}
type CodeLanguage="react"|"html"|"css";
const standaloneBase=`/* TonalDepth base tokens. Install once with @tonaldepth/tokens; TonalDepth components stop redeclaring them. */
:root {
  --td-bg: #eceae6;
  --td-surface: #eceae6;
  --td-surface-2: #e3e0da;
  --td-ink: #1f1c17;
  --td-ink-2: #6e685e;
  --td-ink-3: #9a9388;
  --td-brand: #ff5e29;
  --td-brand-text: #ff5e29;
  --td-accent: #00aaff;
  --td-accent-text: #0675b0;
  --td-green: #59d38c;
  --td-green-text: #0c814a;
  --td-error: #d92a00;
  --td-error-text: #d92a00;
  --td-edge: rgba(82, 70, 54, 0.16);
  --td-shadow-dark: rgba(82, 70, 54, 0.30);
  --td-shadow-light: #ffffff;
  --td-font-ui: "Hanken Grotesk", system-ui, sans-serif;
  --td-font-display: "Anton", "Arial Narrow", sans-serif;
  --td-font-mono: "JetBrains Mono", ui-monospace, monospace;
  --td-ease: cubic-bezier(0.2, 0.75, 0.2, 1);
  --td-btn-h: 42px;
  --td-btn-h-lg: 52px;
}
body { background: var(--td-bg); color: var(--td-ink); font-family: var(--td-font-ui); }`;
const snippets:Record<string,{html:string;css:string}>={
 button:{html:`<button type="button" class="td-coloured td-react-button--md">\n  <span class="td-coloured-label">Save changes</span>\n</button>`,css:`.td-coloured {\n  appearance: none;\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  min-height: var(--td-btn-h);\n  padding: 0 16px;\n  border: 0;\n  border-radius: 13px;\n  background: var(--td-brand);\n  color: #1f1c17;\n  font-family: var(--td-font-ui);\n  font-size: 13px;\n  font-weight: 600;\n  cursor: pointer;\n  box-shadow:\n    3px 3px 8px color-mix(in srgb, var(--td-shadow-dark) 48%, transparent),\n    -3px -3px 8px color-mix(in srgb, var(--td-shadow-light) 50%, transparent),\n    inset 0 1px 0 rgba(255, 255, 255, 0.22);\n  transition: background 160ms var(--td-ease), box-shadow 160ms var(--td-ease);\n}\n\n.td-coloured:hover {\n  background: color-mix(in srgb, var(--td-brand) 92%, white);\n  box-shadow:\n    4px 4px 10px color-mix(in srgb, var(--td-shadow-dark) 52%, transparent),\n    -3px -3px 8px color-mix(in srgb, var(--td-shadow-light) 55%, transparent),\n    inset 0 1px 0 rgba(255, 255, 255, 0.28);\n}\n\n.td-coloured:active {\n  background: color-mix(in srgb, var(--td-brand) 88%, black);\n  box-shadow: inset 2px 2px 6px rgba(0, 0, 0, 0.5);\n}\n\n.td-coloured:focus-visible {\n  outline: 2px solid var(--td-accent);\n  outline-offset: 3px;\n}\n\n.td-coloured:disabled {\n  cursor: not-allowed;\n  box-shadow: none;\n  opacity: 0.58;\n}\n\n.td-coloured-label { transition: transform 220ms var(--td-ease); }\n.td-coloured:active .td-coloured-label { transform: translate(1px, 1px); }`},
 badge:{html:`<span class="td-badge">Neutral</span>\n<span class="td-badge td-badge--brand">Brand</span>\n<span class="td-badge td-badge--green">Ready</span>\n<span class="td-badge td-badge--accent">Review</span>`,css:`.td-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  margin: 4px;\n  padding: 3px 7px;\n  border-radius: 999px;\n  background: color-mix(in srgb, var(--td-surface) 94%, black);\n  color: var(--td-ink-2);\n  font-family: var(--td-font-mono);\n  font-size: 10px;\n  font-weight: 700;\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n  box-shadow:\n    inset 1px 1px 2px color-mix(in srgb, var(--td-shadow-dark) 24%, transparent),\n    inset -1px -1px 2px color-mix(in srgb, var(--td-shadow-light) 30%, transparent);\n}\n\n.td-badge--brand { color: var(--td-brand-text); }\n.td-badge--green { color: var(--td-green-text); }\n.td-badge--accent { color: var(--td-accent-text); }`},
 card:{html:`<article class="td-panel">\n  <header class="td-panel-head"><h3 class="td-panel-title">Project status</h3><span>Ready</span></header>\n  <div class="td-react-card-content">Content stays owned by the consuming app.</div>\n</article>`,css:`.td-panel { max-width: 480px; padding: 24px; border: 1px solid var(--td-edge); border-radius: 12px; background: var(--td-surface); box-shadow: 5px 6px 14px rgba(82,70,54,.21), -4px -5px 12px rgba(255,255,255,.9), inset 0 1px 0 #fff; }\n.td-panel-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-bottom: 20px; }\n.td-panel-title { margin: 0; font-family: var(--td-font-display); font-size: 22px; font-weight: 400; letter-spacing: .01em; }\n.td-panel-head > span { color: var(--td-green-text); font: 700 10px var(--td-font-mono); text-transform: uppercase; letter-spacing: .1em; }\n.td-react-card-content { min-width: 0; color: var(--td-ink-2); line-height: 1.6; }`},
 input:{html:`<span class="td-input-wrap">\n  <input class="td-input" type="email" placeholder="name@company.com">\n</span>`,css:`.td-input-wrap { display: flex; align-items: center; min-height: 42px; padding: 0 13px; border: 1px solid var(--td-edge); border-radius: 12px; background: var(--td-surface); box-shadow: inset 2px 2px 5px rgba(82,70,54,.18), inset -2px -2px 5px rgba(255,255,255,.75); max-width: 420px; }\n.td-input { width: 100%; border: 0; outline: 0; background: transparent; color: var(--td-ink); font: 14px var(--td-font-ui); }\n.td-input::placeholder { color: var(--td-ink-3); }\n.td-input-wrap:focus-within { border-color: var(--td-accent); box-shadow: 0 0 0 2px color-mix(in srgb, var(--td-accent) 25%, transparent); }\n.td-input-wrap[data-state="error"] { border-color: var(--td-brand); }\n.td-input-wrap[data-disabled="true"] { opacity: .6; }`},
 textarea:{html:`<span class="td-textarea-wrap">\n  <textarea class="td-textarea" rows="4" placeholder="Describe the work"></textarea>\n</span>`,css:`.td-textarea-wrap { display: flex; padding: 11px 13px; border: 1px solid var(--td-edge); border-radius: 12px; background: var(--td-surface); box-shadow: inset 2px 2px 5px rgba(82,70,54,.18), inset -2px -2px 5px rgba(255,255,255,.75); max-width: 480px; }\n.td-textarea { width: 100%; min-height: 96px; border: 0; outline: 0; background: transparent; color: var(--td-ink); font: 14px var(--td-font-ui); line-height: 1.5; resize: vertical; }\n.td-textarea::placeholder { color: var(--td-ink-3); }\n.td-textarea-wrap:focus-within { border-color: var(--td-accent); box-shadow: 0 0 0 2px color-mix(in srgb, var(--td-accent) 25%, transparent); }\n.td-textarea-wrap[data-state="error"] { border-color: var(--td-brand); }`},
 "form-field":{html:`<div class="td-field">\n  <label class="td-label" for="work-email">Work email <span class="td-label-required" aria-hidden="true">*</span></label>\n  <span class="td-input-wrap"><input id="work-email" class="td-input" type="email" placeholder="name@company.com" aria-describedby="work-email-message"></span>\n  <p id="work-email-message" class="td-helper">Used only for notifications</p>\n</div>`,css:`.td-field { display: flex; flex-direction: column; gap: 6px; max-width: 420px; }\n.td-label { color: var(--td-ink); font-size: 13px; font-weight: 700; }\n.td-label-required { color: var(--td-brand); font-weight: 700; }\n.td-label-optional { margin-left: 6px; color: var(--td-ink-2); font-size: 11px; font-weight: 500; }\n.td-input-wrap { display: flex; align-items: center; min-height: 42px; padding: 0 13px; border: 1px solid var(--td-edge); border-radius: 12px; background: var(--td-surface); box-shadow: inset 2px 2px 5px rgba(82,70,54,.18), inset -2px -2px 5px rgba(255,255,255,.75); }\n.td-input { width: 100%; border: 0; outline: 0; background: transparent; color: var(--td-ink); font: 14px var(--td-font-ui); }\n.td-input::placeholder { color: var(--td-ink-3); }\n.td-input-wrap:focus-within { border-color: var(--td-accent); box-shadow: 0 0 0 2px color-mix(in srgb, var(--td-accent) 25%, transparent); }\n.td-helper { margin: 0; color: var(--td-ink-2); font-size: 12px; }\n.td-helper--error { color: var(--td-error-text); }\n.td-field[data-invalid="true"] .td-input-wrap { border-color: var(--td-brand); }`},
 checkbox:{html:`<label class="td-check">\n  <input type="checkbox" checked>\n  <span class="td-check-box" aria-hidden="true"><svg viewBox="0 0 16 16"><path d="m3 8 3 3 7-7" fill="none" stroke="currentColor" stroke-width="2"/></svg></span>\n  <span>Email notifications</span>\n</label>`,css:`.td-check { display: inline-flex; align-items: center; gap: 10px; cursor: pointer; user-select: none; font: 13px var(--td-font-ui); color: var(--td-ink); }\n.td-check input { position: absolute; opacity: 0; pointer-events: none; }\n.td-check-box { display: inline-flex; align-items: center; justify-content: center; width: 18px; height: 18px; border: 1px solid var(--td-edge); border-radius: 6px; background: var(--td-surface); color: transparent; box-shadow: inset 1px 1px 3px rgba(82,70,54,.20), inset -1px -1px 2px rgba(255,255,255,.75); transition: background 160ms, color 160ms, border-color 160ms; }\n.td-check-box svg { width: 12px; height: 12px; }\n.td-check input:checked + .td-check-box { background: var(--td-brand); border-color: var(--td-brand); color: #fff; box-shadow: 2px 2px 4px rgba(82,70,54,.22), inset 0 1px 0 rgba(255,255,255,.28); }\n.td-check input:focus-visible + .td-check-box { outline: 2px solid var(--td-accent); outline-offset: 2px; }\n.td-check[data-disabled="true"] { opacity: .55; cursor: not-allowed; }`},
 radio:{html:`<fieldset class="td-fieldset">\n  <legend class="td-fieldset-legend">Delivery</legend>\n  <div class="td-check-row">\n    <label class="td-radio">\n      <input type="radio" name="delivery" value="standard" checked>\n      <span class="td-radio-dot" aria-hidden="true"></span>\n      <span>Standard</span>\n    </label>\n    <label class="td-radio">\n      <input type="radio" name="delivery" value="express">\n      <span class="td-radio-dot" aria-hidden="true"></span>\n      <span>Express</span>\n    </label>\n  </div>\n</fieldset>`,css:`.td-fieldset { border: 0; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }\n.td-fieldset-legend { font: 700 11px var(--td-font-mono); text-transform: uppercase; letter-spacing: .08em; color: var(--td-ink-2); }\n.td-check-row { display: flex; flex-direction: column; gap: 10px; }\n.td-radio { display: inline-flex; align-items: center; gap: 10px; cursor: pointer; user-select: none; font: 13px var(--td-font-ui); color: var(--td-ink); }\n.td-radio input { position: absolute; opacity: 0; pointer-events: none; }\n.td-radio-dot { position: relative; display: inline-flex; width: 18px; height: 18px; border: 1px solid var(--td-edge); border-radius: 999px; background: var(--td-surface); box-shadow: inset 1px 1px 3px rgba(82,70,54,.20), inset -1px -1px 2px rgba(255,255,255,.75); }\n.td-radio-dot::after { content: ""; position: absolute; inset: 4px; border-radius: 999px; background: transparent; transition: background 160ms; }\n.td-radio input:checked + .td-radio-dot { border-color: var(--td-brand); }\n.td-radio input:checked + .td-radio-dot::after { background: var(--td-brand); }\n.td-radio input:focus-visible + .td-radio-dot { outline: 2px solid var(--td-accent); outline-offset: 2px; }\n.td-radio[data-disabled="true"] { opacity: .55; cursor: not-allowed; }`},
 switch:{html:`<label class="td-switch">\n  <input type="checkbox" role="switch" checked>\n  <span class="td-switch-track" aria-hidden="true"><span class="td-switch-thumb"></span></span>\n  <span>Automatic updates</span>\n</label>`,css:`.td-switch { display: inline-flex; align-items: center; gap: 10px; cursor: pointer; user-select: none; font: 13px var(--td-font-ui); color: var(--td-ink); }\n.td-switch input { position: absolute; opacity: 0; pointer-events: none; }\n.td-switch-track { position: relative; display: inline-flex; align-items: center; width: 36px; height: 20px; padding: 2px; border-radius: 999px; background: color-mix(in srgb, var(--td-surface) 90%, black); box-shadow: inset 2px 2px 4px rgba(82,70,54,.20), inset -1px -1px 2px rgba(255,255,255,.7); transition: background 160ms; }\n.td-switch-thumb { width: 16px; height: 16px; border-radius: 999px; background: var(--td-surface); box-shadow: 1px 1px 3px rgba(82,70,54,.30), inset 0 1px 0 rgba(255,255,255,.85); transition: transform 160ms; }\n.td-switch input:checked + .td-switch-track { background: var(--td-brand); }\n.td-switch input:checked + .td-switch-track .td-switch-thumb { transform: translateX(16px); }\n.td-switch input:focus-visible + .td-switch-track { outline: 2px solid var(--td-accent); outline-offset: 2px; }\n.td-switch[data-disabled="true"] { opacity: .55; cursor: not-allowed; }`},
 tooltip:{html:`<span class="td-tooltip-wrap">\n  <button type="button" class="td-primary" aria-describedby="tip">Hover or focus</button>\n  <span id="tip" role="tooltip" class="td-tooltip">Opens guidance</span>\n</span>`,css:`.td-tooltip-wrap { position: relative; display: inline-block; }\n.td-tooltip { position: absolute; bottom: calc(100% + 8px); left: 50%; transform: translateX(-50%); display: none; padding: 6px 10px; border-radius: 8px; background: var(--td-ink); color: var(--td-surface); font: 12px var(--td-font-ui); white-space: nowrap; box-shadow: 3px 4px 8px rgba(82,70,54,.28); }\n.td-tooltip::after { content: ""; position: absolute; top: 100%; left: 50%; transform: translateX(-50%); border: 4px solid transparent; border-top-color: var(--td-ink); }\n.td-tooltip-wrap:hover .td-tooltip,\n.td-tooltip-wrap:focus-within .td-tooltip,\n.td-tooltip-wrap[data-state="open"] .td-tooltip { display: block; }`},
 alert:{html:`<div class="td-alert td-alert--success" role="status">\n  <span class="td-alert-icon" aria-hidden="true">●</span>\n  <div><strong>Saved</strong><p>Your changes are available.</p></div>\n</div>`,css:`.td-alert { display: grid; grid-template-columns: auto 1fr auto; align-items: start; gap: 12px; max-width: 520px; padding: 15px 16px; border: 1px solid var(--td-edge); border-left-width: 4px; border-radius: 12px; background: var(--td-surface); box-shadow: 3px 4px 10px rgba(82,70,54,.16), -3px -3px 8px rgba(255,255,255,.72); }\n.td-alert strong { color: var(--td-ink); font-size: 14px; font-weight: 600; }\n.td-alert p { margin: 4px 0 0; color: var(--td-ink-2); font-size: 13px; }\n.td-alert-icon { font-size: 12px; line-height: 1.6; }\n.td-alert-close { appearance: none; border: 0; background: transparent; color: var(--td-ink-2); font-size: 18px; line-height: 1; padding: 4px 8px; border-radius: 6px; cursor: pointer; }\n.td-alert-close:hover { color: var(--td-ink); background: color-mix(in srgb, var(--td-surface) 92%, black); }\n.td-alert--info { border-left-color: var(--td-accent); }\n.td-alert--info .td-alert-icon { color: var(--td-accent); }\n.td-alert--success { border-left-color: var(--td-green); }\n.td-alert--success .td-alert-icon { color: var(--td-green-text); }\n.td-alert--warning { border-left-color: var(--td-brand); }\n.td-alert--warning .td-alert-icon { color: var(--td-brand-text); }\n.td-alert--error { border-left-color: var(--td-error-text); }\n.td-alert--error .td-alert-icon { color: var(--td-error-text); }`},
 forms:{html:`<div class="td-field">\n  <label class="td-label" for="work-email">Work email <span>*</span></label>\n  <span class="td-input-wrap"><input id="work-email" class="td-input" type="email" placeholder="name@company.com" aria-describedby="work-email-help"></span>\n  <p class="td-helper" id="work-email-help">Used only for notifications</p>\n</div>`,css:`.td-field { display: grid; gap: 8px; max-width: 420px; }\n.td-label { color: var(--td-ink); font-size: 13px; font-weight: 700; }\n.td-label span { color: var(--td-brand); }\n.td-input-wrap { display: flex; align-items: center; min-height: 42px; padding: 0 13px; border: 1px solid var(--td-edge); border-radius: 12px; background: var(--td-surface); box-shadow: inset 2px 2px 5px rgba(82,70,54,.18), inset -2px -2px 5px rgba(255,255,255,.75); }\n.td-input { width: 100%; border: 0; outline: 0; background: transparent; color: var(--td-ink); font: 14px var(--td-font-ui); }\n.td-input::placeholder { color: var(--td-ink-3); }\n.td-input-wrap:focus-within { border-color: var(--td-accent); box-shadow: 0 0 0 2px color-mix(in srgb, var(--td-accent) 25%, transparent); }\n.td-helper { margin: 0; color: var(--td-ink-2); font-size: 12px; }`},
 tabs:{html:`<div class="td-tabs">\n  <div class="td-tablist" role="tablist" aria-label="Project sections">\n    <button class="td-tab" role="tab" aria-selected="true">Overview</button>\n    <button class="td-tab" role="tab" aria-selected="false">Activity</button>\n  </div>\n  <div class="td-tabpanel" role="tabpanel">Current project status and ownership.</div>\n</div>`,css:`.td-tabs { max-width: 560px; }\n.td-tablist { display: inline-flex; gap: 4px; padding: 5px; border-radius: 12px; background: var(--td-surface-2); box-shadow: inset 2px 2px 5px rgba(82,70,54,.18), inset -1px -1px 3px rgba(255,255,255,.7); }\n.td-tab { min-height: 36px; padding: 0 14px; border: 0; border-radius: 9px; background: transparent; color: var(--td-ink-2); font: 600 13px var(--td-font-ui); cursor: pointer; }\n.td-tab[aria-selected="true"] { background: var(--td-surface); color: var(--td-brand-text); box-shadow: 2px 2px 5px rgba(82,70,54,.18), -2px -2px 4px rgba(255,255,255,.75); }\n.td-tab:focus-visible { outline: 2px solid var(--td-accent); outline-offset: 2px; }\n.td-tabpanel { padding: 20px 4px; color: var(--td-ink-2); line-height: 1.6; }`},
 feedback:{html:`<div class="td-alert td-alert--success" role="status">\n  <span class="td-alert-icon" aria-hidden="true">●</span>\n  <div><strong>Saved</strong><p>Your changes are available.</p></div>\n</div>`,css:`.td-alert { display: grid; grid-template-columns: auto 1fr; gap: 12px; max-width: 520px; padding: 15px 16px; border: 1px solid var(--td-edge); border-radius: 12px; background: var(--td-surface); box-shadow: 3px 4px 10px rgba(82,70,54,.16), -3px -3px 8px rgba(255,255,255,.72); }\n.td-alert-icon { color: var(--td-green-text); font-size: 12px; line-height: 1.6; }\n.td-alert strong { color: var(--td-ink); font-size: 14px; }\n.td-alert p { margin: 4px 0 0; color: var(--td-ink-2); font-size: 13px; }\n.td-alert--success { border-left: 4px solid var(--td-green); }`},
 table:{html:`<div class="td-table-wrap">\n  <table class="td-table">\n    <thead><tr><th scope="col">Package</th><th scope="col">Status</th></tr></thead>\n    <tbody><tr><td>React</td><td><span>Verified</span></td></tr><tr><td>Vue</td><td>Prepared</td></tr></tbody>\n  </table>\n</div>`,css:`.td-table-wrap { max-width: 680px; overflow-x: auto; border: 1px solid var(--td-edge); border-radius: 12px; background: var(--td-surface); box-shadow: 4px 5px 12px rgba(82,70,54,.16), -3px -4px 10px rgba(255,255,255,.72); }\n.td-table { width: 100%; border-collapse: collapse; font-size: 13px; }\n.td-table th { padding: 12px 16px; background: color-mix(in srgb, var(--td-surface) 92%, black); color: var(--td-ink-2); font-size: 11px; text-align: left; text-transform: uppercase; letter-spacing: .08em; }\n.td-table td { padding: 14px 16px; border-top: 1px solid var(--td-edge); color: var(--td-ink); }\n.td-table td span { color: var(--td-green-text); font-weight: 700; }\n.td-table tbody tr:hover { background: color-mix(in srgb, var(--td-surface) 96%, var(--td-brand)); }`},
 kpi:{html:`<div class="td-kpi-grid">\n  <article class="td-kpi">\n    <span class="td-kpi-eyebrow">Open</span>\n    <strong class="td-kpi-value">42</strong>\n    <span class="td-kpi-delta td-kpi-delta--up">+6</span>\n  </article>\n</div>`,css:`.td-kpi-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 16px; max-width: 760px; }\n.td-kpi { display: grid; gap: 8px; padding: 20px; border: 1px solid var(--td-edge); border-radius: 12px; background: var(--td-surface); box-shadow: 4px 5px 12px rgba(82,70,54,.18), -4px -5px 10px rgba(255,255,255,.8); }\n.td-kpi-eyebrow { color: var(--td-ink-2); font: 700 10px var(--td-font-mono); text-transform: uppercase; letter-spacing: .1em; }\n.td-kpi-value { color: var(--td-ink); font-family: var(--td-font-display); font-size: 36px; font-weight: 400; line-height: 1; }\n.td-kpi-delta { width: fit-content; padding: 3px 7px; border-radius: 999px; font-size: 11px; font-weight: 700; }\n.td-kpi-delta--up { background: color-mix(in srgb, var(--td-green) 18%, transparent); color: var(--td-green-text); }`},
 dialog:{html:`<div class="td-overlay-backdrop" data-state="open">\n  <div class="td-modal" role="dialog" aria-modal="true" aria-labelledby="title" tabindex="-1">\n    <div class="td-modal-head"><h2 id="title" class="td-modal-title">Delete project</h2><button type="button" class="td-alert-close" aria-label="Close dialog">×</button></div>\n    <p class="td-modal-desc">This action cannot be undone.</p>\n    <div class="td-modal-actions"><button type="button" class="td-primary">Cancel</button><button type="button" class="td-coloured">Delete</button></div>\n  </div>\n</div>`,css:`.td-overlay-backdrop { position: fixed; inset: 0; display: grid; place-items: center; padding: 24px; background: color-mix(in srgb, var(--td-ink) 42%, transparent); backdrop-filter: blur(3px); z-index: 200; }\n.td-modal { max-width: 480px; width: 100%; padding: 24px; border: 1px solid var(--td-edge); border-radius: 14px; background: var(--td-surface); box-shadow: 6px 8px 22px rgba(82,70,54,.28), -3px -3px 10px rgba(255,255,255,.65); display: grid; gap: 16px; }\n.td-modal-head { display: flex; align-items: start; justify-content: space-between; gap: 12px; }\n.td-modal-title { margin: 0; font-family: var(--td-font-display); font-size: 22px; font-weight: 400; color: var(--td-ink); }\n.td-modal-desc { margin: 0; color: var(--td-ink-2); font-size: 13px; }\n.td-modal-actions { display: flex; justify-content: flex-end; gap: 8px; }\n.td-alert-close { appearance: none; border: 0; background: transparent; color: var(--td-ink-2); font-size: 20px; padding: 4px 8px; border-radius: 6px; cursor: pointer; }`},
 "dropdown-menu":{html:`<div class="td-dropdown" data-state="open">\n  <button type="button" class="td-dropdown-trigger" aria-haspopup="menu" aria-expanded="true">\n    <span class="td-dropdown-value">Standard</span><span class="td-dropdown-chevron" aria-hidden="true">⌄</span>\n  </button>\n  <div role="menu" class="td-dropdown-menu">\n    <button type="button" role="menuitemradio" aria-checked="true" class="td-dropdown-item"><span class="td-dropdown-check" aria-hidden="true">✓</span>Standard</button>\n    <button type="button" role="menuitemradio" aria-checked="false" class="td-dropdown-item"><span class="td-dropdown-check" aria-hidden="true">✓</span>Express</button>\n  </div>\n</div>`,css:`.td-dropdown { position: relative; display: inline-flex; }\n.td-dropdown-trigger { display: inline-flex; align-items: center; gap: 8px; min-height: 40px; padding: 0 12px; border: 1px solid var(--td-edge); border-radius: 10px; background: var(--td-surface); color: var(--td-ink); font: 13px var(--td-font-ui); cursor: pointer; box-shadow: 2px 2px 5px rgba(82,70,54,.15), -2px -2px 4px rgba(255,255,255,.7); }\n.td-dropdown-menu { position: absolute; top: calc(100% + 6px); left: 0; min-width: 180px; padding: 6px; border: 1px solid var(--td-edge); border-radius: 10px; background: var(--td-surface); box-shadow: 4px 6px 16px rgba(82,70,54,.22); display: none; z-index: 20; }\n.td-dropdown[data-state="open"] .td-dropdown-menu { display: grid; gap: 2px; }\n.td-dropdown-item { display: flex; align-items: center; gap: 8px; padding: 6px 10px; border: 0; border-radius: 6px; background: transparent; color: var(--td-ink); font: 13px var(--td-font-ui); cursor: pointer; text-align: left; }\n.td-dropdown-item:hover { background: color-mix(in srgb, var(--td-surface) 90%, black); }\n.td-dropdown-item[aria-checked="true"] { color: var(--td-brand-text); font-weight: 600; }\n.td-dropdown-check { visibility: hidden; color: var(--td-brand); }\n.td-dropdown-item[aria-checked="true"] .td-dropdown-check { visibility: visible; }`},
 toast:{html:`<div class="td-react-toast-viewport" aria-live="polite">\n  <div class="td-toast td-toast--success" role="status">\n    <span class="td-toast-dot" aria-hidden="true"></span>\n    <div><strong>Saved</strong><p>Your changes are safe.</p></div>\n    <button type="button" class="td-toast-close" aria-label="Dismiss notification">×</button>\n  </div>\n</div>`,css:`.td-react-toast-viewport { position: fixed; right: 24px; bottom: 24px; z-index: 300; display: flex; flex-direction: column; gap: 8px; width: min(360px, calc(100vw - 32px)); }\n.td-toast { display: grid; grid-template-columns: auto 1fr auto; align-items: start; gap: 12px; padding: 12px 14px; border: 1px solid var(--td-edge); border-radius: 12px; background: var(--td-surface); box-shadow: 3px 5px 12px rgba(82,70,54,.22); }\n.td-toast strong { color: var(--td-ink); font-size: 13px; font-weight: 600; }\n.td-toast p { margin: 3px 0 0; color: var(--td-ink-2); font-size: 12px; }\n.td-toast-dot { width: 8px; height: 8px; margin-top: 6px; border-radius: 999px; background: var(--td-accent); }\n.td-toast--success .td-toast-dot { background: var(--td-green); }\n.td-toast--error .td-toast-dot { background: var(--td-error); }\n.td-toast-close { appearance: none; border: 0; background: transparent; color: var(--td-ink-2); font-size: 18px; cursor: pointer; }`},
 "chart-container":{html:`<figure class="td-chart-card">\n  <figcaption class="td-chart-card-head">\n    <span class="td-chart-card-title">Weekly signups</span>\n    <span class="td-chart-card-meta">Q3</span>\n  </figcaption>\n  <div class="td-chart-svg-wrap">\n    <svg viewBox="0 0 200 60" style="width:100%;height:120px;color:var(--td-brand)"><polyline fill="none" stroke="currentColor" stroke-width="2" points="0,50 40,40 80,20 120,30 160,10 200,25"/></svg>\n  </div>\n  <div class="td-chart-legend" aria-label="Chart legend">\n    <span class="td-chart-legend-item"><span class="td-chart-legend-swatch" style="background:var(--td-brand)"></span>This week</span>\n    <span class="td-chart-legend-item"><span class="td-chart-legend-swatch" style="background:var(--td-accent)"></span>Last week</span>\n  </div>\n</figure>`,css:`.td-chart-card { margin: 0; padding: 20px; border: 1px solid var(--td-edge); border-radius: 14px; background: var(--td-surface); box-shadow: 4px 5px 14px rgba(82,70,54,.18), -3px -4px 10px rgba(255,255,255,.75); display: grid; gap: 14px; }\n.td-chart-card-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }\n.td-chart-card-title { font-family: var(--td-font-display); font-size: 20px; color: var(--td-ink); }\n.td-chart-card-meta { font: 700 10px var(--td-font-mono); text-transform: uppercase; letter-spacing: .1em; color: var(--td-ink-2); }\n.td-chart-svg-wrap { min-height: 120px; }\n.td-chart-legend { display: flex; gap: 16px; flex-wrap: wrap; font: 12px var(--td-font-ui); color: var(--td-ink-2); }\n.td-chart-legend-item { display: inline-flex; align-items: center; gap: 6px; }\n.td-chart-legend-swatch { width: 10px; height: 10px; border-radius: 3px; }\n.td-react-visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }`},
 "filter-bar":{html:`<div class="td-filters" role="group" aria-label="Filters">\n  <button type="button" class="td-filter-chip" aria-pressed="true" data-color="brand">Open <span class="td-filter-chip-count">42</span></button>\n  <button type="button" class="td-filter-chip" aria-pressed="false">In review <span class="td-filter-chip-count">12</span></button>\n  <button type="button" class="td-filters-clear">Clear filters <span aria-hidden="true">×</span></button>\n</div>`,css:`.td-filters { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; padding: 10px 12px; border: 1px solid var(--td-edge); border-radius: 12px; background: var(--td-surface); }\n.td-filter-chip { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border: 1px solid var(--td-edge); border-radius: 999px; background: transparent; color: var(--td-ink-2); font: 12px var(--td-font-ui); cursor: pointer; }\n.td-filter-chip[aria-pressed="true"] { background: var(--td-surface); color: var(--td-ink); font-weight: 600; box-shadow: 1px 2px 4px rgba(82,70,54,.18); }\n.td-filter-chip[data-color="brand"][aria-pressed="true"] { color: var(--td-brand-text); border-color: color-mix(in srgb, var(--td-brand) 45%, transparent); }\n.td-filter-chip[data-color="accent"][aria-pressed="true"] { color: var(--td-accent-text); border-color: color-mix(in srgb, var(--td-accent) 45%, transparent); }\n.td-filter-chip-count { font-family: var(--td-font-mono); font-size: 11px; opacity: .8; }\n.td-filters-clear { display: inline-flex; align-items: center; gap: 4px; padding: 4px 10px; border: 0; background: transparent; color: var(--td-ink-2); font: 12px var(--td-font-ui); cursor: pointer; }`},
 "desktop-navigation":{html:`<header class="td-nav-wrap">\n  <nav class="td-navbar" aria-label="Primary navigation">\n    <div class="td-react-nav-brand">TD</div>\n    <div class="td-navlinks">\n      <a href="#" class="td-navbtn" aria-current="page">Dashboard</a>\n      <a href="#" class="td-navbtn">Projects</a>\n      <a href="#" class="td-navbtn">Reports</a>\n    </div>\n    <div class="td-nav-right"><button class="td-coloured">New project</button></div>\n  </nav>\n</header>`,css:`.td-nav-wrap { background: var(--td-surface); border-bottom: 1px solid var(--td-edge); box-shadow: 0 3px 8px rgba(82,70,54,.10); }\n.td-navbar { display: flex; align-items: center; gap: 24px; max-width: 1160px; margin: 0 auto; padding: 12px 20px; }\n.td-react-nav-brand { font-family: var(--td-font-display); font-size: 24px; color: var(--td-ink); flex: 0 0 auto; }\n.td-navlinks { display: flex; gap: 4px; flex: 1 1 auto; }\n.td-navbtn { display: inline-flex; align-items: center; padding: 8px 12px; border-radius: 8px; text-decoration: none; color: var(--td-ink-2); font: 13px var(--td-font-ui); }\n.td-navbtn[aria-current="page"] { color: var(--td-brand-text); background: color-mix(in srgb, var(--td-brand) 10%, transparent); font-weight: 600; }\n.td-navbtn[aria-disabled="true"] { opacity: .45; pointer-events: none; }\n.td-nav-right { flex: 0 0 auto; }`},
 "application-shell":{html:`<div class="td-shell">\n  <aside class="td-sidebar">\n    <div class="td-sb-head"><b>Acme</b></div>\n    <nav>\n      <div class="td-sb-section">\n        <div class="td-sb-label">Work</div>\n        <a href="#" class="td-sb-item" aria-current="page">Dashboard</a>\n        <a href="#" class="td-sb-item">Projects <span class="td-sb-item-count">12</span></a>\n      </div>\n    </nav>\n  </aside>\n  <main class="td-main">\n    <header class="td-page-head">\n      <div><h1 class="td-page-title">Overview</h1><p class="td-page-sub">Signals from every workspace.</p></div>\n    </header>\n    <p>Content lives here.</p>\n  </main>\n</div>`,css:`.td-shell { display: grid; grid-template-columns: 260px 1fr; min-height: 100vh; background: var(--td-bg); }\n.td-sidebar { border-right: 1px solid var(--td-edge); background: var(--td-surface); padding: 20px 16px; display: flex; flex-direction: column; gap: 20px; }\n.td-sb-head { font-family: var(--td-font-display); font-size: 22px; color: var(--td-ink); }\n.td-sb-label { font: 700 10px var(--td-font-mono); text-transform: uppercase; letter-spacing: .1em; color: var(--td-ink-3); margin-bottom: 6px; }\n.td-sb-section { display: flex; flex-direction: column; gap: 2px; }\n.td-sb-item { display: flex; align-items: center; justify-content: space-between; padding: 8px 10px; border-radius: 8px; text-decoration: none; color: var(--td-ink-2); font: 13px var(--td-font-ui); }\n.td-sb-item[aria-current="page"] { background: color-mix(in srgb, var(--td-brand) 10%, transparent); color: var(--td-brand-text); font-weight: 600; }\n.td-sb-item-count { font-family: var(--td-font-mono); font-size: 11px; color: var(--td-ink-3); }\n.td-main { padding: 28px 32px; display: flex; flex-direction: column; gap: 20px; }\n.td-page-head { display: flex; align-items: start; justify-content: space-between; gap: 16px; }\n.td-page-title { margin: 0; font-family: var(--td-font-display); font-size: 32px; color: var(--td-ink); }\n.td-page-sub { margin: 4px 0 0; color: var(--td-ink-2); font-size: 13px; }`},
 "page-patterns":{html:`<section class="td-react-page-pattern">\n  <header class="td-page-head"><div><h2 class="td-page-title">Overview</h2><p class="td-page-sub">Signals across every workspace.</p></div></header>\n  <div class="td-react-pattern-metrics">\n    <div class="td-kpi-grid">\n      <article class="td-kpi"><span class="td-kpi-eyebrow">Open</span><strong class="td-kpi-value">42</strong></article>\n      <article class="td-kpi"><span class="td-kpi-eyebrow">Resolved</span><strong class="td-kpi-value">128</strong></article>\n    </div>\n  </div>\n  <div class="td-bento">\n    <article class="td-panel td-bento-cell--span-full">\n      <header class="td-panel-head"><h3 class="td-panel-title">Recent activity</h3></header>\n      Signals appear here.\n    </article>\n  </div>\n</section>`,css:`.td-react-page-pattern { display: flex; flex-direction: column; gap: 20px; }\n.td-react-pattern-metrics { display: block; }\n.td-bento { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }\n.td-bento-cell--span2 { grid-column: span 2; }\n.td-bento-cell--span-full { grid-column: 1 / -1; }\n.td-empty { display: grid; place-items: center; gap: 12px; padding: 32px; border: 1px dashed var(--td-edge); border-radius: 14px; text-align: center; background: var(--td-surface); color: var(--td-ink-2); }\n.td-empty-title { color: var(--td-ink); font-family: var(--td-font-display); font-size: 20px; }\n.td-loading-dots { display: inline-flex; gap: 6px; }\n.td-loading-dots span { width: 8px; height: 8px; border-radius: 999px; background: var(--td-ink-3); animation: td-loading 900ms infinite alternate; }\n.td-loading-dots span:nth-child(2) { animation-delay: 180ms; }\n.td-loading-dots span:nth-child(3) { animation-delay: 360ms; }\n@keyframes td-loading { to { transform: translateY(-4px); opacity: 1; } }`}
};
function LanguageCode({doc}:{doc:Doc}){const[language,setLanguage]=useState<CodeLanguage>("react");const[includeBase,setIncludeBase]=useState(false);const baseCss=language==="css"&&includeBase?`${standaloneBase}\n\n`:"";const code=language==="react"?doc.code:language==="html"?snippets[doc.id].html:`${baseCss}${snippets[doc.id].css}`;return <div className="language-code"><div className="language-row"><label>Code language<select aria-label="Code language" value={language} onChange={event=>setLanguage(event.target.value as CodeLanguage)}><option value="react">React / TSX</option><option value="html">HTML</option><option value="css">CSS</option></select></label>{language==="css"?<label className="include-base"><input type="checkbox" checked={includeBase} onChange={event=>setIncludeBase(event.target.checked)}/> Include base tokens (for a standalone visualizer without <code>@tonaldepth/tokens</code>)</label>:null}</div><Code label={language==="react"?"tsx":language}>{code}</Code></div>}
type Runner="npm"|"pnpm"|"yarn"|"bun";
const runners:Record<Runner,{setup:string;add:string}>={npm:{setup:"npx shadcn@latest registry add",add:"npx shadcn@latest add"},pnpm:{setup:"pnpm dlx shadcn@latest registry add",add:"pnpm dlx shadcn@latest add"},yarn:{setup:"yarn dlx shadcn@latest registry add",add:"yarn dlx shadcn@latest add"},bun:{setup:"bunx --bun shadcn@latest registry add",add:"bunx --bun shadcn@latest add"}};
function RunnerPicker({runner,setRunner}:{runner:Runner;setRunner:(r:Runner)=>void}){return <div className="runner" aria-label="Package manager">{(["npm","pnpm","yarn","bun"] as Runner[]).map(value=><button className={runner===value?"selected":""} onClick={()=>setRunner(value)} key={value}>{value}</button>)}</div>}
const ALL_COMPONENTS="@tonaldepth/button @tonaldepth/badge @tonaldepth/card @tonaldepth/input @tonaldepth/textarea @tonaldepth/form-field @tonaldepth/checkbox @tonaldepth/radio @tonaldepth/switch @tonaldepth/alert @tonaldepth/tabs @tonaldepth/table @tonaldepth/kpi @tonaldepth/tooltip @tonaldepth/dialog @tonaldepth/dropdown-menu @tonaldepth/toast @tonaldepth/chart-container @tonaldepth/filter-bar @tonaldepth/desktop-navigation @tonaldepth/application-shell @tonaldepth/page-patterns @tonaldepth/icon-button @tonaldepth/site-navigation @tonaldepth/footer @tonaldepth/article-card @tonaldepth/case-card @tonaldepth/feature-card @tonaldepth/comparison-table @tonaldepth/cta-banner @tonaldepth/timeline @tonaldepth/prose @tonaldepth/rect-title @tonaldepth/filament-button @tonaldepth/side-tabs @tonaldepth/split-button @tonaldepth/search-bar @tonaldepth/frame";
const REGISTRY_ORIGIN=typeof window!=="undefined"?window.location.origin:"http://127.0.0.1:4176";
/* ── RectTitle playground ───────────────────────────────────────────────────
   The rectangle is a *fit*, so a static preview cannot show what the knobs do.
   Type a headline, move the line count, swap the ink, and watch it re-square. */
const RECT_TONES=["ink","muted","brand","accent","green","error"] as const;
/* The specimen wall.

   One playground with one headline shows how the controls work and nothing
   about how the TREATMENT behaves — and the treatment is the component. A
   two-word line and a fourteen-word line are different problems for a fitter
   that scales every line to the longest one, and h1 against h3 is a different
   problem again, because the smaller the type the less a ragged edge is
   forgiven. So the wall is real headlines of real different lengths at every
   level, each captioned with what it is demonstrating. */
const RECT_SPECIMENS:{caption:string;text:string;level:1|2|3;lines?:number;maxLines?:number;force?:boolean;tones?:readonly ("ink"|"muted"|"brand"|"accent"|"green"|"error")[]}[]=[
  {caption:"h1 · two lines · the short ask",text:"Talk to a principal consultant.",level:1,lines:2,tones:["ink","brand"]},
  {caption:"h1 · three lines · a long headline the splitter has to balance",text:"We implement ERPNext for companies that have outgrown the spreadsheet they were run on.",level:1,lines:3,tones:["ink","ink","brand"]},
  {caption:"h1 · four lines · a manifesto, one tone stepped down the middle",text:"Own your source. Own your data. Own the schedule you ship on. Nobody sends you an invoice for a seat.",level:1,lines:4,tones:["ink","brand","ink","muted"]},
  {caption:"h2 · two lines · a section head, set against the h1 above it",text:"Nine to sixteen weeks, discovery to go-live.",level:2,lines:2,tones:["muted","ink"]},
  {caption:"h2 · two words · what the fitter refuses to do",text:"No licence.",level:2,lines:2,tones:["ink","brand"]},
  {caption:"h3 · three lines · the smallest level, where a ragged edge shows most",text:"Every rule ships in the item itself, so nothing imports from a private registry.",level:3,lines:3,tones:["ink","muted","ink"]},
];

/* The SearchBar preview searches these docs for real.

   A field wired to nothing shows the shape and none of the behaviour — the
   panel, the arrow keys, `aria-activedescendant` moving through it, Escape
   closing the list without clearing the query. Wiring it to the index the rest
   of the page already uses costs one function and makes the preview the thing
   it documents. */
function SearchBarBench({size,placeholder,expand,block=true}:{size?:"sm"|"md"|"lg";placeholder?:string;expand?:boolean;block?:boolean}){
 const[query,setQuery]=useState("");
 const hits=useMemo(()=>runSearch(query).slice(0,6),[query]);
 return <SearchBar
  size={size}
  block={block}
  expand={expand}
  value={query}
  onValueChange={setQuery}
  placeholder={placeholder}
  suggestions={hits.map(hit=>({id:hit.doc.id,label:hit.doc.name,detail:hit.why}))}
  onSuggestionSelect={suggestion=>{location.hash=`#${suggestion.id}`;setQuery("")}}
  onSubmit={()=>{if(hits[0])location.hash=`#${hits[0].doc.id}`}}
 />;
}

function RectTitleSpecimens(){
  const[force,setForce]=useState(true);
  return <div style={{display:"grid",gap:26}}>
    <div className="row" style={{alignItems:"center",gap:16}}>
      <Checkbox label="forceRectangle on every specimen" checked={force} onChange={e=>setForce(e.target.checked)}/>
      <span className="hint" style={{margin:0}}>Turn it off and watch which of these go ragged — it is the short ones, because the fitter stops at 1.5x.</span>
    </div>
    {RECT_SPECIMENS.map(spec=><div key={spec.caption}>
      <p className="sub" style={{margin:"0 0 10px",fontFamily:"var(--td-font-mono)",fontSize:"0.62rem",letterSpacing:"0.14em",textTransform:"uppercase"}}>{spec.caption}</p>
      <RectTitle text={spec.text} level={spec.level} lines={spec.lines} maxLines={spec.maxLines}
        forceRectangle={force} tones={spec.tones as never}/>
    </div>)}
  </div>;
}

function RectTitlePlayground(){
  const[text,setText]=useState("Talk to a principal consultant.");
  const[maxLines,setMaxLines]=useState(2);
  /* 0 is "let the splitter decide" — the prop itself is simply not passed. */
  const[exact,setExact]=useState(0);
  const[level,setLevel]=useState<1|2|3>(1);
  const[force,setForce]=useState(false);
  const[tones,setTones]=useState<string[]>(["ink","brand"]);
  const lines=splitRectTitle(text||" ",maxLines,exact||undefined);
  const setTone=(i:number,value:string)=>setTones(current=>{const next=[...current];while(next.length<=i)next.push("ink");next[i]=value;return next});
  return <div className="playground">
    <div className="playground-controls">
      <label className="pg-field"><span>Headline <small>press Enter to break where you want</small></span>
        <Textarea rows={2} value={text} onChange={e=>setText(e.target.value)} placeholder="Type a headline"/></label>
      <Range className="pg-range" label="Max lines" min={2} max={6} step={1} value={maxLines}
        format={v=>`${v} · got ${lines.length}`} disabled={exact>0||text.includes("\n")}
        onChange={e=>setMaxLines(Number(e.target.value))}/>
      <Range className="pg-range" label="Exact lines" min={0} max={6} step={1} value={exact}
        format={v=>v?String(v):"auto"} disabled={text.includes("\n")}
        onChange={e=>setExact(Number(e.target.value))}/>
      <label className="pg-field"><span>Level</span>
        <select value={level} onChange={e=>setLevel(Number(e.target.value) as 1|2|3)}>
          <option value={1}>h1</option><option value={2}>h2</option><option value={3}>h3</option></select></label>
      <Checkbox label="forceRectangle" checked={force} onChange={e=>setForce(e.target.checked)}/>
    </div>
    <div className="playground-tones">
      {lines.map((line:string,i:number)=><label className="pg-tone" key={i}>
        <span title={line}>Line {i+1}</span>
        <select value={tones[Math.min(i,tones.length-1)]??"ink"} onChange={e=>setTone(i,e.target.value)}>
          {RECT_TONES.map(t=><option key={t} value={t}>{t}</option>)}</select></label>)}
    </div>
    <div className="preview"><span>Live React component</span>
      <RectTitle text={text||"Type a headline"} level={level} maxLines={maxLines} lines={exact||undefined}
        forceRectangle={force} tones={lines.map((_l:string,i:number)=>(tones[Math.min(i,tones.length-1)]??"ink") as never)}/></div>
    <p className="hint"><strong>Three ways to decide the lines, and they win in this order.</strong> A newline in the headline is an explicit break and beats everything — press Enter in the field above and both sliders go inert. <code>lines</code> asks for an exact count. Otherwise the splitter chooses, capped by <code>maxLines</code> <em>and</em> by a words-per-line heuristic — which is why raising <code>maxLines</code> on a short headline appears to do nothing, and why an exact count exists. Every line is then measured and scaled to the longest one; uncheck <code>forceRectangle</code> and a lopsided split stays slightly ragged, because the fitter stops at 1.5x so a two-word line cannot become a billboard.</p>
  </div>;
}
function InstallSelector({doc}:{doc:Doc}){const[runner,setRunner]=useState<Runner>("npm");const[showManual,setShowManual]=useState(false);const[source,setSource]=useState("Loading component source...");const registryReady=["button","badge","card","input","textarea","form-field","checkbox","radio","switch","alert","tabs","table","kpi","tooltip","dialog","dropdown-menu","toast","chart-container","filter-bar","desktop-navigation","application-shell","page-patterns","icon-button","site-navigation","footer","article-card","case-card","feature-card","comparison-table","cta-banner","timeline","prose","rect-title","filament-button","side-tabs","split-button","search-bar","frame"].includes(doc.id);useEffect(()=>{if(!showManual||!registryReady)return;fetch(`/r/${doc.id}.json`).then(x=>x.json()).then(x=>setSource(x.files.find((file:{path:string})=>file.path.endsWith(`${doc.id}.tsx`))?.content||"Source unavailable")).catch(()=>setSource("Source unavailable"))},[doc.id,registryReady,showManual]);if(!registryReady)return <Alert variant="info" title="Registry conversion pending">This component is verified in package mode. Its copy-to-source registry item has not been prepared yet.</Alert>;const addCmd=`${runners[runner].add} '@tonaldepth/${doc.id}'`;return <div className="installer"><RunnerPicker runner={runner} setRunner={setRunner}/><ol className="steps"><li><div className="step-head"><span className="step-num">1</span><strong>Add {doc.name} from the registry</strong></div><p>Shadcn will automatically install <code>@tonaldepth/tokens</code> if it isn't already in your project.</p><Code label="shell">{addCmd}</Code><p className="hint">Windows / PowerShell: keep the single quotes — <code>@</code> and <code>/</code> parse without them, but quoting is safest.</p></li><li><div className="step-head"><span className="step-num">2</span><strong>Use it in your app</strong></div><p>The component was copied into <code>components/ui/tonaldepth-{doc.id}.tsx</code>. Import and render:</p><Code>{doc.code}</Code></li></ol><details className="fallback"><summary onClick={()=>setShowManual(!showManual)}>Prefer to copy the source manually?</summary><p>Create <code>components/ui/tonaldepth-{doc.id}.tsx</code> in your project and paste the code below. Make sure the tokens from <code>@tonaldepth/tokens</code> are loaded on your page.</p><Code>{source}</Code></details></div>}
